/// Que se eligio del modelo.
#[derive(Clone)]
struct Selection {
    dimensions: Vec<ObjectId>,
    legend: Option<ObjectId>,
    measures: Vec<ObjectId>,
    implicit_measures: Vec<ImplicitMeasure>,
    value_order: Vec<ValueSelection>,
}

impl Selection {
    fn value_is_selected(&self, value: ValueSelection) -> bool {
        match value {
            ValueSelection::Measure(id) => self.measures.contains(&id),
            ValueSelection::Implicit(column, aggregation) => self
                .implicit_measures
                .iter()
                .any(|measure| measure.column == column && measure.aggregation == aggregation),
        }
    }

    fn has_implicit_column_at_ordered_role(&self, index: usize, column: ObjectId) -> bool {
        let value = if self.value_order.is_empty() {
            self.measures
                .iter()
                .copied()
                .map(ValueSelection::Measure)
                .chain(
                    self.implicit_measures
                        .iter()
                        .map(|measure| measure.selection()),
                )
                .nth(index)
        } else {
            self.value_order.get(index).copied()
        };
        matches!(value, Some(ValueSelection::Implicit(id, _)) if id == column)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ValueSelection {
    Measure(ObjectId),
    Implicit(ObjectId, Aggregation),
}

impl ImplicitMeasure {
    fn selection(self) -> ValueSelection {
        ValueSelection::Implicit(self.column, self.aggregation)
    }
}

