#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct GaugeFields {
    value: Option<ValueSelection>,
    minimum: Option<ValueSelection>,
    maximum: Option<ValueSelection>,
    target: Option<ValueSelection>,
}

impl GaugeFields {
    fn get(self, role: GaugeFieldRole) -> Option<ValueSelection> {
        match role {
            GaugeFieldRole::Value => self.value,
            GaugeFieldRole::Minimum => self.minimum,
            GaugeFieldRole::Maximum => self.maximum,
            GaugeFieldRole::Target => self.target,
        }
    }

    fn set(&mut self, role: GaugeFieldRole, value: Option<ValueSelection>) {
        match role {
            GaugeFieldRole::Value => self.value = value,
            GaugeFieldRole::Minimum => self.minimum = value,
            GaugeFieldRole::Maximum => self.maximum = value,
            GaugeFieldRole::Target => self.target = value,
        }
    }

    fn remove(&mut self, value: ValueSelection) {
        for role in [
            GaugeFieldRole::Value,
            GaugeFieldRole::Minimum,
            GaugeFieldRole::Maximum,
            GaugeFieldRole::Target,
        ] {
            if self.get(role) == Some(value) {
                self.set(role, None);
            }
        }
    }

    fn assign(&mut self, role: GaugeFieldRole, value: ValueSelection) -> Option<ValueSelection> {
        let previous = self.get(role);
        if previous == Some(value) {
            return None;
        }
        self.set(role, Some(value));
        previous.filter(|previous| {
            ![self.value, self.minimum, self.maximum, self.target].contains(&Some(*previous))
        })
    }
}

