fn siguiente_interaccion(
    current: datan_report::saved::SavedInteraction,
    target_supports_highlight: bool,
) -> datan_report::saved::SavedInteraction {
    use datan_report::saved::SavedInteraction;

    match (current, target_supports_highlight) {
        (SavedInteraction::Filter, true) => SavedInteraction::Highlight,
        (SavedInteraction::Filter, false) | (SavedInteraction::Highlight, _) => {
            SavedInteraction::Disabled
        }
        (SavedInteraction::Disabled, _) => SavedInteraction::Filter,
    }
}

fn dimensiones_seleccion(selection: &Selection) -> Vec<ObjectId> {
    selection
        .dimensions
        .iter()
        .copied()
        .chain(selection.legend)
        .collect()
}

fn etiquetas_leyenda(matrix: &datan_report::Matrix, selection: &Selection) -> Vec<String> {
    if selection.legend.is_none() {
        return Vec::new();
    }
    visuales::series_por_leyenda(matrix, dimensiones_seleccion(selection).len())
        .series
        .into_iter()
        .map(|series| series.etiqueta)
        .collect()
}

fn puede_agregar_valor(kind: &str, cantidad_actual: usize) -> bool {
    let roles = ordered_value_roles(kind);
    if !roles.is_empty() {
        return cantidad_actual < roles.len();
    }
    match kind {
        "KPI" => cantidad_actual < 2,
        "Sankey" => cantidad_actual < 1,
        _ => true,
    }
}

fn puede_agregar_dimension(kind: &str, cantidad_actual: usize) -> bool {
    match kind {
        "Sankey" => cantidad_actual < 2,
        "Candlestick" => cantidad_actual < 1,
        _ => true,
    }
}

