fn quitar_valor_seleccion(selection: &mut Selection, value: ValueSelection) {
    match value {
        ValueSelection::Measure(id) => selection.measures.retain(|measure| *measure != id),
        ValueSelection::Implicit(column, aggregation) => selection
            .implicit_measures
            .retain(|measure| measure.column != column || measure.aggregation != aggregation),
    }
    selection.value_order.retain(|current| *current != value);
}

impl Aggregation {
    fn saved(self) -> datan_report::saved::SavedAggregation {
        match self {
            Self::Sum => datan_report::saved::SavedAggregation::Sum,
            Self::Average => datan_report::saved::SavedAggregation::Average,
            Self::Count => datan_report::saved::SavedAggregation::Count,
            Self::CountRows => datan_report::saved::SavedAggregation::CountRows,
            Self::DistinctCount => datan_report::saved::SavedAggregation::DistinctCount,
            Self::Min => datan_report::saved::SavedAggregation::Min,
            Self::Max => datan_report::saved::SavedAggregation::Max,
            Self::First => datan_report::saved::SavedAggregation::First,
            Self::Last => datan_report::saved::SavedAggregation::Last,
            Self::Earliest => datan_report::saved::SavedAggregation::Earliest,
            Self::Latest => datan_report::saved::SavedAggregation::Latest,
            Self::Median => datan_report::saved::SavedAggregation::Median,
            Self::Variance => datan_report::saved::SavedAggregation::Variance,
            Self::StandardDeviation => datan_report::saved::SavedAggregation::StandardDeviation,
        }
    }

    fn from_saved(value: datan_report::saved::SavedAggregation) -> Self {
        match value {
            datan_report::saved::SavedAggregation::Sum => Self::Sum,
            datan_report::saved::SavedAggregation::Average => Self::Average,
            datan_report::saved::SavedAggregation::Count => Self::Count,
            datan_report::saved::SavedAggregation::CountRows => Self::CountRows,
            datan_report::saved::SavedAggregation::DistinctCount => Self::DistinctCount,
            datan_report::saved::SavedAggregation::Min => Self::Min,
            datan_report::saved::SavedAggregation::Max => Self::Max,
            datan_report::saved::SavedAggregation::First => Self::First,
            datan_report::saved::SavedAggregation::Last => Self::Last,
            datan_report::saved::SavedAggregation::Earliest => Self::Earliest,
            datan_report::saved::SavedAggregation::Latest => Self::Latest,
            datan_report::saved::SavedAggregation::Median => Self::Median,
            datan_report::saved::SavedAggregation::Variance => Self::Variance,
            datan_report::saved::SavedAggregation::StandardDeviation => Self::StandardDeviation,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Sum => "Suma",
            Self::Average => "Promedio",
            Self::Count => "Recuento",
            Self::CountRows => "Recuento de filas",
            Self::DistinctCount => "Recuento distinto",
            Self::Min => "Mínimo",
            Self::Max => "Máximo",
            Self::First => "Primero alfabético",
            Self::Last => "Último alfabético",
            Self::Earliest => "Más antiguo",
            Self::Latest => "Más reciente",
            Self::Median => "Mediana",
            Self::Variance => "Varianza",
            Self::StandardDeviation => "Desviación estándar",
        }
    }

    fn dax(self) -> &'static str {
        match self {
            Self::Sum => "SUM",
            Self::Average => "AVERAGE",
            Self::Count => "COUNTA",
            Self::CountRows => "COUNTROWS",
            Self::DistinctCount => "DISTINCTCOUNT",
            Self::Min => "MIN",
            Self::Max => "MAX",
            Self::First | Self::Earliest => "MIN",
            Self::Last | Self::Latest => "MAX",
            Self::Median => "MEDIAN",
            Self::Variance => "VAR.S",
            Self::StandardDeviation => "STDEV.S",
        }
    }

    fn default_for(data_type: DataType) -> Self {
        if data_type.is_numeric() {
            Self::Sum
        } else {
            Self::Count
        }
    }

    fn supports(self, data_type: DataType) -> bool {
        match self {
            Self::Sum
            | Self::Average
            | Self::Min
            | Self::Max
            | Self::Median
            | Self::Variance
            | Self::StandardDeviation => data_type.is_numeric(),
            Self::First | Self::Last => data_type == DataType::Text,
            Self::Earliest | Self::Latest => {
                matches!(data_type, DataType::Date | DataType::DateTime)
            }
            Self::Count | Self::CountRows | Self::DistinctCount => true,
        }
    }

    fn next_for_column(
        selection: &Selection,
        model: &Model,
        column: ObjectId,
        data_type: DataType,
    ) -> Option<Self> {
        let options = [
            Self::Sum,
            Self::Average,
            Self::Count,
            Self::DistinctCount,
            Self::CountRows,
            Self::Min,
            Self::Max,
            Self::First,
            Self::Last,
            Self::Earliest,
            Self::Latest,
            Self::Median,
            Self::Variance,
            Self::StandardDeviation,
        ];
        let current: Vec<_> = selection
            .implicit_measures
            .iter()
            .filter(|measure| {
                same_aggregation_target(model, measure.column, column, measure.aggregation)
            })
            .map(|measure| measure.aggregation)
            .collect();
        options
            .into_iter()
            .find(|option| option.supports(data_type) && !current.contains(option))
    }
}

fn cantidad_medidas(selection: &Selection) -> usize {
    selection.measures.len() + selection.implicit_measures.len()
}

/// Compara dos filas del grid por la columna de orden.
///
/// Una medida se ordena por numero: "9" es menor que "10", aunque el texto diga lo
/// contrario. Una dimension se ordena por texto, y el renglon en blanco queda primero en
/// ascendente, igual que en el panel de filtro.
fn comparar_filas_grid(
    a: &Vec<String>,
    b: &Vec<String>,
    column: usize,
    es_dimension: bool,
) -> std::cmp::Ordering {
    if es_dimension {
        a.get(column).cmp(&b.get(column))
    } else {
        let parse =
            |row: &Vec<String>| row.get(column).and_then(|value| value.parse::<f64>().ok());
        parse(a)
            .partial_cmp(&parse(b))
            .unwrap_or(std::cmp::Ordering::Equal)
    }
}

fn ordenar_medidas_visual(
    selection: &Selection,
    implicit_ids: &[(ImplicitMeasure, ObjectId)],
) -> Vec<ObjectId> {
    if selection.value_order.is_empty() {
        return selection
            .measures
            .iter()
            .copied()
            .chain(implicit_ids.iter().map(|(_, id)| *id))
            .collect();
    }
    selection
        .value_order
        .iter()
        .filter_map(|value| match value {
            ValueSelection::Measure(id) => selection.measures.contains(id).then_some(*id),
            ValueSelection::Implicit(column, aggregation) => implicit_ids
                .iter()
                .find(|(implicit, _)| {
                    implicit.column == *column && implicit.aggregation == *aggregation
                })
                .map(|(_, id)| *id),
        })
        .collect()
}

fn dax_quote_table(name: &str) -> String {
    format!("'{}'", name.replace('\'', "''"))
}

fn dax_quote_column(name: &str) -> String {
    format!("[{}]", name.replace(']', "]]"))
}

fn implicit_for_value(selection: &Selection, value: ValueSelection) -> Option<ImplicitMeasure> {
    let ValueSelection::Implicit(column, aggregation) = value else {
        return None;
    };
    selection
        .implicit_measures
        .iter()
        .find(|measure| measure.column == column && measure.aggregation == aggregation)
        .copied()
}

fn value_selection_key(value: ValueSelection) -> String {
    match value {
        ValueSelection::Measure(id) => format!("measure-{}", id.0),
        ValueSelection::Implicit(column, aggregation) => {
            format!("column-{}-{aggregation:?}", column.0)
        }
    }
}

fn aggregation_available(
    selection: &Selection,
    model: &Model,
    value: ValueSelection,
    aggregation: Aggregation,
) -> bool {
    let ValueSelection::Implicit(column, current) = value else {
        return false;
    };
    current == aggregation
        || !selection.implicit_measures.iter().any(|measure| {
            measure.aggregation == aggregation
                && same_aggregation_target(model, measure.column, column, aggregation)
        })
}

fn same_aggregation_target(
    model: &Model,
    left: ObjectId,
    right: ObjectId,
    aggregation: Aggregation,
) -> bool {
    if aggregation != Aggregation::CountRows {
        return left == right;
    }
    matches!((model.column(left), model.column(right)), (Some((left_table, _)), Some((right_table, _))) if left_table.id == right_table.id)
}

fn guardar_agregacion_implicita(
    report: &Report,
    implicit: ImplicitMeasure,
) -> Option<datan_report::saved::SavedImplicitMeasure> {
    let (table, column) = report.model.column(implicit.column)?;
    Some(datan_report::saved::SavedImplicitMeasure {
        column: datan_report::saved::SavedColumnRef::Qualified {
            table: table.name.clone(),
            column: column.name.clone(),
        },
        aggregation: implicit.aggregation.saved(),
        table: (implicit.aggregation == Aggregation::CountRows).then(|| table.name.clone()),
    })
}

fn expresion_agregacion(model: &Model, implicit: ImplicitMeasure) -> Option<String> {
    let (table, column) = model.column(implicit.column)?;
    if implicit.aggregation == Aggregation::CountRows {
        return Some(format!("COUNTROWS({})", dax_quote_table(&table.name)));
    }
    implicit.aggregation.supports(column.data_type).then(|| {
        format!(
            "{}({}{})",
            implicit.aggregation.dax(),
            dax_quote_table(&table.name),
            dax_quote_column(&column.name)
        )
    })
}

fn etiqueta_agregacion(model: &Model, implicit: ImplicitMeasure) -> Option<String> {
    let (table, column) = model.column(implicit.column)?;
    Some(if implicit.aggregation == Aggregation::CountRows {
        format!("{} · {}", implicit.aggregation.label(), table.name)
    } else {
        format!(
            "{} · {}.{}",
            implicit.aggregation.label(),
            table.name,
            column.name
        )
    })
}

