const LIENZO_ALTO_MINIMO: u32 = 480;
const LIENZO_MARGEN_INFERIOR: u32 = 32;
const LIENZO_ANCHO_PAGINA: u32 = 1280;
const LIENZO_ALTO_PAGINA: u32 = 720;

#[derive(Clone, Copy, PartialEq, Eq)]
enum CanvasPreset {
    Widescreen,
    Standard,
    Square,
    Portrait,
    Letter,
}

impl CanvasPreset {
    const ALL: [Self; 5] = [
        Self::Widescreen,
        Self::Standard,
        Self::Square,
        Self::Portrait,
        Self::Letter,
    ];

    fn size(self) -> datan_report::saved::CanvasSize {
        match self {
            Self::Widescreen => datan_report::saved::CanvasSize {
                width: 1280,
                height: 720,
            },
            Self::Standard => datan_report::saved::CanvasSize {
                width: 960,
                height: 720,
            },
            Self::Square => datan_report::saved::CanvasSize {
                width: 720,
                height: 720,
            },
            Self::Portrait => datan_report::saved::CanvasSize {
                width: 720,
                height: 1280,
            },
            Self::Letter => datan_report::saved::CanvasSize {
                width: 816,
                height: 1056,
            },
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Widescreen => "16:9",
            Self::Standard => "4:3",
            Self::Square => "Cuadrado",
            Self::Portrait => "Vertical 9:16",
            Self::Letter => "Carta",
        }
    }

    fn for_size(size: datan_report::saved::CanvasSize) -> Self {
        Self::ALL
            .into_iter()
            .find(|preset| preset.size() == size)
            .unwrap_or(Self::Widescreen)
    }
}

fn alto_lienzo(visuales: &[VisualState], canvas: datan_report::saved::CanvasSize) -> u32 {
    let contenido = visuales
        .iter()
        .filter(|visual| visual.visible)
        .map(|visual| {
            visual
                .position
                .y
                .saturating_add(visual.size.height.max(160))
        })
        .max()
        .unwrap_or(0);
    contenido
        .saturating_add(LIENZO_MARGEN_INFERIOR)
        .max(canvas.height.max(LIENZO_ALTO_MINIMO))
}

fn ancho_lienzo(visuales: &[VisualState], canvas: datan_report::saved::CanvasSize) -> u32 {
    visuales
        .iter()
        .filter(|visual| visual.visible)
        .map(|visual| visual.position.x.saturating_add(visual.size.width.max(280)))
        .max()
        .unwrap_or(0)
        .max(canvas.width)
}

fn dimensiones_lienzo(
    visuales: &[VisualState],
    canvas: datan_report::saved::CanvasSize,
) -> (u32, u32) {
    (
        ancho_lienzo(visuales, canvas),
        alto_lienzo(visuales, canvas),
    )
}

fn marco_pagina_lienzo(
    theme: &Theme,
    zoom: f32,
    canvas: datan_report::saved::CanvasSize,
) -> AnyElement {
    div()
        .absolute()
        .top_0()
        .left_0()
        .w(px(canvas.width as f32 * zoom))
        .h(px(canvas.height as f32 * zoom))
        .bg(theme.background)
        .border_1()
        .border_color(theme.border)
        .into_any_element()
}

fn acotar_geometria_visual(
    position: &mut datan_report::saved::SavedPosition,
    size: &mut datan_report::saved::SavedSize,
    canvas: datan_report::saved::CanvasSize,
) {
    size.width = size.width.clamp(280, canvas.width);
    size.height = size.height.clamp(160, canvas.height);
    position.x = position.x.min(canvas.width - size.width);
    position.y = position.y.min(canvas.height - size.height);
}

fn geometria_ancho_visual_preset(
    mut position: datan_report::saved::SavedPosition,
    mut size: datan_report::saved::SavedSize,
    canvas: datan_report::saved::CanvasSize,
    width: u32,
) -> (
    datan_report::saved::SavedPosition,
    datan_report::saved::SavedSize,
) {
    size.width = width.clamp(280, canvas.width.min(1200).max(280));
    acotar_geometria_visual(&mut position, &mut size, canvas);
    (position, size)
}

fn ancho_visual_preset(available_width: u32, fraction: f32, canvas_width: u32) -> u32 {
    let max_width = canvas_width.min(1200).max(280);
    ((available_width as f32 * fraction).round() as u32).clamp(280, max_width)
}

fn primera_posicion_visual_libre(
    ocupados: &[(
        datan_report::saved::SavedPosition,
        datan_report::saved::SavedSize,
    )],
    canvas: datan_report::saved::CanvasSize,
    size: datan_report::saved::SavedSize,
) -> datan_report::saved::SavedPosition {
    let columnas = canvas.width.saturating_sub(size.width) / 480 + 1;
    let ultimo_borde = ocupados
        .iter()
        .map(|(position, occupied_size)| position.y.saturating_add(occupied_size.height))
        .max()
        .unwrap_or(0);
    let filas = ultimo_borde / 360 + ocupados.len() as u32 + 2;

    for row in 0..filas {
        for column in 0..columnas {
            let position = datan_report::saved::SavedPosition {
                x: column.saturating_mul(480),
                y: row.saturating_mul(360),
            };
            let overlaps = ocupados.iter().any(|(other_position, other_size)| {
                let left = position.x < other_position.x.saturating_add(other_size.width);
                let right = position.x.saturating_add(size.width) > other_position.x;
                let above = position.y < other_position.y.saturating_add(other_size.height);
                let below = position.y.saturating_add(size.height) > other_position.y;
                left && right && above && below
            });
            if !overlaps {
                return position;
            }
        }
    }

    datan_report::saved::SavedPosition {
        x: 0,
        y: ultimo_borde.saturating_add(40),
    }
}

#[cfg(test)]
mod visual_placement_tests {
    use super::{
        ancho_visual_preset, geometria_ancho_visual_preset, primera_posicion_visual_libre,
    };
    use datan_report::saved::{CanvasSize, SavedPosition, SavedSize};

    fn ocupacion(x: u32, y: u32) -> (SavedPosition, SavedSize) {
        (
            SavedPosition { x, y },
            SavedSize {
                width: 460,
                height: 320,
            },
        )
    }

    #[test]
    fn preset_de_ancho_acota_el_visual_y_lo_mantiene_dentro_del_lienzo() {
        let (position, size) = geometria_ancho_visual_preset(
            SavedPosition { x: 100, y: 40 },
            SavedSize {
                width: 460,
                height: 320,
            },
            CanvasSize {
                width: 1280,
                height: 720,
            },
            1200,
        );

        assert_eq!(size.width, 1200);
        assert_eq!(position.x + size.width, 1280);
        assert_eq!(position.y, 40);
    }

    #[test]
    fn preset_completo_respeta_el_ancho_del_lienzo_y_su_estado_activo() {
        assert_eq!(ancho_visual_preset(1600, 1.0, 960), 960);
    }

    #[test]
    fn agrega_un_visual_en_el_espacio_libre_despues_de_borrar_otro() {
        let ocupados = vec![ocupacion(0, 0), ocupacion(0, 360), ocupacion(480, 360)];
        let size = SavedSize {
            width: 460,
            height: 320,
        };

        let position = primera_posicion_visual_libre(&ocupados, CanvasSize::default(), size);

        assert_eq!(position, SavedPosition { x: 480, y: 0 });
    }

    #[test]
    fn agrega_un_visual_debajo_del_lienzo_si_todos_los_espacios_estan_ocupados() {
        let ocupados = vec![
            ocupacion(0, 0),
            ocupacion(480, 0),
            ocupacion(0, 360),
            ocupacion(480, 360),
        ];
        let size = SavedSize {
            width: 460,
            height: 320,
        };

        let position = primera_posicion_visual_libre(&ocupados, CanvasSize::default(), size);

        assert_eq!(position, SavedPosition { x: 0, y: 720 });
    }
}

fn visuales_fuera_de_pagina(
    visuales: &[VisualState],
    canvas: datan_report::saved::CanvasSize,
) -> usize {
    visuales
        .iter()
        .filter(|visual| {
            visual.visible
                && (visual.position.x.saturating_add(visual.size.width.max(280)) > canvas.width
                    || visual
                        .position
                        .y
                        .saturating_add(visual.size.height.max(160))
                        > canvas.height)
        })
        .count()
}

fn mover_capa_visual<T>(visuales: &mut [T], index: usize, hacia_delante: bool) -> bool {
    if index >= visuales.len() {
        return false;
    }
    let destino = if hacia_delante {
        index
            .checked_add(1)
            .filter(|destino| *destino < visuales.len())
    } else {
        index.checked_sub(1)
    };
    let Some(destino) = destino else {
        return false;
    };
    visuales.swap(index, destino);
    true
}

#[derive(Clone, Copy)]
enum DisposicionLienzo {
    Izquierda,
    Arriba,
    Horizontal,
    Vertical,
}

#[derive(Clone, Copy)]
enum OrdenCampo {
    Arriba,
    Abajo,
}

fn indice_campo_vecino(indice: usize, largo: usize, direccion: OrdenCampo) -> Option<usize> {
    if indice >= largo {
        return None;
    }
    match direccion {
        OrdenCampo::Arriba => indice.checked_sub(1),
        OrdenCampo::Abajo => indice.checked_add(1).filter(|siguiente| *siguiente < largo),
    }
}

fn mover_campo_vecino<T>(campos: &mut [T], indice: usize, direccion: OrdenCampo) -> bool {
    let Some(destino) = indice_campo_vecino(indice, campos.len(), direccion) else {
        return false;
    };
    campos.swap(indice, destino);
    true
}

fn disponer_visuales(
    items: &mut [(
        String,
        datan_report::saved::SavedPosition,
        datan_report::saved::SavedSize,
    )],
    seleccionados: &[String],
    disposicion: DisposicionLienzo,
) -> bool {
    let mut indices: Vec<usize> = items
        .iter()
        .enumerate()
        .filter(|(_, (id, _, _))| seleccionados.contains(id))
        .map(|(index, _)| index)
        .collect();
    if indices.len() < 2 {
        return false;
    }
    match disposicion {
        DisposicionLienzo::Izquierda => {
            let x = indices
                .iter()
                .map(|index| items[*index].1.x)
                .min()
                .unwrap_or(0);
            for index in &indices {
                items[*index].1.x = x;
            }
        }
        DisposicionLienzo::Arriba => {
            let y = indices
                .iter()
                .map(|index| items[*index].1.y)
                .min()
                .unwrap_or(0);
            for index in &indices {
                items[*index].1.y = y;
            }
        }
        DisposicionLienzo::Horizontal | DisposicionLienzo::Vertical => {
            if indices.len() < 3 {
                return false;
            }
            let horizontal = matches!(disposicion, DisposicionLienzo::Horizontal);
            indices.sort_by_key(|index| {
                if horizontal {
                    items[*index].1.x
                } else {
                    items[*index].1.y
                }
            });
            let start = if horizontal {
                items[indices[0]].1.x
            } else {
                items[indices[0]].1.y
            };
            let last = *indices.last().unwrap_or(&indices[0]);
            let end = if horizontal {
                items[last].1.x.saturating_add(items[last].2.width)
            } else {
                items[last].1.y.saturating_add(items[last].2.height)
            };
            let total_size = indices.iter().fold(0u32, |total, index| {
                total.saturating_add(if horizontal {
                    items[*index].2.width
                } else {
                    items[*index].2.height
                })
            });
            let gap =
                end.saturating_sub(start).saturating_sub(total_size) / (indices.len() as u32 - 1);
            let mut cursor = start;
            for index in indices.iter().take(indices.len() - 1) {
                if horizontal {
                    items[*index].1.x = cursor;
                    cursor = cursor
                        .saturating_add(items[*index].2.width)
                        .saturating_add(gap);
                } else {
                    items[*index].1.y = cursor;
                    cursor = cursor
                        .saturating_add(items[*index].2.height)
                        .saturating_add(gap);
                }
            }
            if horizontal {
                items[last].1.x = end.saturating_sub(items[last].2.width);
            } else {
                items[last].1.y = end.saturating_sub(items[last].2.height);
            }
        }
    }
    true
}

const LIENZO_ZOOM_MINIMO: u16 = 10;
const LIENZO_ZOOM_MAXIMO: u16 = 200;

fn factor_zoom(percent: u16) -> f32 {
    percent.clamp(LIENZO_ZOOM_MINIMO, LIENZO_ZOOM_MAXIMO) as f32 / 100.0
}

fn px_lienzo(valor: f32, zoom: f32) -> Pixels {
    px(valor * zoom)
}

fn px_texto_lienzo(valor: f32, zoom: f32, escala: f32) -> Pixels {
    px(valor * zoom * escala.clamp(0.7, 1.6))
}

fn ancho_lienzo_disponible(viewport_width: u32, margen: f32) -> u32 {
    (viewport_width as f32 - margen).max(1.0) as u32
}

fn ancho_vista_canvas(
    viewport_width: u32,
    lectura: bool,
    datos_visible: bool,
    filtros_visible: bool,
    visualizaciones_visible: bool,
    margen: f32,
) -> u32 {
    let ancho_paneles = if lectura {
        0
    } else {
        [(datos_visible, tokens::PANEL_DATOS),
         (filtros_visible, tokens::PANEL_FILTROS),
         (visualizaciones_visible, tokens::PANEL_VISUALES)]
            .into_iter()
            .map(|(visible, width)| if visible { width } else { tokens::PANEL_PLEGADO } as u32)
            .sum()
    };
    ancho_lienzo_disponible(viewport_width.saturating_sub(ancho_paneles), margen)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct GeometriaEtapaLienzo {
    ancho: u32,
    alto: u32,
    margen_izquierdo: u32,
    margen_superior: u32,
}

fn geometria_etapa_lienzo(
    ancho_disponible: u32,
    alto_disponible: u32,
    ancho_contenido: u32,
    alto_contenido: u32,
) -> GeometriaEtapaLienzo {
    let ancho = ancho_disponible.max(ancho_contenido);
    let alto = alto_disponible.max(alto_contenido);
    GeometriaEtapaLienzo {
        ancho,
        alto,
        margen_izquierdo: ancho.saturating_sub(ancho_contenido) / 2,
        margen_superior: alto.saturating_sub(alto_contenido) / 2,
    }
}

fn visual_seleccionado<'a>(page: &'a Pagina, selected_id: Option<&str>) -> Option<&'a VisualState> {
    let id = selected_id?;
    page.visuales
        .iter()
        .find(|visual| visual.visible && visual.id == id)
}

fn vista_visual_nuevo(mut vista: Vista, tipo: &str) -> Vista {
    vista.selection = Selection {
        dimensions: Vec::new(),
        legend: None,
        measures: Vec::new(),
        implicit_measures: Vec::new(),
        value_order: Vec::new(),
    };
    vista.matrix_row_count = None;
    vista.visual = tipo.to_string();
    vista.sort = None;
    vista.top_n = None;
    vista.formatos.clear();
    vista
}

fn convertir_visual(visual: &mut VisualState, tipo: &str) {
    let mut vista = visual.vista.clone();
    if !supports_legend(tipo) {
        vista.selection.legend = None;
    }
    if tipo == "KPI" {
        limitar_valores_kpi(&mut vista.selection);
    } else if tipo == "Medidor" {
        normalizar_valores_medidor(&mut vista.selection, &mut visual.gauge_fields);
    }
    vista.visual = tipo.to_string();
    visual.vista = vista;
}

fn normalizar_valores_medidor(selection: &mut Selection, fields: &mut GaugeFields) {
    fields.minimum = fields
        .minimum
        .filter(|value| selection.value_is_selected(*value));
    fields.maximum = fields
        .maximum
        .filter(|value| selection.value_is_selected(*value));
    fields.target = fields
        .target
        .filter(|value| selection.value_is_selected(*value));
    fields.value = fields
        .value
        .filter(|value| selection.value_is_selected(*value))
        .or_else(|| {
            selection
                .value_order
                .first()
                .copied()
                .or_else(|| {
                    selection
                        .measures
                        .first()
                        .copied()
                        .map(ValueSelection::Measure)
                })
                .or_else(|| {
                    selection
                        .implicit_measures
                        .first()
                        .map(|measure| measure.selection())
                })
        });

    let assigned = [fields.value, fields.minimum, fields.maximum, fields.target];
    selection
        .measures
        .retain(|id| assigned.contains(&Some(ValueSelection::Measure(*id))));
    selection
        .implicit_measures
        .retain(|measure| assigned.contains(&Some(measure.selection())));
    selection
        .value_order
        .retain(|value| assigned.contains(&Some(*value)));
}

fn limitar_valores_kpi(selection: &mut Selection) {
    let values = if selection.value_order.is_empty() {
        selection
            .measures
            .iter()
            .copied()
            .map(ValueSelection::Measure)
            .chain(
                selection
                    .implicit_measures
                    .iter()
                    .map(|measure| measure.selection()),
            )
            .take(2)
            .collect::<Vec<_>>()
    } else {
        selection.value_order.iter().copied().take(2).collect()
    };
    selection.measures.retain(|id| {
        values
            .iter()
            .any(|value| matches!(value, ValueSelection::Measure(value_id) if value_id == id))
    });
    selection.implicit_measures.retain(|measure| {
        values.iter().any(
            |value| matches!(value, ValueSelection::Implicit(column, aggregation) if *column == measure.column && *aggregation == measure.aggregation),
        )
    });
    selection.value_order = values;
}

fn selected_filter_value_indices(
    values: &[datan_dax_eval::FilterValue],
    existing: &[datan_dax_eval::FilterValue],
    truncated: bool,
) -> Vec<usize> {
    values
        .iter()
        .enumerate()
        .filter_map(|(index, value)| {
            let selected = if existing.is_empty() {
                !truncated
            } else {
                existing.contains(value)
            };
            selected.then_some(index)
        })
        .collect()
}

fn selected_filter_values(
    values: &[datan_dax_eval::FilterValue],
    selected: &[usize],
    preserved: &[datan_dax_eval::FilterValue],
    condition_mode: bool,
) -> Vec<datan_dax_eval::FilterValue> {
    let mut chosen: Vec<_> = selected
        .iter()
        .filter_map(|index| values.get(*index).cloned())
        .collect();
    if !condition_mode {
        chosen.extend_from_slice(preserved);
    }
    chosen
}

fn puede_aplicar_valores_cargados(
    truncated: bool,
    selected_count: usize,
    preserved_count: usize,
    has_existing_filter: bool,
) -> bool {
    !truncated || selected_count > 0 || preserved_count > 0 || has_existing_filter
}

fn puede_aplicar_condicion(
    selected_count: usize,
    operator: Option<datan_report::saved::SavedFilterOperator>,
) -> bool {
    match operator {
        Some(datan_report::saved::SavedFilterOperator::Between) => selected_count == 2,
        Some(_) => selected_count == 1,
        None => false,
    }
}

fn parse_filter_range_bounds(
    data_type: DataType,
    lower: &str,
    upper: &str,
) -> Option<(datan_dax_eval::FilterValue, datan_dax_eval::FilterValue)> {
    let lower = parse_filter_bound(data_type, lower)?;
    let upper = parse_filter_bound(data_type, upper)?;
    (comparar_valores_filtro(&lower, &upper)? != std::cmp::Ordering::Greater)
        .then_some((lower, upper))
}

fn parse_filter_bound(data_type: DataType, text: &str) -> Option<datan_dax_eval::FilterValue> {
    use datan_dax_eval::FilterValue;

    let text = text.trim();
    if text.is_empty() {
        return None;
    }
    match data_type {
        DataType::Integer | DataType::Moneda => text.parse().ok().map(FilterValue::Integer),
        DataType::Decimal => {
            let normalized = if text.contains(',') && !text.contains('.') {
                text.replace(',', ".")
            } else if text.contains(',') {
                return None;
            } else {
                text.to_string()
            };
            normalized
                .parse::<f64>()
                .ok()
                .filter(|value| value.is_finite())
                .map(FilterValue::Decimal)
        }
        DataType::Date | DataType::DateTime => {
            if !text.contains('-') || text.contains('T') {
                return None;
            }
            datan_dax_eval::parse_day(text).map(FilterValue::Date)
        }
        DataType::Text | DataType::Boolean => None,
    }
}

fn clear_filter_scope_values(
    page_filters: &mut Vec<ActiveFilter>,
    report_filters: &mut Vec<ActiveFilter>,
    visual_filters: &mut Vec<ActiveFilter>,
    scope: AlcanceFiltro,
) -> bool {
    let filters = match scope {
        AlcanceFiltro::Pagina => page_filters,
        AlcanceFiltro::Informe => report_filters,
        AlcanceFiltro::Visual => visual_filters,
    };
    if filters.is_empty() {
        return false;
    }
    filters.clear();
    true
}

fn pagina_tiene_filtros_de_pagina(page: &Pagina) -> bool {
    !page.filtros.is_empty()
        || !page.vista.filters.is_empty()
        || page.vista.date_months.is_some()
        || !page.interacciones_grafico.is_empty()
        || page.visuales.iter().any(|visual| {
            !visual.slicer_selection.is_empty()
                || visual.rango_fecha.is_some()
                || visual.vista.date_months.is_some()
        })
}

fn hay_filtros_activos(
    filters: &[ActiveFilter],
    report_filters: &[ActiveFilter],
    visual_filters: &[ActiveFilter],
    date_months: Option<u8>,
    page: Option<&Pagina>,
) -> bool {
    !filters.is_empty()
        || !report_filters.is_empty()
        || !visual_filters.is_empty()
        || date_months.is_some()
        || page.is_some_and(pagina_tiene_filtros_de_pagina)
        || page.is_some_and(|page| page.visuales.iter().any(|visual| !visual.filtros.is_empty()))
}

fn limpiar_filtros_de_pagina(page: &mut Pagina) {
    page.filtros.clear();
    page.vista.filters.clear();
    page.vista.date_months = None;
    page.interacciones_grafico.clear();
    for visual in &mut page.visuales {
        visual.slicer_selection.clear();
        visual.rango_fecha = None;
        visual.vista.date_months = None;
        visual.vista.filters.clear();
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum EstadoLienzoSinVisuales {
    Vacio,
    Ocultos,
}

fn estado_lienzo_sin_visuales(cantidad: usize) -> EstadoLienzoSinVisuales {
    if cantidad == 0 {
        EstadoLienzoSinVisuales::Vacio
    } else {
        EstadoLienzoSinVisuales::Ocultos
    }
}

fn matriz_filas(dimension_count: usize, configured: Option<usize>) -> usize {
    match dimension_count {
        0 => 0,
        1 => 1,
        count => configured.unwrap_or(count - 1).clamp(1, count - 1),
    }
}

fn siguiente_cantidad_filas(
    dimensions: &[ObjectId],
    row_count: usize,
    column: ObjectId,
) -> Option<usize> {
    let index = dimensions
        .iter()
        .position(|dimension| *dimension == column)?;
    if index + 1 == row_count && row_count > 1 {
        Some(row_count - 1)
    } else if index == row_count && row_count + 1 < dimensions.len() {
        Some(row_count + 1)
    } else {
        None
    }
}

fn instruccion_eje(visual: &str, dimensiones: usize) -> Option<&'static str> {
    match (visual, dimensiones) {
        ("Sankey", 0) => Some("Añade el origen y el destino."),
        ("Sankey", 1) => Some("Añade el destino del flujo."),
        _ => None,
    }
}

fn instruccion_valores(visual: &str, medidas: usize) -> Option<&'static str> {
    match (visual, medidas) {
        ("Sankey", 0) => Some("Añade una medida para el flujo."),
        ("Dispersion", 0) => Some("Añade dos medidas: eje X y después eje Y."),
        ("Dispersion", 1) => Some("Añade la medida del eje Y."),
        ("Combinado", 0) => Some("Añade dos medidas: primero barras y después línea."),
        ("Combinado", 1) => Some("Añade la medida para la línea."),
        ("Candlestick", 0) => Some("Añade apertura, máximo, mínimo y cierre."),
        ("Candlestick", 1) => Some("Añade máximo, mínimo y cierre, en ese orden."),
        ("Candlestick", 2) => Some("Añade mínimo y cierre, en ese orden."),
        ("Candlestick", 3) => Some("Añade la medida de cierre."),
        _ => None,
    }
}

fn mensaje_campos_visual(visual: &str, dimensiones: usize, medidas: usize) -> Option<&'static str> {
    match visual {
        "Tarjetas" => {
            (medidas == 0).then_some("Añade una medida desde Datos para mostrar la tarjeta.")
        }
        "KPI" => {
            (medidas == 0).then_some("Añade una medida desde Datos para mostrar el indicador.")
        }
        "Medidor" if medidas == 0 => Some("Añade una medida a Valores para mostrar el medidor."),
        "Medidor" => None,
        "Segmentador" => (dimensiones == 0)
            .then_some("Añade un campo desde Datos para filtrar con este segmentador."),
        "Sankey" if dimensiones > 2 => {
            Some("Sankey usa dos campos de eje: origen y destino. Quita los campos extra.")
        }
        "Sankey" if medidas > 1 => {
            Some("Sankey usa una medida para el peso de los enlaces. Quita las medidas extra.")
        }
        "Sankey" => {
            instruccion_eje(visual, dimensiones).or_else(|| instruccion_valores(visual, medidas))
        }
        "Dispersion" if dimensiones == 0 && medidas < 2 => {
            Some("Marca una categoría en el eje y dos medidas numéricas para los ejes X e Y.")
        }
        "Dispersion" if medidas < 2 => instruccion_valores(visual, medidas),
        "Combinado" if dimensiones == 0 && medidas < 2 => {
            Some("Marca una categoría y dos medidas, primero Barras y después Línea.")
        }
        "Combinado" if medidas < 2 => instruccion_valores(visual, medidas),
        "Candlestick" if dimensiones == 0 && medidas < 4 => {
            Some("Marca una categoría en el eje y las medidas apertura, máximo, mínimo y cierre.")
        }
        "Candlestick" if dimensiones > 1 => {
            Some("Velas usa un campo para el eje X. Quita los campos de eje extra.")
        }
        "Candlestick" if medidas < 4 => instruccion_valores(visual, medidas),
        _ if dimensiones == 0 && medidas == 0 => {
            Some("Marca un campo en el eje y una medida en Valores desde Datos.")
        }
        _ if dimensiones == 0 => Some("Añade un campo al eje para mostrar categorías."),
        _ if medidas == 0 && visual != "Tabla" => {
            Some("Añade una medida numérica a Valores desde Datos.")
        }
        _ => None,
    }
}

fn mensaje_sin_datos_visual(visual: &str) -> &'static str {
    match visual {
        "KPI" | "Tarjetas" => "No hay un valor para mostrar en esta tarjeta. Revisa los filtros.",
        "Tabla" | "Todo" => "No hay filas para mostrar en esta tabla. Revisa los filtros.",
        "Sankey" => "No hay flujos para mostrar con estas dimensiones. Revisa los filtros.",
        "Dispersion" => "No hay pares de valores para comparar. Revisa los filtros.",
        "Candlestick" => "No hay valores de apertura, máximo, mínimo y cierre para mostrar.",
        "Combinado" => "No hay categorías con valores para combinar. Revisa los filtros.",
        "Medidor" => "No hay un valor para mostrar en este medidor. Revisa los filtros.",
        "Segmentador" => "No hay opciones para este segmentador. Revisa los filtros.",
        "Anillo" => "No hay categorías para mostrar en este anillo. Revisa los filtros.",
        "Lineas" | "Area" => "No hay valores para trazar esta serie. Revisa los filtros.",
        "Barras" | "Columnas" => "No hay categorías para mostrar. Revisa los filtros.",
        "Embudo" => "No hay etapas para mostrar en este embudo. Revisa los filtros.",
        "Treemap" => "No hay categorías para mostrar en este mosaico. Revisa los filtros.",
        "Cascada" => "No hay valores para mostrar en esta cascada. Revisa los filtros.",
        _ => "No hay datos para mostrar en este visual. Revisa los filtros.",
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum EstadoCategoriasVisual {
    RevisarRelaciones,
    ElegirDimension,
    AgregarTablaDimension,
    SinCategorias,
}

fn estado_categorias_visual(
    dimensiones_seleccionadas: usize,
    dimensiones_conectadas: usize,
    dimensiones_modelo: usize,
    hay_filas_de_datos: bool,
) -> Option<EstadoCategoriasVisual> {
    if dimensiones_seleccionadas == 0 {
        if dimensiones_modelo > 0 && dimensiones_conectadas == 0 {
            return Some(EstadoCategoriasVisual::RevisarRelaciones);
        }
        if dimensiones_modelo == 0 {
            return Some(EstadoCategoriasVisual::AgregarTablaDimension);
        }
        return Some(EstadoCategoriasVisual::ElegirDimension);
    }
    (!hay_filas_de_datos).then_some(EstadoCategoriasVisual::SinCategorias)
}

