fn mosaico_visual(
    theme: &Theme,
    visual_actual: &str,
    key: &'static str,
    etiqueta: &'static str,
    glifo: IconName,
    cx: &mut Context<Datan>,
) -> AnyElement {
    // `Todo` es el lienzo compuesto. Se representa con la tarjeta que ocupa su zona superior.
    let activo = visual_actual == key || (key == "Tarjetas" && visual_actual == "Todo");
    components::mosaico(
        theme,
        SharedString::from(format!("viz-{key}")),
        etiqueta,
        glifo,
        activo,
        false,
        cx.listener(move |view, _event, _window, cx| {
            if matches!(
                key,
                "Combinado"
                    | "Radar"
                    | "Embudo"
                    | "Medidor"
                    | "Treemap"
                    | "Cascada"
                    | "KPI"
                    | "Sankey"
                    | "Candlestick"
                    | "Matriz"
                    | "Segmentador"
            ) {
                view.tipos_avanzados_abiertos = true;
            }
            view.agregar_visual_tipo(key, cx);
        }),
    )
}

fn zoom_ajustado(
    visuales: &[VisualState],
    canvas: datan_report::saved::CanvasSize,
    ancho_disponible: u32,
    alto_disponible: u32,
) -> u16 {
    let (ancho, alto) = dimensiones_lienzo(visuales, canvas);
    let factor = (ancho_disponible as f32 / ancho as f32).min(alto_disponible as f32 / alto as f32);
    ((factor * 100.0).floor() as u16).clamp(LIENZO_ZOOM_MINIMO, LIENZO_ZOOM_MAXIMO)
}

fn alineacion_barras(tipo: &str) -> gpui_kit::component::plot::shape::BarAlignment {
    use gpui_kit::component::plot::shape::BarAlignment;

    if tipo == "Barras" {
        BarAlignment::Left
    } else {
        BarAlignment::Bottom
    }
}

fn tamano_visual_desde_puntero(x_origen: u32, y_origen: u32, x: f32, y: f32) -> (u32, u32) {
    (
        (x - x_origen as f32).round().clamp(280.0, 1200.0) as u32,
        (y - y_origen as f32).round().clamp(160.0, 900.0) as u32,
    )
}

fn resize_handle(visual_id: &str, nombre: &str, edge: ResizeEdge, zoom: f32) -> Stateful<Div> {
    let largo = px((8.0 * zoom).max(8.0));
    let esquina = px((12.0 * zoom).max(10.0));
    let margen = px((12.0 * zoom).max(10.0));
    let cursor = match edge {
        ResizeEdge::North | ResizeEdge::South => CursorStyle::ResizeUpDown,
        ResizeEdge::East | ResizeEdge::West => CursorStyle::ResizeLeftRight,
        ResizeEdge::NorthWest | ResizeEdge::SouthEast => CursorStyle::ResizeUpLeftDownRight,
        ResizeEdge::NorthEast | ResizeEdge::SouthWest => CursorStyle::ResizeUpRightDownLeft,
    };
    let mut handle = div()
        .id(ElementId::Name(
            format!("visual-resize-{visual_id}-{nombre}").into(),
        ))
        .absolute()
        .cursor(cursor);
    handle = match edge {
        ResizeEdge::North => handle.left(margen).right(margen).top(px(-4.0)).h(largo),
        ResizeEdge::NorthEast => handle.right(px(-4.0)).top(px(-4.0)).w(esquina).h(esquina),
        ResizeEdge::East => handle.right(px(-4.0)).top(margen).bottom(margen).w(largo),
        ResizeEdge::SouthEast => handle
            .right(px(-4.0))
            .bottom(px(-4.0))
            .w(esquina)
            .h(esquina),
        ResizeEdge::South => handle.left(margen).right(margen).bottom(px(-4.0)).h(largo),
        ResizeEdge::SouthWest => handle.left(px(-4.0)).bottom(px(-4.0)).w(esquina).h(esquina),
        ResizeEdge::West => handle.left(px(-4.0)).top(margen).bottom(margen).w(largo),
        ResizeEdge::NorthWest => handle.left(px(-4.0)).top(px(-4.0)).w(esquina).h(esquina),
    };
    handle
}

fn alternar_seleccion_grafico(
    page: &mut Pagina,
    source_id: &str,
    filters: &[ActiveFilter],
) -> bool {
    if page
        .interacciones_grafico
        .get(source_id)
        .is_some_and(|selected| selected == filters)
    {
        page.interacciones_grafico.remove(source_id);
    } else if filters.is_empty() {
        page.interacciones_grafico.remove(source_id);
    } else {
        page.interacciones_grafico
            .insert(source_id.to_string(), filters.to_vec());
    }
    true
}

fn interacciones_para_visual(page: &Pagina, target_id: &str) -> InteraccionesVisual {
    let mut result = InteraccionesVisual::default();
    for (source_id, filters) in &page.interacciones_grafico {
        if source_id == target_id || filters.is_empty() {
            continue;
        }
        let Some(source) = page
            .visuales
            .iter()
            .find(|visual| visual.id == *source_id && visual.visible)
        else {
            continue;
        };
        if !visual_admite_seleccion_interactiva(&source.vista.visual) {
            continue;
        }
        if filters
            .iter()
            .any(|filter| !source.vista.selection.dimensions.contains(&filter.column))
        {
            continue;
        }
        match source
            .interactions
            .get(target_id)
            .copied()
            .unwrap_or_default()
        {
            datan_report::saved::SavedInteraction::Filter => {
                result.filtros.push(filters.clone());
            }
            datan_report::saved::SavedInteraction::Highlight
                if page
                    .visuales
                    .iter()
                    .find(|visual| visual.id == target_id)
                    .is_some_and(|visual| visual_admite_resaltado(&visual.vista.visual)) =>
            {
                result.resaltados.push(filters.clone());
            }
            datan_report::saved::SavedInteraction::Highlight => {}
            datan_report::saved::SavedInteraction::Disabled => {}
        }
    }
    result
}

fn aplicar_grupos_filtros(mut report: Report, groups: &[Vec<ActiveFilter>]) -> Report {
    for filters in groups {
        report = aplicar_filtros(report, filters);
    }
    report
}

fn filtro_detalle(
    visual_filters: &[ActiveFilter],
    page: Option<&Pagina>,
    filters: &[ActiveFilter],
) -> Option<ActiveFilter> {
    visual_filters
        .last()
        .cloned()
        .or_else(|| {
            page.and_then(|page| {
                page.visuales
                    .iter()
                    .rev()
                    .find_map(|visual| visual.filtros.last().cloned())
                    .or_else(|| page.filtros.last().cloned())
            })
        })
        .or_else(|| filters.last().cloned())
}

fn alternar_valor_en_filtros(filtros: &mut Vec<ActiveFilter>, filtro: ActiveFilter) {
    if filtros
        .iter()
        .any(|activo| activo.column == filtro.column && activo.value == filtro.value)
    {
        filtros.retain(|activo| activo.column != filtro.column || activo.value != filtro.value);
    } else {
        filtros.push(filtro);
    }
}

fn filtros_categoria(
    columns: &[ObjectId],
    values: &[String],
    mut label_for: impl FnMut(ObjectId) -> String,
) -> Vec<ActiveFilter> {
    columns
        .iter()
        .zip(values)
        .map(|(column, value)| ActiveFilter {
            column: *column,
            label: SharedString::from(label_for(*column)),
            value: SharedString::from(value.clone()),
            operator: None,
            upper_value: None,
        })
        .collect()
}

fn filtros_fila_tabla(
    row_kind: RowKind,
    columns: &[ObjectId],
    values: &[String],
    label_for: impl FnMut(ObjectId) -> String,
) -> Option<Vec<ActiveFilter>> {
    if row_kind != RowKind::Data || columns.is_empty() || columns.len() != values.len() {
        return None;
    }
    Some(filtros_categoria(columns, values, label_for))
}

const FILAS_POR_PAGINA_TABLA: usize = 50;

fn columnas_visibles_tabla(matrix: &Matrix) -> std::ops::Range<usize> {
    0..matrix.width()
}

fn rango_pagina_tabla(row_count: usize, page: usize) -> (usize, usize) {
    let page_count = row_count.div_ceil(FILAS_POR_PAGINA_TABLA);
    let page = page.min(page_count.saturating_sub(1));
    let start = page * FILAS_POR_PAGINA_TABLA;
    (start, (start + FILAS_POR_PAGINA_TABLA).min(row_count))
}

fn filtros_de_segmentadores(page: &Pagina) -> Vec<Vec<ActiveFilter>> {
    page.visuales
        .iter()
        .filter(|visual| visual.visible && visual.vista.visual == "Segmentador")
        .filter(|visual| !visual.slicer_selection.is_empty())
        .map(|visual| visual.slicer_selection.clone())
        .collect()
}

fn limpiar_filtros_pagina(page: &mut Pagina) {
    limpiar_filtros_de_pagina(page);
    for visual in &mut page.visuales {
        visual.filtros.clear();
        visual.vista.filters.clear();
    }
}

fn migrar_seleccion_segmentadores_legacy(
    page: &mut Pagina,
    saved_visuals: &[datan_report::saved::SavedVisual],
) {
    let mut slicer_columns = std::collections::BTreeSet::new();
    for (visual, saved) in page.visuales.iter_mut().zip(saved_visuals) {
        if saved.kind != "Segmentador" || saved.slicer_selection.is_some() {
            continue;
        }
        let Some(column) = visual.vista.selection.dimensions.first().copied() else {
            continue;
        };
        let selection = page
            .filtros
            .iter()
            .filter(|filter| filter.column == column)
            .cloned()
            .collect::<Vec<_>>();
        if selection.is_empty() {
            continue;
        }
        visual.slicer_selection = selection;
        visual.filtros.retain(|filter| filter.column != column);
        slicer_columns.insert(column);
    }
    page.filtros
        .retain(|filter| !slicer_columns.contains(&filter.column));
}

fn migrar_filtro_pagina_a_segmentador(page: &mut Pagina, visual_id: &str, column: ObjectId) {
    let selection = page
        .filtros
        .iter()
        .filter(|filter| filter.column == column)
        .cloned()
        .collect::<Vec<_>>();
    if selection.is_empty() {
        return;
    }
    if let Some(visual) = page.visuales.iter_mut().find(|visual| {
        visual.id == visual_id
            && visual.vista.visual == "Segmentador"
            && visual.vista.selection.dimensions.first() == Some(&column)
    }) {
        visual.slicer_selection = selection;
        page.filtros.retain(|filter| filter.column != column);
    }
}

fn visual_id() -> String {
    format!("visual-{}", NEXT_VISUAL_ID.fetch_add(1, Ordering::Relaxed))
}

fn rekey_visuales(visuales: &mut [VisualState], activo: &mut String) {
    let ids: std::collections::HashMap<String, String> = visuales
        .iter()
        .map(|visual| (visual.id.clone(), visual_id()))
        .collect();
    for visual in visuales {
        let interactions = std::mem::take(&mut visual.interactions);
        visual.interactions = interactions
            .into_iter()
            .map(|(target, interaction)| (ids.get(&target).cloned().unwrap_or(target), interaction))
            .collect();
        if let Some(id) = ids.get(&visual.id) {
            visual.id = id.clone();
        }
    }
    if let Some(id) = ids.get(activo) {
        *activo = id.clone();
    }
}

fn rekey_pagina(pagina: &mut Pagina) {
    rekey_visuales(&mut pagina.visuales, &mut pagina.visual_activo);
    pagina.interacciones_grafico.clear();
    for bookmark in &mut pagina.bookmarks {
        rekey_visuales(&mut bookmark.visuales, &mut bookmark.visual_activo);
    }
}

fn fecha_desde_dia(day: i32) -> Option<NaiveDate> {
    NaiveDate::from_ymd_opt(1970, 1, 1)?.checked_add_signed(chrono::Duration::days(i64::from(day)))
}

fn es_tipo_fecha(data_type: DataType) -> bool {
    matches!(data_type, DataType::Date | DataType::DateTime)
}

fn dia_desde_fecha(date: NaiveDate) -> i32 {
    date.signed_duration_since(NaiveDate::from_ymd_opt(1970, 1, 1).expect("fecha de epoca valida"))
        .num_days() as i32
}

