fn insertar_copia_pagina(
    paginas: &mut Vec<Pagina>,
    activa: &mut usize,
    origen: usize,
    copia: Pagina,
) -> Option<usize> {
    if origen >= paginas.len() {
        return None;
    }
    let indice_copia = origen + 1;
    paginas.insert(indice_copia, copia);
    *activa = indice_copia;
    Some(indice_copia)
}

fn aplicar_periodo_pagina(page: &mut Pagina, months: Option<u8>) {
    page.vista.date_months = months;
    for visual in &mut page.visuales {
        visual.vista.date_months = months;
    }
}

impl Pagina {
    fn quitar_medida(&mut self, measure: ObjectId) {
        quitar_medida_de_vista(&mut self.vista, measure);
        self.historial.olvidar();
        for visual in &mut self.visuales {
            quitar_medida_de_vista(&mut visual.vista, measure);
        }
        for bookmark in &mut self.bookmarks {
            for visual in &mut bookmark.visuales {
                quitar_medida_de_vista(&mut visual.vista, measure);
            }
        }
    }
}

fn quitar_medida_de_vista(vista: &mut Vista, measure: ObjectId) {
    vista.selection.measures.retain(|id| *id != measure);
    vista
        .selection
        .value_order
        .retain(|value| !matches!(value, ValueSelection::Measure(id) if *id == measure));
    if vista.top_n.is_some_and(|top| top.measure == measure) {
        vista.top_n = None;
    }
}

/// Cuantos pasos guarda el historial.
///
/// Un tope y no historia infinita: cada paso es una seleccion y una lista de filtros, pero el
/// tope tambien dice donde termina lo que se puede deshacer. Cincuenta alcanza para el trabajo
/// de una sesion.
const HISTORIAL_MAX: usize = 50;

/// Las dos pilas de deshacer y rehacer.
///
/// Es una pila y no parte de `Datan`: asi el orden de los pasos se prueba sin una ventana, que
/// es lo unico que no se puede montar en un test. La app solo le pasa la vista actual.
#[derive(Clone)]
struct Historial<T = Vista> {
    atras: Vec<T>,
    adelante: Vec<T>,
}

impl<T> Default for Historial<T> {
    fn default() -> Self {
        Self {
            atras: Vec::new(),
            adelante: Vec::new(),
        }
    }
}

impl<T> Historial<T> {
    /// Anota la vista que se va a abandonar. Un cambio nuevo borra el futuro: despues de
    /// deshacer y tocar otra cosa, rehacer ya no lleva a ninguna parte.
    fn recordar(&mut self, vista: T) {
        self.adelante.clear();
        if self.atras.len() == HISTORIAL_MAX {
            self.atras.remove(0);
        }
        self.atras.push(vista);
    }

    /// Devuelve la vista anterior y guarda la actual para rehacer. `None` si no hay nada.
    fn deshacer(&mut self, actual: T) -> Option<T> {
        let vista = self.atras.pop()?;
        self.adelante.push(actual);
        Some(vista)
    }

    fn rehacer(&mut self, actual: T) -> Option<T> {
        let vista = self.adelante.pop()?;
        self.atras.push(actual);
        Some(vista)
    }

    fn descartar_rehacer(&mut self) {
        self.adelante.clear();
    }

    fn registrar_interaccion(&mut self, lectura: bool, vista: T) {
        if lectura {
            self.descartar_rehacer();
        } else {
            self.recordar(vista);
        }
    }

    /// Olvida todo. Se llama cuando cambia el MODELO o el informe: los ids del historial son
    /// de otra cosa y restaurarlos apuntaria a columnas que ya no estan.
    fn olvidar(&mut self) {
        self.atras.clear();
        self.adelante.clear();
    }
}

