struct PerfilNumerico {
    minimo: f64,
    maximo: f64,
    media: f64,
    distribucion: [usize; 8],
}

fn perfil_numerico(values: &[&str]) -> Option<PerfilNumerico> {
    let parsed: Vec<f64> = values
        .iter()
        .filter_map(|value| value.trim().parse::<f64>().ok())
        .filter(|number| number.is_finite())
        .collect();
    let first = *parsed.first()?;
    let mut minimo = first;
    let mut maximo = first;
    for number in parsed.iter().copied().skip(1) {
        minimo = minimo.min(number);
        maximo = maximo.max(number);
    }
    let mut distribucion = [0; 8];
    let scale = minimo.abs().max(maximo.abs()).max(f64::MIN_POSITIVE);
    let normalized_min = minimo / scale;
    let span = maximo / scale - normalized_min;
    for number in &parsed {
        let bucket = if span == 0.0 {
            0
        } else {
            (((*number / scale - normalized_min) / span * distribucion.len() as f64) as usize)
                .min(distribucion.len() - 1)
        };
        distribucion[bucket] += 1;
    }
    Some(PerfilNumerico {
        minimo,
        maximo,
        media: parsed
            .iter()
            .map(|number| *number / parsed.len() as f64)
            .sum(),
        distribucion,
    })
}

