    fn crear_informe_vacio(&mut self, cx: &mut Context<Self>) {
        self.report_save_request = self.report_save_request.wrapping_add(1);
        self.report_save_in_flight = false;
        self.report_navigation_request = self.report_navigation_request.wrapping_add(1);
        self.refresh_seq = self.refresh_seq.wrapping_add(1);
        let mut source_model = self
            .data_source_model
            .clone()
            .or_else(|| self.report.as_ref().map(|report| report.model.clone()));
        if let Some(model) = source_model.as_mut() {
            model.tables.retain(|table| {
                !self
                    .loaded_query_tables
                    .contains(&table.name.to_ascii_lowercase())
            });
            self.data_source_types = data_doc::DataDoc::source_column_types(model);
        }
        self.state = State::Ready;
        self.report = Some(Report::new(Model::default()));
        self.database = None;
        self.loaded_query_tables.clear();
        self.report_data_scope = new_report_data_scope();
        self.saved_report_data_scope = None;
        self.report_source_key = None;
        self.data_source_model = source_model;
        self.filters.clear();
        self.visual_filters.clear();
        self.report_filters.clear();
        self.selection.dimensions.clear();
        self.selection.measures.clear();
        self.selection.implicit_measures.clear();
        self.selection.value_order.clear();
        self.visual = "Todo".to_string();
        self.sort = None;
        self.top_n = None;
        self.date_months = None;
        self.data_table = None;
        self.data_preview = None;
        self.data_query_drafts.clear();
        self.data_query_draft.clear();
        self.data_preview_request = self.data_preview_request.wrapping_add(1);
        self.selected_column = None;
        self.selected_relationship = None;
        self.model_positions.clear();
        self.model_warnings.clear();
        self.jerarquias.clear();
        self.expanded.clear();
        self.last_refreshed_at = None;
        self.workspace = WorkspaceView::Informe;
        self.formula_error = None;
        self.olvidar_historial();
        self.report_name = Some("Informe sin título".to_string());
        self.saved_report_path = None;
        self.project_path = None;
        self.paginas = vec![pagina_vacia("Página 1".to_string(), self.vista())];
        self.pagina_activa = 0;
        self.matrix = None;
        self.grid = None;
        self.totals.clear();
        self.stats = None;
        self.last_saved = None;
        self.report_dirty = true;
        self.lectura = false;
        cx.notify();
    }

    fn request_new_report(&mut self, cx: &mut Context<Self>) {
        if self.report.is_some() && self.report_dirty {
            self.report_navigation_request = self.report_navigation_request.wrapping_add(1);
            self.pending_report_navigation = Some(PendingReportNavigation::NewReport);
            cx.notify();
            return;
        }
        self.crear_informe_vacio(cx);
    }

    fn abrir_datanx(&mut self, cx: &mut Context<Self>) {
        cx.spawn(async move |this, cx| {
            let file = rfd::AsyncFileDialog::new()
                .add_filter("Informe Datan", &["dtx", "datanx", "datanr"])
                .pick_file()
                .await;
            if let Some(file) = file {
                let path = file.path().to_path_buf();
                let kind = project_doc::document_kind(&path);
                _ = this.update(cx, |view, cx| match kind {
                    Ok(project_doc::DocumentKind::Report) => {
                        let name = path
                            .file_stem()
                            .map(|name| name.to_string_lossy().into_owned())
                            .unwrap_or_else(|| "Informe".to_string());
                        view.open_report_at(&name, Some(path), cx);
                    }
                    Ok(project_doc::DocumentKind::Project) => {
                        view.open_project_at(path, cx);
                    }
                    Err(error) => {
                        view.stats = Some(format!("no se pudo abrir el archivo: {error}"));
                        cx.notify();
                    }
                });
            }
        })
        .detach();
    }

    fn cargar_datanx(&mut self, path: PathBuf, cx: &mut Context<Self>) {
        match project_doc::DatanxDocument::load(&path) {
            Ok(document) => {
                let document_title = document.title.clone();
                let saved_model_positions = document.model_positions.clone();
                self.refresh_seq = self.refresh_seq.wrapping_add(1);
                let mut model = Model::default();
                self.database = None;
                self.report_data_scope = document.data_scope.unwrap_or_else(new_report_data_scope);
                self.saved_report_data_scope = Some(self.report_data_scope.clone());
                self.report_source_key = document.source_key;
                let mut loaded_queries = Vec::new();
                if let (Some(source_key), Some(scope)) = (
                    self.report_source_key.as_deref(),
                    Some(self.report_data_scope.as_str()),
                ) {
                    let key = report_data_key(source_key, scope);
                    let mut data = match data_doc::DataDoc::load(&key) {
                        Ok(data) => data,
                        Err(error) => {
                            self.stats =
                                Some(format!("no se pudieron restaurar las consultas: {error}"));
                            cx.notify();
                            return;
                        }
                    };
                    if data.loaded_queries.is_empty() {
                        for query in &document.loaded_queries {
                            let loaded = data_doc::LoadedQueryDoc {
                                table: query.table.clone(),
                                source_sql: query.source_sql.clone(),
                                columns: query.columns.clone(),
                                column_types: query.column_types.clone(),
                            };
                            data.set_loaded_query(loaded.clone());
                            bind_loaded_query_source(
                                &mut data,
                                &loaded,
                                self.active_connection.as_ref().is_some_and(|connection| {
                                    connection.document_key() == source_key
                                        && connection.mode == config::ConnectionMode::Import
                                }),
                            );
                        }
                        if let Err(error) = data.save(&key) {
                            self.stats =
                                Some(format!("no se pudieron restaurar las consultas: {error}"));
                            cx.notify();
                            return;
                        }
                    }
                    loaded_queries = data.loaded_queries;
                }
                for query in &loaded_queries {
                    if let Err(error) = push_loaded_query_table(&mut model, query) {
                        self.stats = Some(error);
                        cx.notify();
                        return;
                    }
                }
                self.loaded_query_tables = loaded_queries
                    .iter()
                    .map(|query| query.table.to_ascii_lowercase())
                    .collect();
                self.model_positions = posiciones_modelo_resueltas(&model, &saved_model_positions);
                self.report = Some(Report::new(model.clone()));
                self.data_source_model = Some(model.clone());
                self.data_source_types = data_doc::DataDoc::source_column_types(&model);
                self.data_preview_request = self.data_preview_request.wrapping_add(1);
                self.selection.dimensions.clear();
                self.selection.measures.clear();
                self.selection.implicit_measures.clear();
                self.selection.value_order.clear();
                self.filters.clear();
                self.visual_filters.clear();
                self.report_filters.clear();
                self.visual = "Todo".to_string();
                self.sort = None;
                self.top_n = None;
                self.date_months = None;
                self.matrix = None;
                self.grid = None;
                self.totals.clear();
                self.data_table = None;
                self.data_preview = None;
                self.data_query_drafts.clear();
                self.data_query_draft.clear();
                self.selected_column = None;
                self.selected_relationship = None;
                self.model_positions.clear();
                self.model_warnings.clear();
                self.jerarquias.clear();
                self.expanded.clear();
                self.workspace = WorkspaceView::Informe;
                self.formula_error = None;
                self.olvidar_historial();
                self.panel_datos_visible = document.panels.datos;
                self.panel_filtros_visible = document.panels.filtros;
                self.panel_visualizaciones_visible = document.panels.visualizaciones;
                self.report_name = Some(document.title);
                datan_report::saved::mark_opened_path(&document_title, &path);
                self.last_saved = document.saved_at.or_else(|| archivo_modificado_en(&path));
                self.report_dirty = false;
                self.saved_report_path = None;
                self.project_path = Some(path);
                self.paginas = document
                    .pages
                    .iter()
                    .map(|saved| {
                        let canvas_size = saved.canvas_size.normalized();
                        let vista = Self::vista_guardada(&model, saved);
                        let visuals = saved
                            .visuals
                            .iter()
                            .map(|visual| {
                                Self::visual_guardado(
                                    &model,
                                    visual,
                                    canvas_size,
                                    saved.formato.get(&visual.kind).copied(),
                                )
                            })
                            .collect::<Vec<_>>();
                        let visual_activo = if visuals.iter().any(|v| v.id == saved.active_visual) {
                            saved.active_visual.clone()
                        } else {
                            String::new()
                        };
                        Pagina {
                            nombre: saved.name.clone(),
                            canvas_size,
                            vista,
                            filtros: Vec::new(),
                            historial: Historial::default(),
                            visuales: visuals,
                            visual_activo,
                            interacciones_grafico: std::collections::BTreeMap::new(),
                            bookmarks: Vec::new(),
                            zoom_percent: saved.zoom_percent.unwrap_or(100),
                        }
                    })
                    .collect();
                if self.paginas.is_empty() {
                    self.paginas
                        .push(pagina_vacia("Página 1".to_string(), self.vista()));
                }
                self.pagina_activa = document.active_page.min(self.paginas.len() - 1);
                self.state = State::Ready;
                self.lectura = false;
                self.stats = None;
            }
            Err(error) => self.stats = Some(format!("no se pudo abrir el archivo: {error}")),
        }
        cx.notify();
    }

    fn open_project_at(&mut self, path: PathBuf, cx: &mut Context<Self>) {
        if self.report.is_some() && self.report_dirty {
            self.report_navigation_request = self.report_navigation_request.wrapping_add(1);
            self.pending_report_navigation = Some(PendingReportNavigation::OpenProject { path });
            cx.notify();
            return;
        }
        self.cargar_datanx(path, cx);
    }

    fn guardar_datanx(&mut self, cx: &mut Context<Self>) {
        let save_request = self.report_save_request;
        let navigation_request = self.report_navigation_request;
        self.guardar_pagina_actual();
        let title = self.report_title();
        let pages = self
            .paginas
            .iter()
            .map(|page| self.pagina_guardada(page))
            .collect();
        let mut document =
            project_doc::DatanxDocument::new(title.clone(), pages, self.pagina_activa);
        document.model_positions = self
            .report
            .as_ref()
            .map(|report| posiciones_modelo_guardadas(&report.model, &self.model_positions))
            .unwrap_or_default();
        document.panels = self.paneles_informe();
        document.data_scope = Some(self.report_data_scope.clone());
        let saved_scope = self.report_data_scope.clone();
        document.source_key = self.report_source_key.clone();
        if let Some(source_key) = self.report_source_key.as_deref() {
            let key = report_data_key(source_key, &self.report_data_scope);
            match data_doc::DataDoc::load(&key) {
                Ok(data) => {
                    document.loaded_queries = data
                        .loaded_queries
                        .into_iter()
                        .map(|query| datan_report::saved::SavedSourceTable {
                            table: query.table,
                            source_sql: query.source_sql,
                            columns: query.columns,
                            column_types: query.column_types,
                        })
                        .collect();
                }
                Err(error) => {
                    self.stats = Some(format!("no se pudo guardar el origen del informe: {error}"));
                    self.report_save_in_flight = false;
                    self.terminar_guardado_pendiente_de_cierre(false, cx);
                    cx.notify();
                    return;
                }
            }
        }
        let existing_path = self.project_path.clone();
        cx.spawn(async move |this, cx| {
            let path = match existing_path {
                Some(path) => Some(path),
                None => rfd::AsyncFileDialog::new()
                    .set_file_name(format!("{title}.dtx"))
                    .add_filter("Informe Datan", &["dtx"])
                    .save_file()
                    .await
                    .map(|file| file.path().to_path_buf()),
            };
            if let Some(path) = path {
                let path = match project_doc::report_path(&path) {
                    Ok(path) => path,
                    Err(error) => {
                        _ = this.update(cx, |view, cx| {
                            if view.report_save_request != save_request {
                                return;
                            }
                            view.report_save_in_flight = false;
                            view.stats = Some(format!("no se pudo guardar: {error}"));
                            view.terminar_guardado_pendiente_de_cierre(false, cx);
                            cx.notify();
                        });
                        return;
                    }
                };
                let saved_name = path
                    .file_stem()
                    .and_then(|name| name.to_str())
                    .filter(|name| !name.trim().is_empty())
                    .unwrap_or(&title)
                    .to_string();
                document.title = saved_name.clone();
                let saved_at = epoch_now();
                let mut document = document;
                document.saved_at = Some(saved_at);
                let result = document.save(&path);
                _ = this.update(cx, |view, cx| {
                    if view.report_save_request != save_request {
                        return;
                    }
                    view.report_save_in_flight = false;
                    let exitoso = result.is_ok();
                    match result {
                        Ok(()) => {
                            datan_report::saved::mark_opened_path(&saved_name, &path);
                            view.project_path = Some(path);
                            view.saved_report_data_scope = Some(saved_scope);
                            view.report_name = Some(saved_name);
                            view.last_saved = Some(saved_at);
                            view.report_dirty = false;
                            view.stats = Some("guardado".to_string());
                            view.continue_report_navigation_after_save(navigation_request, cx);
                        }
                        Err(error) => view.stats = Some(format!("no se pudo guardar: {error}")),
                    }
                    view.terminar_guardado_pendiente_de_cierre(exitoso, cx);
                    cx.notify();
                });
            } else {
                _ = this.update(cx, |view, cx| {
                    if view.report_save_request == save_request {
                        view.report_save_in_flight = false;
                        view.terminar_guardado_pendiente_de_cierre(false, cx);
                        cx.notify();
                    }
                });
            }
        })
        .detach();
    }

    /// Las conexiones guardadas que se pueden abrir desde el inicio.
    fn render_connections(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme().clone();
        let brand = rgb(0x3267e8);
        let connections = match &*self.conexiones_guardadas() {
            Ok(connections) => connections.clone(),
            Err(error) => {
                return div()
                    .text_size(px(tokens::LETRA_CUERPO))
                    .text_color(theme.muted_foreground)
                    .child(format!("No se pudieron leer las conexiones: {error}"))
                    .into_any_element();
            }
        };
        let database_icon = r##"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><ellipse cx="12" cy="5" rx="8" ry="3" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="M4 5v14c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3" fill="none" stroke="currentColor" stroke-width="1.7"/></svg>"##;
        let mut list = div().flex_col().gap_1();

        if connections.list.is_empty() {
            list = list.child(
                div()
                    .py_4()
                    .text_size(px(tokens::LETRA_CUERPO))
                    .text_color(theme.muted_foreground)
                    .child("No hay conexiones guardadas."),
            );
        }

        for connection in &connections.list {
            let profile = connection.clone();
            list = list.child(
                div()
                    .id(ElementId::Name(SharedString::from(format!(
                        "home-conn-{}:{}-{}-{}:{}-{}:{}",
                        connection.host.len(),
                        connection.host,
                        connection.port,
                        connection.database.len(),
                        connection.database,
                        connection.username.len(),
                        connection.username
                    ))))
                    .w_full()
                    .flex()
                    .items_center()
                    .justify_between()
                    .gap_4()
                    .px_3()
                    .py_3()
                    .rounded_lg()
                    .cursor_pointer()
                    .hover(|style| style.bg(theme.list_hover))
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap_3()
                            .child(
                                svg()
                                    .data(database_icon.as_bytes())
                                    .size(px(18.0))
                                    .text_color(brand),
                            )
                            .child(
                                div()
                                    .flex_col()
                                    .gap_1()
                                    .child(
                                        div()
                                            .font_weight(FontWeight::MEDIUM)
                                            .child(connection.name.clone()),
                                    )
                                    .child(
                                        div()
                                            .text_size(px(tokens::LETRA_ETIQUETA))
                                            .text_color(theme.muted_foreground)
                                            .child(format!(
                                                "{}:{} · {}",
                                                connection.host,
                                                connection.port,
                                                connection.database
                                            )),
                                    ),
                            ),
                    )
                    .child(
                        div()
                            .text_size(px(tokens::LETRA_ETIQUETA))
                            .text_color(theme.muted_foreground)
                            .child("Conectar"),
                    )
                    .on_click(cx.listener(move |view, _event, window, cx| {
                        view.open_postgres_profile(profile.clone(), window, cx)
                    })),
            );
        }

        list.into_any_element()
    }

    fn render_recent_reports(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme().clone();
        let brand = rgb(0x3267e8);
        let reports = self.recientes_de_inicio();
        let profiles = match &*self.conexiones_guardadas() {
            Ok(connections) => connections.list.clone(),
            Err(_) => Vec::new(),
        };
        let active_key = self
            .active_connection
            .as_ref()
            .map(config::PostgresConnection::document_key);
        let mut list = div().flex_col().gap_1();

        if reports.is_empty() {
            list = list.child(
                div()
                    .py_4()
                    .text_size(px(tokens::LETRA_CUERPO))
                    .text_color(theme.muted_foreground)
                    .child("Los informes que guardes aparecerán aquí."),
            );
        }

        for report in reports.iter().take(8) {
            let report_name = report.name.clone();
            let path = report.path.clone();
            let kind = report.kind;
            let source_key = report.source_key.clone();
            let is_current_source = match source_key.as_ref() {
                Some(key) => active_key.as_ref() == Some(key),
                None => kind == datan_report::saved::SavedKind::Project,
            };
            let matching_profile = profiles.iter().find(|profile| {
                if let Some(source_key) = report.source_key.as_deref() {
                    config::PostgresConnection {
                        name: profile.name.clone(),
                        host: profile.host.clone(),
                        port: profile.port,
                        username: profile.username.clone(),
                        password: String::new(),
                        database: profile.database.clone(),
                        sslmode: profile.sslmode.clone(),
                        mode: profile.mode,
                        table: profile.table.clone(),
                        source_query: profile.source_query.clone(),
                    }
                    .document_key()
                        == source_key
                } else {
                    false
                }
            });
            let profile = matching_profile.cloned().or_else(|| {
                source_key.as_deref().and_then(|source_key| {
                    config::Connection::from_document_key(
                        if report.database.is_empty() {
                            report.name.clone()
                        } else {
                            report.database.clone()
                        },
                        source_key,
                    )
                })
            });
            let source_state =
                recent_report_source(is_current_source, source_key.is_some(), profile);
            let subtitle = format!(
                "{} · {}",
                if report.database.is_empty() {
                    "Archivo Datan"
                } else {
                    report.database.as_str()
                },
                match &source_state {
                    RecentReportSource::Current => "Abrir",
                    RecentReportSource::Choose => "Elige el origen al abrir",
                    RecentReportSource::Reconnect(_) => "Conectar para abrir",
                    RecentReportSource::Unavailable => "Origen no disponible",
                }
            );
            let item = div()
                .id(ElementId::Name(SharedString::from(format!(
                    "home-document-{}",
                    path.display()
                ))))
                .w_full()
                .flex()
                .items_center()
                .justify_between()
                .gap_4()
                .px_3()
                .py_3()
                .rounded_lg()
                .child(
                    div()
                        .flex_col()
                        .gap_1()
                        .child(
                            div()
                                .font_weight(FontWeight::MEDIUM)
                                .child(report.name.clone()),
                        )
                        .child(
                            div()
                                .text_size(px(tokens::LETRA_ETIQUETA))
                                .text_color(theme.muted_foreground)
                                .child(subtitle),
                        ),
                )
                .child(
                    div()
                        .text_size(px(tokens::LETRA_ETIQUETA))
                        .text_color(brand)
                        .child(match &source_state {
                            RecentReportSource::Current => "Abrir",
                            RecentReportSource::Choose | RecentReportSource::Reconnect(_) => {
                                "Conectar"
                            }
                            RecentReportSource::Unavailable => "Origen no disponible",
                        }),
                );
            let item = if matches!(source_state, RecentReportSource::Unavailable) {
                item.text_color(theme.muted_foreground)
            } else {
                item.cursor_pointer()
                    .hover(|style| style.bg(theme.list_hover))
                    .on_click(cx.listener(move |view, _event, window, cx| {
                        match (kind, source_state.clone()) {
                            (
                                datan_report::saved::SavedKind::Report,
                                RecentReportSource::Choose,
                            ) => {
                                view.pending_home_document = Some(PendingHomeDocument::Report {
                                    name: report_name.clone(),
                                    path: path.clone(),
                                });
                                view.data_connection_dialog = Some(DataConnectionDialog::Sources);
                                cx.notify();
                            }
                            (
                                datan_report::saved::SavedKind::Report,
                                RecentReportSource::Current,
                            ) => {
                                view.open_report_at(&report_name, Some(path.clone()), cx);
                            }
                            (
                                datan_report::saved::SavedKind::Project,
                                RecentReportSource::Current,
                            ) => {
                                view.cargar_datanx(path.clone(), cx);
                            }
                            (_, RecentReportSource::Reconnect(profile)) => {
                                view.pending_home_document = Some(match kind {
                                    datan_report::saved::SavedKind::Report => {
                                        PendingHomeDocument::Report {
                                            name: report_name.clone(),
                                            path: path.clone(),
                                        }
                                    }
                                    datan_report::saved::SavedKind::Project => {
                                        PendingHomeDocument::Project { path: path.clone() }
                                    }
                                });
                                view.open_postgres_profile(profile, window, cx);
                            }
                            (_, RecentReportSource::Unavailable)
                            | (
                                datan_report::saved::SavedKind::Project,
                                RecentReportSource::Choose,
                            ) => {}
                        }
                    }))
            };
            list = list.child(item);
        }

        list.into_any_element()
    }

