fn data_preview_column_type(
    name: &str,
    physical_columns: &[&datan_model::Column],
    steps: &[data_doc::QueryStep],
) -> Option<datan_model::DataType> {
    let mut source_name = name.to_string();
    let mut changed_type = None;
    for step in steps.iter().rev() {
        match step {
            data_doc::QueryStep::RenameColumn { column, new_name }
                if source_name.eq_ignore_ascii_case(new_name) =>
            {
                source_name = column.clone();
            }
            data_doc::QueryStep::ChangeType {
                column,
                column_type,
            } if changed_type.is_none() && source_name.eq_ignore_ascii_case(column) => {
                changed_type = Some(column_type.model_type());
            }
            _ => {}
        }
    }
    changed_type.or_else(|| {
        physical_columns
            .iter()
            .find(|column| column.name.eq_ignore_ascii_case(&source_name))
            .map(|column| column.data_type)
    })
}

fn debe_conservar_borrador_query(
    misma_tabla: bool,
    pasos_previsualizados: Option<&[data_doc::QueryStep]>,
    borrador: &[data_doc::QueryStep],
) -> bool {
    misma_tabla && pasos_previsualizados.is_some_and(|pasos| pasos != borrador)
}

fn actualiza_borrador_query(
    borradores: &mut std::collections::BTreeMap<ObjectId, Vec<data_doc::QueryStep>>,
    tabla: ObjectId,
    pasos_guardados: &[data_doc::QueryStep],
    borrador: &[data_doc::QueryStep],
) {
    if pasos_guardados == borrador {
        borradores.remove(&tabla);
    } else {
        borradores.insert(tabla, borrador.to_vec());
    }
}

#[cfg(test)]
mod query_draft_tests {
    use super::{ObjectId, actualiza_borrador_query, data_doc};
    use std::collections::BTreeMap;

    #[test]
    fn guarda_borradores_sin_aplicar_por_tabla_y_los_quita_al_volver_a_guardado() {
        let table = ObjectId(7);
        let saved = vec![data_doc::QueryStep::RemoveDuplicates];
        let draft = vec![data_doc::QueryStep::RemoveEmptyRows {
            column: "Fecha".to_string(),
        }];
        let mut drafts = BTreeMap::new();

        actualiza_borrador_query(&mut drafts, table, &saved, &draft);
        assert_eq!(drafts.get(&table), Some(&draft));

        actualiza_borrador_query(&mut drafts, table, &saved, &saved);
        assert!(!drafts.contains_key(&table));
    }

    #[test]
    fn conserva_un_borrador_vacio_si_el_usuario_quito_todos_los_pasos() {
        let table = ObjectId(9);
        let saved = vec![data_doc::QueryStep::RemoveDuplicates];
        let mut drafts = BTreeMap::new();

        actualiza_borrador_query(&mut drafts, table, &saved, &[]);

        assert_eq!(drafts.get(&table), Some(&Vec::new()));
    }
}

