/// Un punto de un grafico: la categoria y el valor de la primera medida.
#[derive(Clone)]
struct Punto {
    /// El lugar que ocupa en la serie. Es el indice de la paleta: sin el, el color de una
    /// porcion se elige desde afuera del dato.
    indice: usize,
    etiqueta: String,
    clave_categoria: Vec<String>,
    valor: f64,
    color_condicional: Option<u32>,
    formato: Option<formato::Formato>,
    detalles: Vec<String>,
}

fn medidor_de_matriz(
    matrix: &Matrix,
    dimension_count: usize,
    selection: &Selection,
    fields: GaugeFields,
    model: &Model,
    source_id: &str,
    formats: &std::collections::HashMap<ObjectId, formato::Formato>,
) -> Option<visuales::Medidor> {
    let column_for = |value: ValueSelection| match value {
        ValueSelection::Measure(id) => matrix
            .headers
            .iter()
            .position(|header| header.measure == Some(id)),
        ValueSelection::Implicit(_, _) => implicit_for_value(selection, value)
            .and_then(|measure| etiqueta_agregacion(model, measure))
            .and_then(|label| {
                matrix
                    .headers
                    .iter()
                    .position(|header| header.label == label)
            }),
    };
    let fallback_value = selection
        .value_order
        .first()
        .copied()
        .or_else(|| {
            selection
                .measures
                .first()
                .copied()
                .map(ValueSelection::Measure)
        })
        .or_else(|| {
            selection
                .implicit_measures
                .first()
                .map(|measure| measure.selection())
        });
    let value_field = fields.value.or(fallback_value)?;
    let value_column = column_for(value_field).unwrap_or(dimension_count);
    let value_at = |row: &[String], column: usize| {
        row.get(column)
            .and_then(|value| value.parse::<f64>().ok())
            .filter(|value| value.is_finite())
    };
    let total_row = matrix
        .rows
        .iter()
        .enumerate()
        .find(|(index, _)| matrix.row_kind(*index) == RowKind::GrandTotal)
        .map(|(_, row)| row)
        .or_else(|| {
            (dimension_count == 0)
                .then(|| {
                    matrix
                        .rows
                        .iter()
                        .enumerate()
                        .find(|(index, _)| matrix.row_kind(*index) == RowKind::Data)
                        .map(|(_, row)| row)
                })
                .flatten()
        })?;
    let value = value_at(total_row, value_column)?;
    let (automatic_minimum, automatic_maximum) = if value < 0.0 {
        (finite_scaled_range(value), 0.0)
    } else {
        (0.0, finite_scaled_range(value).max(1.0))
    };
    let boundary_value = |field: Option<ValueSelection>| {
        let column = column_for(field?)?;
        value_at(total_row, column)
    };
    let requested_minimum = boundary_value(fields.minimum).unwrap_or(automatic_minimum);
    let requested_maximum = boundary_value(fields.maximum).unwrap_or(automatic_maximum);
    let (minimum, maximum) = if requested_minimum < requested_maximum {
        (requested_minimum, requested_maximum)
    } else {
        (automatic_minimum, automatic_maximum)
    };
    let format = match value_field {
        ValueSelection::Measure(id) => Some(id),
        ValueSelection::Implicit(_, _) => None,
    }
    .and_then(|id| formats.get(&id))
    .cloned();
    let label = matrix
        .header(value_column)
        .and_then(|header| header.measure)
        .and_then(|id| model.measures.iter().find(|measure| measure.id == id))
        .map(|measure| measure.name.as_str())
        .map(str::to_string)
        .or_else(|| {
            matrix
                .header(value_column)
                .map(|header| header.label.clone())
        })
        .unwrap_or_else(|| "Valor".to_string());
    Some(visuales::Medidor {
        id: source_id.to_string(),
        etiqueta: label,
        valor: value,
        minimo: minimum,
        maximo: maximum,
        objetivo: boundary_value(fields.target),
        formato: format,
    })
}

fn finite_scaled_range(value: f64) -> f64 {
    let scaled = value * 1.2;
    if scaled.is_finite() { scaled } else { value }
}

#[derive(Clone)]
struct PuntoDispersion {
    indice: usize,
    etiqueta: String,
    clave_categoria: Vec<String>,
    x: f64,
    y: f64,
    color_condicional: Option<u32>,
    medida_x: String,
    medida_y: String,
}

fn puntos_de_matriz_dispersion(matrix: &Matrix, dimension_count: usize) -> Vec<PuntoDispersion> {
    matrix
        .rows
        .iter()
        .enumerate()
        .filter(|(index, _)| matrix.row_kind(*index) == RowKind::Data)
        .filter_map(|(_, row)| {
            let clave_categoria = row.get(..dimension_count)?.to_vec();
            let x = row.get(dimension_count)?.parse::<f64>().ok()?;
            let y = row.get(dimension_count + 1)?.parse::<f64>().ok()?;
            if !x.is_finite() || !y.is_finite() {
                return None;
            }
            Some((clave_categoria, x, y))
        })
        .enumerate()
        .map(|(indice, (clave_categoria, x, y))| PuntoDispersion {
            indice,
            etiqueta: clave_categoria.join(" · "),
            clave_categoria,
            x,
            y,
            color_condicional: None,
            medida_x: matrix
                .header(dimension_count)
                .map(|header| header.label.clone())
                .unwrap_or_default(),
            medida_y: matrix
                .header(dimension_count + 1)
                .map(|header| header.label.clone())
                .unwrap_or_default(),
        })
        .collect()
}

fn colorear_dispersion_por_leyenda(
    points: &mut [PuntoDispersion],
    series_labels: &[String],
    overrides: &std::collections::BTreeMap<String, u32>,
) {
    for point in points {
        let Some(series) = point.clave_categoria.last() else {
            continue;
        };
        let Some(index) = series_labels.iter().position(|label| label == series) else {
            continue;
        };
        point.color_condicional = Some(color_serie_leyenda(series, index, overrides));
    }
}

fn puntos_dispersion_con_color_condicional(
    mut points: Vec<PuntoDispersion>,
    matrix: &Matrix,
    measure: &str,
    comparison_measure: Option<&str>,
    format: datan_report::saved::SavedFormato,
    rules: &[datan_report::saved::SavedConditionalColorRule],
) -> Vec<PuntoDispersion> {
    let Some(value_column) = matrix
        .headers
        .iter()
        .position(|header| header.label == measure)
    else {
        return points;
    };
    let comparison_column = comparison_measure.and_then(|measure| {
        matrix
            .headers
            .iter()
            .position(|header| header.label == measure)
    });
    if comparison_measure.is_some() && comparison_column.is_none() {
        return points;
    }
    let rows_by_category: std::collections::HashMap<Vec<String>, &Vec<String>> = matrix
        .rows
        .iter()
        .enumerate()
        .filter(|(index, _)| matrix.row_kind(*index) == RowKind::Data)
        .filter_map(|(_, row)| {
            let key = row.get(..points.first()?.clave_categoria.len())?.to_vec();
            Some((key, row))
        })
        .collect();
    for point in &mut points {
        let row = rows_by_category.get(&point.clave_categoria).copied();
        let value = row
            .and_then(|row| row.get(value_column))
            .and_then(|value| value.parse::<f64>().ok());
        let comparison = comparison_column.and_then(|column| {
            row.and_then(|row| row.get(column))
                .and_then(|value| value.parse::<f64>().ok())
        });
        point.color_condicional = value.and_then(|value| {
            if !rules.is_empty() {
                color_condicional_por_umbral(rules, value)
            } else if comparison_measure.is_some() {
                comparison.and_then(|comparison| {
                    color_condicional_por_regla(format, value, Some(comparison))
                })
            } else {
                color_condicional_por_regla(format, value, None)
            }
        });
    }
    points
}

#[derive(Clone)]
struct PuntoCombinado {
    indice: usize,
    etiqueta: String,
    clave_categoria: Vec<String>,
    barras: f64,
    linea: f64,
    formato_barras: Option<formato::Formato>,
    formato_linea: Option<formato::Formato>,
}

struct SerieCombinada {
    puntos: Vec<PuntoCombinado>,
    total: usize,
}

fn puntos_combinados(
    matrix: &Matrix,
    dimension_count: usize,
    limit: usize,
    formatos: &std::collections::HashMap<ObjectId, formato::Formato>,
) -> SerieCombinada {
    let points: Vec<(Vec<String>, f64, f64)> = matrix
        .rows
        .iter()
        .enumerate()
        .filter(|(index, _)| matrix.row_kind(*index) == RowKind::Data)
        .filter_map(|(_, row)| {
            let key = row.get(..dimension_count)?.to_vec();
            let bars = row.get(dimension_count)?.parse::<f64>().ok()?;
            let line = row.get(dimension_count + 1)?.parse::<f64>().ok()?;
            if !bars.is_finite() || !line.is_finite() {
                return None;
            }
            Some((key, bars, line))
        })
        .collect();
    let total = points.len();
    let puntos = points
        .into_iter()
        .take(limit)
        .enumerate()
        .map(
            |(indice, (clave_categoria, barras, linea))| PuntoCombinado {
                indice,
                etiqueta: clave_categoria.join(" · "),
                clave_categoria,
                barras,
                linea,
                formato_barras: matrix
                    .header(dimension_count)
                    .and_then(|header| header.measure)
                    .and_then(|measure| formatos.get(&measure))
                    .cloned(),
                formato_linea: matrix
                    .header(dimension_count + 1)
                    .and_then(|header| header.measure)
                    .and_then(|measure| formatos.get(&measure))
                    .cloned(),
            },
        )
        .collect();
    SerieCombinada { puntos, total }
}

fn rango_serie_combinada(points: &[PuntoCombinado]) -> (f64, f64) {
    let Some((minimum, maximum)) = points.iter().fold(None::<(f64, f64)>, |range, point| {
        Some(match range {
            None => (point.linea, point.linea),
            Some((minimum, maximum)) => (minimum.min(point.linea), maximum.max(point.linea)),
        })
    }) else {
        return (0.0, 1.0);
    };
    if (maximum - minimum).abs() < f64::EPSILON {
        (minimum - 1.0, maximum + 1.0)
    } else {
        (minimum, maximum)
    }
}

fn rango_barras_combinadas(points: &[PuntoCombinado]) -> (f64, f64) {
    let (minimum, maximum) = points
        .iter()
        .fold((0.0_f64, 0.0_f64), |(minimum, maximum), point| {
            (minimum.min(point.barras), maximum.max(point.barras))
        });
    if (maximum - minimum).abs() < f64::EPSILON {
        (minimum, maximum + 1.0)
    } else {
        (minimum, maximum)
    }
}

fn tooltip_combinado(point: &PuntoCombinado, medida_barras: &str, medida_linea: &str) -> String {
    format!(
        "{} · {}: {} · {}: {}",
        point.etiqueta,
        medida_barras,
        format_value_with(point.barras, point.formato_barras.as_ref()),
        medida_linea,
        format_value_with(point.linea, point.formato_linea.as_ref()),
    )
}

fn puntos_de_matriz(
    matrix: &Matrix,
    dimension_count: usize,
    limit: usize,
    por_valor: bool,
) -> Vec<Punto> {
    puntos_de_matriz_con_formatos(
        matrix,
        dimension_count,
        limit,
        por_valor,
        &std::collections::HashMap::new(),
    )
}

fn puntos_de_matriz_con_formatos(
    matrix: &Matrix,
    dimension_count: usize,
    limit: usize,
    por_valor: bool,
    formatos: &std::collections::HashMap<ObjectId, formato::Formato>,
) -> Vec<Punto> {
    let mut points: Vec<(String, Vec<String>, f64, Vec<String>)> =
        crate::visuales::filas_de_datos(matrix)
            .filter_map(|(_, row)| {
                let key = row.get(..dimension_count)?.to_vec();
                let label = key.join(" · ");
                let value = row.get(dimension_count)?.parse::<f64>().ok()?;
                if !value.is_finite() {
                    return None;
                }
                let details = (dimension_count + 1..row.len())
                    .filter_map(|index| {
                        let name = matrix.header(index)?.label.clone();
                        let value = row.get(index)?;
                        let format = matrix
                            .header(index)
                            .and_then(|header| header.measure)
                            .and_then(|measure| formatos.get(&measure));
                        let display = value.parse::<f64>().map_or_else(
                            |_| value.clone(),
                            |number| format_value_with(number, format),
                        );
                        Some(format!("{name}: {display}"))
                    })
                    .collect();
                Some((label, key, value, details))
            })
            .collect();
    if por_valor {
        points.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal));
    }
    points.truncate(limit);
    points
        .into_iter()
        .enumerate()
        .map(
            |(indice, (etiqueta, clave_categoria, valor, detalles))| Punto {
                indice,
                etiqueta,
                clave_categoria,
                valor,
                color_condicional: None,
                formato: matrix
                    .header(dimension_count)
                    .and_then(|header| header.measure)
                    .and_then(|measure| formatos.get(&measure))
                    .cloned(),
                detalles,
            },
        )
        .collect()
}

fn puntos_con_color_condicional(
    mut points: Vec<Punto>,
    matrix: &Matrix,
    measure: &str,
    comparison_measure: Option<&str>,
    format: datan_report::saved::SavedFormato,
    rules: &[datan_report::saved::SavedConditionalColorRule],
) -> Vec<Punto> {
    let Some(value_column) = matrix
        .headers
        .iter()
        .position(|header| header.label == measure)
    else {
        return points;
    };
    let comparison_column = comparison_measure.and_then(|measure| {
        matrix
            .headers
            .iter()
            .position(|header| header.label == measure)
    });
    if comparison_measure.is_some() && comparison_column.is_none() {
        return points;
    }
    for point in &mut points {
        let dimensions = point.clave_categoria.len();
        let row = matrix
            .rows
            .iter()
            .enumerate()
            .find(|(index, row)| {
                matrix.row_kind(*index) == RowKind::Data
                    && row
                        .get(..dimensions)
                        .is_some_and(|key| key == point.clave_categoria)
            })
            .map(|(_, row)| row);
        let driver_value = row
            .and_then(|row| row.get(value_column))
            .and_then(|value| value.parse::<f64>().ok());
        let comparison_value = comparison_column.and_then(|column| {
            row.and_then(|row| row.get(column))
                .and_then(|value| value.parse::<f64>().ok())
        });
        point.color_condicional = driver_value.and_then(|value| {
            if !rules.is_empty() {
                color_condicional_por_umbral(rules, value)
            } else if comparison_measure.is_some() {
                comparison_value.and_then(|comparison| {
                    color_condicional_por_regla(format, value, Some(comparison))
                })
            } else {
                color_condicional_por_regla(format, value, None)
            }
        });
    }
    points
}

fn promedio_de_matriz(matrix: &Matrix, dimension_count: usize) -> Option<f64> {
    let values: Vec<f64> = matrix
        .rows
        .iter()
        .enumerate()
        .filter(|(index, _)| matrix.row_kind(*index) == RowKind::Data)
        .filter_map(|(_, row)| row.get(dimension_count)?.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .collect();
    (!values.is_empty()).then(|| values.iter().sum::<f64>() / values.len() as f64)
}

fn extremos_de_matriz(matrix: &Matrix, dimension_count: usize) -> Option<(f64, f64)> {
    matrix
        .rows
        .iter()
        .enumerate()
        .filter(|(index, _)| matrix.row_kind(*index) == RowKind::Data)
        .filter_map(|(_, row)| row.get(dimension_count)?.parse::<f64>().ok())
        .filter(|value| value.is_finite())
        .fold(None, |range: Option<(f64, f64)>, value| {
            Some(range.map_or((value, value), |(minimum, maximum)| {
                (minimum.min(value), maximum.max(value))
            }))
        })
}

/// Cuantos valores entran en un grafico.
///
/// Ocho barras se leen de un golpe. Veinte no: el eje de categorias se convierte en una
/// lista de nombres imposible de seguir.
const TOPE: usize = 8;
const TOPE_CATEGORIAS_LEYENDA: usize = 100;

fn categorias_de_matriz(
    matrix: &Matrix,
    dimension_count: usize,
    puntos_visibles: &[Punto],
) -> (Vec<Punto>, bool) {
    let mut keys = std::collections::HashSet::new();
    let mut categorias = Vec::with_capacity(TOPE_CATEGORIAS_LEYENDA);
    for punto in puntos_visibles {
        if keys.insert(punto.clave_categoria.clone()) {
            categorias.push(punto.clone());
        }
    }

    let mut filas_leidas = 0;
    for (row_index, row) in matrix.rows.iter().enumerate() {
        filas_leidas = row_index + 1;
        if matrix.row_kind(row_index) != RowKind::Data {
            continue;
        }
        let Some(key) = row.get(..dimension_count) else {
            continue;
        };
        let key = key.to_vec();
        if !keys.insert(key.clone()) {
            continue;
        }
        categorias.push(Punto {
            indice: categorias.len(),
            etiqueta: key.join(" · "),
            clave_categoria: key,
            valor: 0.0,
            color_condicional: None,
            formato: None,
            detalles: Vec::new(),
        });
        if categorias.len() == TOPE_CATEGORIAS_LEYENDA
            || filas_leidas == TOPE_CATEGORIAS_LEYENDA * 5
        {
            break;
        }
    }

    let quedan_mas = matrix.truncated || filas_leidas < matrix.rows.len();
    (categorias, quedan_mas)
}

/// Lo que hace falta para armar la tarjeta de un grafico.
#[derive(Clone, Copy)]
struct Grafico<'a> {
    /// La clave del tipo elegido.
    tipo: &'a str,
    puntos: &'a [Punto],
    series_leyenda: &'a [String],
    series_datos: Option<&'a visuales::DatosSeries>,
    series_colors: &'a std::collections::BTreeMap<String, u32>,
    series_omitidas: usize,
    categorias: &'a [Punto],
    categorias_incompletas: bool,
    /// Los puntos de una dispersion: (x, y) por categoria. Vacio en los demas graficos.
    nube: &'a [PuntoDispersion],
    formatos_eje: [Option<&'a formato::Formato>; 2],
    velas: &'a [visuales::Vela],
    nodos_flujo: &'a [visuales::NodoFlujo],
    enlaces_flujo: &'a [gpui_kit::component::plot::shape::SankeyLink],
    /// El nombre de la medida, para el titulo.
    medida: &'a str,
    /// El nombre de la dimension, para el titulo.
    dimension: &'a str,
    dimension_ids: &'a [ObjectId],
    source_id: &'a str,
    highlight: Option<&'a Matrix>,
    referencia_promedio: Option<f64>,
    extremos: Option<(f64, f64)>,
    /// Cuantas filas tiene la matriz: el titulo dice cuantas quedaron afuera.
    filas: usize,
    /// El formato del visual: titulo, fondo, etiquetas y eje.
    formato: datan_report::saved::SavedFormato,
    kpi_valor: f64,
    kpi_objetivo: Option<(&'a str, f64)>,
    medidor: Option<&'a visuales::Medidor>,
    /// El alto del dibujo. `None` cuando el grafico es lo unico del lienzo: ahi ocupa lo
    /// que sobra en la ventana, que es lo que hace la referencia.
    alto: Option<f32>,
    zoom: f32,
}

fn matrix_contiene_categoria(matrix: &Matrix, key: &[String]) -> bool {
    let dimension_count = matrix
        .headers
        .iter()
        .take_while(|header| header.is_dimension())
        .count();
    matrix.rows.iter().enumerate().any(|(index, row)| {
        matrix.row_kind(index) == RowKind::Data
            && row
                .get(..dimension_count)
                .is_some_and(|values| values == key)
    })
}

fn matriz_tiene_filas_de_datos(matrix: &Matrix) -> bool {
    matrix
        .rows
        .iter()
        .enumerate()
        .any(|(index, _)| matrix.row_kind(index) == RowKind::Data)
}

fn tooltip_de_punto(point: &Punto, value: f64) -> SharedString {
    let mut values = vec![format_value_with(value, point.formato.as_ref())];
    values.extend(point.detalles.iter().cloned());
    SharedString::from(values.join(" · "))
}

fn format_value_with(value: f64, formato: Option<&formato::Formato>) -> String {
    formato.map_or_else(|| format_value(value), |formato| formato.aplicar(value))
}

fn tooltip_de_dispersion(
    point: &PuntoDispersion,
    formatos_eje: [Option<&formato::Formato>; 2],
) -> String {
    format!(
        "{} · {}: {} · {}: {}",
        point.etiqueta,
        point.medida_x,
        format_value_with(point.x, formatos_eje[0]),
        point.medida_y,
        format_value_with(point.y, formatos_eje[1]),
    )
}

fn desplazamiento_hit_dispersion(fraccion: f32) -> f32 {
    6.0 * (1.0 - 2.0 * fraccion) - 8.0
}

fn formatos_de_medidas<'a>(
    matrix: &Matrix,
    inicio: usize,
    formatos: &'a std::collections::HashMap<ObjectId, formato::Formato>,
) -> [Option<&'a formato::Formato>; 2] {
    [inicio, inicio + 1].map(|index| {
        matrix
            .header(index)
            .and_then(|header| header.measure)
            .and_then(|measure| formatos.get(&measure))
    })
}

fn ajuste_lineal(values: &[f64]) -> Option<(f64, f64)> {
    if values.len() < 2 {
        return None;
    }
    let count = values.len() as f64;
    let mean_x = (count - 1.0) / 2.0;
    let mean_y = values.iter().sum::<f64>() / count;
    let numerator = values
        .iter()
        .enumerate()
        .map(|(index, value)| (index as f64 - mean_x) * (value - mean_y))
        .sum::<f64>();
    let denominator = values
        .iter()
        .enumerate()
        .map(|(index, _)| (index as f64 - mean_x).powi(2))
        .sum::<f64>();
    (denominator > 0.0).then_some((
        mean_y - numerator / denominator * mean_x,
        numerator / denominator,
    ))
}

fn pronostico_lineal(values: &[f64], periods: usize) -> Vec<f64> {
    let Some((intercept, slope)) = ajuste_lineal(values) else {
        return Vec::new();
    };
    (0..periods)
        .map(|period| intercept + slope * (values.len() + period) as f64)
        .collect()
}

fn rango_analitico(
    points: &[Punto],
    references: &[f64],
    trend: bool,
    forecast: bool,
) -> (f64, f64) {
    let values: Vec<f64> = points.iter().map(|point| point.valor).collect();
    let mut range_values = values.clone();
    if trend {
        if let Some((intercept, slope)) = ajuste_lineal(&values) {
            range_values.extend((0..values.len()).map(|index| intercept + slope * index as f64));
        }
    }
    if forecast {
        range_values.extend(pronostico_lineal(&values, 3));
    }
    range_values.extend_from_slice(references);
    let (minimum, maximum) = range_values
        .iter()
        .copied()
        .fold(None, |range: Option<(f64, f64)>, value| {
            Some(range.map_or((value, value), |(min, max)| {
                (min.min(value), max.max(value))
            }))
        })
        .unwrap_or((0.0, 1.0));
    if (maximum - minimum).abs() < f64::EPSILON {
        (minimum - 1.0, maximum + 1.0)
    } else {
        (minimum, maximum)
    }
}

fn overlay_analitica(
    oscuro: bool,
    chart: AnyElement,
    points: &[Punto],
    references: Vec<f64>,
    show_trend: bool,
    show_forecast: bool,
    axis: bool,
    zoom: f32,
) -> AnyElement {
    let values: Vec<f64> = points.iter().map(|point| point.valor).collect();
    let trend = if show_trend {
        ajuste_lineal(&values)
            .map(|(intercept, slope)| {
                (0..values.len())
                    .map(|index| intercept + slope * index as f64)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default()
    } else {
        Vec::new()
    };
    let forecast = if show_forecast {
        pronostico_lineal(&values, 3)
    } else {
        Vec::new()
    };
    let (minimum, maximum) = rango_analitico(points, &references, show_trend, show_forecast);
    let span = (maximum - minimum).max(f64::MIN_POSITIVE);
    let future = forecast.len();
    let points_len = values.len();
    let trend_color = tokens::serie(1, oscuro);
    let forecast_color = tokens::serie(3, oscuro);
    let overlay = canvas(
        move |bounds, window, _cx| {
            if !axis {
                return 0.0;
            }
            let axis_gap = gpui_kit::component::plot::label::TEXT_SIZE * zoom
                + gpui_kit::component::plot::label::TEXT_GAP * 4.0 * zoom;
            let height = (bounds.size.height.as_f32() - axis_gap).max(10.0);
            (0..4)
                .map(|index| {
                    let y = height * index as f32 / 3.0;
                    let value = if height <= 10.0 * zoom {
                        minimum
                    } else {
                        minimum
                            + (maximum - minimum) * ((height - y) / (height - 10.0 * zoom)) as f64
                    };
                    gpui_kit::component::plot::label::measure_text_width(
                        &SharedString::from(format_value(value)),
                        px(gpui_kit::component::plot::label::TEXT_SIZE * zoom),
                        window,
                    ) + gpui_kit::component::plot::label::TEXT_GAP * 2.0 * zoom
                })
                .fold(32.0_f32 * zoom, f32::max)
        },
        move |bounds, gutter, window, _cx| {
            let left = px(gutter);
            let top = px(10.0 * zoom);
            let bottom = px(28.0 * zoom);
            let width = (bounds.size.width - left).max(px(1.0 * zoom));
            let height = (bounds.size.height - top - bottom).max(px(1.0 * zoom));
            let total = points_len + future;
            if total == 0 {
                return;
            }
            let x = |index: usize| {
                bounds.origin.x
                    + left
                    + width * (index as f32 / total.saturating_sub(1).max(1) as f32)
            };
            let y = |value: f64| {
                bounds.origin.y + top + height * (1.0 - ((value - minimum) / span) as f32)
            };
            let mut paint_line = |series: &[f64], start: usize, color| {
                if series.len() < 2 {
                    return;
                }
                let mut path = PathBuilder::stroke(px(2.0 * zoom));
                path.move_to(point(x(start), y(series[0])));
                for (index, value) in series.iter().enumerate().skip(1) {
                    path.line_to(point(x(start + index), y(*value)));
                }
                if let Ok(path) = path.build() {
                    window.paint_path(path, color);
                }
            };
            if show_trend {
                paint_line(&trend, 0, trend_color);
            }
            if show_forecast && !values.is_empty() && !forecast.is_empty() {
                let mut series = vec![*values.last().unwrap_or(&forecast[0])];
                series.extend(forecast.iter().copied());
                paint_line(&series, points_len.saturating_sub(1), forecast_color);
            }
            for (index, reference) in references.iter().copied().enumerate() {
                let mut path = PathBuilder::stroke(px(1.0 * zoom));
                path.move_to(point(x(0), y(reference)));
                path.line_to(point(x(total.saturating_sub(1)), y(reference)));
                if let Ok(path) = path.build() {
                    window.paint_path(path, tokens::serie((4 + index) % 6, oscuro));
                }
            }
        },
    )
    .absolute()
    .top_0()
    .left_0()
    .w_full()
    .h_full();
    div()
        .relative()
        .flex_1()
        .child(chart)
        .child(overlay)
        .into_any_element()
}

fn overlay_color_condicional_lineal(
    chart: AnyElement,
    points: &[Punto],
    base_color: Hsla,
    domain: Option<(f64, f64)>,
    axis: bool,
    area: bool,
    point_count: usize,
    zoom: f32,
) -> AnyElement {
    if !points.iter().any(|point| point.color_condicional.is_some()) || points.is_empty() {
        return chart;
    }
    let data = points.to_vec();
    let (minimum, maximum) = domain.unwrap_or_else(|| {
        let (minimum, maximum) = data.iter().fold((0.0_f64, 0.0_f64), |(lo, hi), point| {
            (lo.min(point.valor), hi.max(point.valor))
        });
        (minimum, maximum)
    });
    let (minimum, maximum) = if (maximum - minimum).abs() <= f64::EPSILON {
        if minimum == 0.0 {
            (0.0, 1.0)
        } else {
            (minimum - 0.5, maximum + 0.5)
        }
    } else {
        (minimum, maximum)
    };
    let span = maximum - minimum;
    if !span.is_finite() || span <= f64::EPSILON {
        return chart;
    }
    let format = data.first().and_then(|point| point.formato.clone());
    let overlay = canvas(
        move |bounds, window, _cx| {
            if !axis {
                return 0.0;
            }
            let text_size = gpui_kit::component::plot::label::TEXT_SIZE * zoom;
            let text_gap = gpui_kit::component::plot::label::TEXT_GAP * zoom;
            let axis_gap = text_size + text_gap * 4.0;
            let height = (bounds.size.height.as_f32() - axis_gap).max(10.0);
            (0..4)
                .map(|index| {
                    let y = height * index as f32 / 3.0;
                    let value = minimum + span * ((height - y) / (height - 10.0)).max(0.0) as f64;
                    gpui_kit::component::plot::label::measure_text_width(
                        &SharedString::from(format_value_with(value, format.as_ref())),
                        px(text_size),
                        window,
                    ) + text_gap * 2.0
                })
                .fold(32.0_f32 * zoom, f32::max)
        },
        move |bounds, gutter, window, _cx| {
            let text_size = gpui_kit::component::plot::label::TEXT_SIZE * zoom;
            let text_gap = gpui_kit::component::plot::label::TEXT_GAP * zoom;
            let axis_gap = text_size + text_gap * 4.0;
            let plot_height = (bounds.size.height.as_f32() - axis_gap).max(1.0);
            let top = 10.0;
            let usable_height = (plot_height - top).max(1.0);
            let left = px(gutter);
            let width = (bounds.size.width - left).max(px(1.0 * zoom));
            let x = |index: usize| {
                bounds.origin.x
                    + left
                    + width * (index as f32 / point_count.saturating_sub(1).max(1) as f32)
            };
            let y = |value: f64| {
                bounds.origin.y
                    + px(top + usable_height * (1.0 - ((value - minimum) / span) as f32))
            };
            let bottom = bounds.origin.y + px(plot_height);
            for (index, pair) in data.windows(2).enumerate() {
                let first = &pair[0];
                let second = &pair[1];
                let color = second
                    .color_condicional
                    .or(first.color_condicional)
                    .map_or(base_color, |color| rgb(color & 0x00ff_ffff).into());
                if area {
                    let mut fill_path = PathBuilder::fill();
                    fill_path.move_to(point(x(index), y(first.valor)));
                    fill_path.line_to(point(x(index + 1), y(second.valor)));
                    fill_path.line_to(point(x(index + 1), bottom));
                    fill_path.line_to(point(x(index), bottom));
                    fill_path.close();
                    if let Ok(path) = fill_path.build() {
                        window.paint_path(path, color.opacity(0.18));
                    }
                }
                let mut line = PathBuilder::stroke(px(2.0));
                line.move_to(point(x(index), y(first.valor)));
                line.line_to(point(x(index + 1), y(second.valor)));
                if let Ok(path) = line.build() {
                    window.paint_path(path, color);
                }
            }
            for (index, datum) in data.iter().enumerate() {
                let color = datum
                    .color_condicional
                    .map_or(base_color, |color| rgb(color & 0x00ff_ffff).into());
                let diameter = px(6.0);
                let position = point(x(index), y(datum.valor));
                window.paint_quad(
                    fill(
                        Bounds::new(
                            position - point(diameter / 2.0, diameter / 2.0),
                            size(diameter, diameter),
                        ),
                        color,
                    )
                    .corner_radii(Corners::all(diameter / 2.0)),
                );
            }
        },
    )
    .absolute()
    .top_0()
    .left_0()
    .w_full()
    .h_full();
    div()
        .relative()
        .flex_1()
        .child(chart)
        .child(overlay)
        .into_any_element()
}

fn overlay_color_condicional_radar(
    chart: AnyElement,
    points: &[Punto],
    base_color: Hsla,
    zoom: f32,
) -> AnyElement {
    if !points.iter().any(|point| point.color_condicional.is_some()) || points.is_empty() {
        return chart;
    }
    let data = points.to_vec();
    let (minimum, maximum) = data
        .iter()
        .map(|point| point.valor)
        .chain(std::iter::once(0.0))
        .fold((f64::INFINITY, f64::NEG_INFINITY), |(lo, hi), value| {
            (lo.min(value), hi.max(value))
        });
    let (minimum, maximum) = if (maximum - minimum).abs() <= f64::EPSILON {
        if minimum == 0.0 {
            (0.0, 1.0)
        } else {
            (minimum - 0.5, maximum + 0.5)
        }
    } else {
        (minimum, maximum)
    };
    let span = maximum - minimum;
    if !span.is_finite() || span <= f64::EPSILON {
        return chart;
    }
    let overlay = canvas(
        move |_bounds, _window, _cx| (),
        move |bounds, (), window, _cx| {
            let count = data.len();
            let radius = bounds.size.height.as_f32() * 0.4;
            let center_x = bounds.size.width.as_f32() / 2.0;
            let center_y = bounds.size.height.as_f32() / 2.0;
            let coordinates = data
                .iter()
                .enumerate()
                .map(|(index, datum)| {
                    let angle = index as f32 * std::f32::consts::TAU / count as f32
                        - std::f32::consts::FRAC_PI_2;
                    let point_radius = radius * ((datum.valor - minimum) / span) as f32;
                    (
                        point(
                            bounds.origin.x + px(center_x + point_radius * angle.cos()),
                            bounds.origin.y + px(center_y + point_radius * angle.sin()),
                        ),
                        datum
                            .color_condicional
                            .map_or(base_color, |color| rgb(color & 0x00ff_ffff).into()),
                    )
                })
                .collect::<Vec<_>>();
            for index in 0..count {
                let next = (index + 1) % count;
                let (start, color) = coordinates[index];
                let (end, _) = coordinates[next];
                let mut line = PathBuilder::stroke(px(2.0));
                line.move_to(start);
                line.line_to(end);
                if let Ok(path) = line.build() {
                    window.paint_path(path, color);
                }
            }
            for (position, color) in coordinates {
                let diameter = px(6.0 * zoom);
                window.paint_quad(
                    fill(
                        Bounds::new(
                            position - point(diameter / 2.0, diameter / 2.0),
                            size(diameter, diameter),
                        ),
                        color,
                    )
                    .corner_radii(Corners::all(diameter / 2.0)),
                );
            }
        },
    )
    .absolute()
    .top_0()
    .left_0()
    .w_full()
    .h_full();
    div()
        .relative()
        .flex_1()
        .child(chart)
        .child(overlay)
        .into_any_element()
}

/// La tarjeta de un grafico: el titulo, el dibujo y, en el anillo, la leyenda.
///
/// El titulo se arma con el nombre de la medida y el de la dimension. Son los nombres del
/// modelo y no se traducen: un grafico que dice "Ventas" cuando la medida se llama
/// `product_boleta quantity` manda al usuario a buscar un campo que no existe.
#[derive(Clone, Copy, PartialEq, Eq)]
enum MarcoGrafico {
    Interno,
    ContenedorLienzo,
}

fn card_grafico(
    theme: &Theme,
    grafico: &Grafico,
    cx: &mut Context<Datan>,
    marco: MarcoGrafico,
) -> AnyElement {
    let Grafico {
        tipo,
        puntos,
        series_leyenda,
        series_datos,
        series_colors,
        series_omitidas,
        categorias,
        categorias_incompletas,
        nube,
        formatos_eje,
        velas,
        nodos_flujo,
        enlaces_flujo,
        medida,
        dimension,
        dimension_ids,
        source_id,
        highlight,
        referencia_promedio,
        extremos,
        filas,
        formato,
        kpi_valor,
        kpi_objetivo,
        medidor,
        alto,
        zoom,
    } = *grafico;
    let axes = ChartAxes::from(formato);
    let scale = f32::from(formato.escala_texto.clamp(70, 160)) / 100.0;
    let title_scale = scale * f32::from(formato.escala_titulo.clamp(70, 160)) / 100.0;
    let foreground = if formato.color_texto == 0 {
        theme.foreground
    } else {
        rgb(formato.color_texto & 0x00ff_ffff).into()
    };
    let (label_color, plot_label_color) = color_etiquetas_grafico(formato, theme);
    let title_foreground = if formato.color_titulo == 0 {
        foreground
    } else {
        rgb(formato.color_titulo & 0x00ff_ffff).into()
    };
    let (promedio_analitico, extremos_analiticos) = if tipo == "Dispersion" {
        nube.iter().map(|point| point.y).fold(None, |range: Option<(f64, f64, f64, usize)>, value| {
            Some(range.map_or((value, value, value, 1), |(sum, minimum, maximum, count)| {
                (sum + value, minimum.min(value), maximum.max(value), count + 1)
            }))
        }).map_or((None, None), |(sum, minimum, maximum, count)| {
            (Some(sum / count as f64), Some((minimum, maximum)))
        })
    } else {
        (referencia_promedio, extremos)
    };
    let mut referencias = Vec::new();
    if formato.linea_referencia
        && let Some(value) = promedio_analitico
    {
        referencias.push(value);
    }
    if formato.linea_minimo && let Some((value, _)) = extremos_analiticos {
        referencias.push(value);
    }
    if formato.linea_maximo && let Some((_, value)) = extremos_analiticos {
        referencias.push(value);
    }
    if formato.linea_constante {
        referencias.push(formato.valor_linea_constante_milesimas as f64 / 1000.0);
    }
    referencias.sort_by(f64::total_cmp);
    referencias.dedup_by(|left, right| (*left - *right).abs() < f64::EPSILON);
    let mut tarjeta_titulo = div().flex().items_center().gap(px_lienzo(8.0, zoom));
    // Cuantos valores quedaron afuera. Un grafico que dibuja ocho de quinientas filas y no
    // lo dice es un grafico que miente con el eje. La nota va con el titulo: sin titulo, el
    // aviso del recorte flota sobre el dibujo sin decir de que habla.
    if formato.titulo && marco == MarcoGrafico::Interno {
        tarjeta_titulo = tarjeta_titulo
            .child(
                components::titulo_tarjeta_zoom(theme, titulo_de(medida, dimension), zoom)
                    .text_size(px_lienzo(tokens::LETRA_TITULO * title_scale, zoom))
                    .text_color(title_foreground),
            )
            .child(div().flex_1());
        if filas > puntos.len() && tipo != "Medidor" {
            tarjeta_titulo = tarjeta_titulo.child(components::nota_zoom(
                theme,
                if matches!(tipo, "Lineas" | "Area") {
                    format!("las {} primeras categorías", puntos.len())
                } else {
                    format!("los {} valores mas altos", puntos.len())
                },
                zoom,
            ));
        }
    }

    let puntos_custom: Vec<visuales::Punto> = puntos
        .iter()
        .map(|punto| {
            visuales::Punto::new(punto.etiqueta.clone(), punto.valor)
                .con_formato(punto.formato.clone())
        })
        .collect();
    let puntos_series: Vec<Punto> = series_datos.map_or_else(Vec::new, |series_data| {
        series_data
            .series
            .iter()
            .enumerate()
            .flat_map(|(series_index, series)| {
                series_data.categorias.iter().enumerate().filter_map(
                    move |(category_index, category)| {
                        let value = series.valores.get(category_index).copied().flatten()?;
                        let mut key = category.clone();
                        key.push(series.etiqueta.clone());
                        Some(Punto {
                            indice: series_index * series_data.categorias.len() + category_index,
                            etiqueta: format!("{} · {}", category.join(" · "), series.etiqueta),
                            clave_categoria: key,
                            valor: value,
                            color_condicional: Some(
                                [0x2563eb, 0x0d9488, 0xea580c, 0x7c3aed, 0xdc2626]
                                    [series_index % 5],
                            ),
                            formato: None,
                            detalles: Vec::new(),
                        })
                    },
                )
            })
            .collect()
    });
    let puntos_dibujo = if puntos_series.is_empty() {
        puntos
    } else {
        &puntos_series
    };

    let cuerpo: AnyElement = match tipo {
        // El anillo no lleva etiquetas sobre las porciones: ocho lineas de guia alrededor de
        // un circulo se pisan entre ellas. La leyenda dice lo mismo, en una columna, y cada
        // fila filtra.
        "Anillo" => {
            let puntos_anillo = puntos_con_colores_categoria(puntos, series_colors);
            div()
                .flex()
                .flex_1()
                .gap(px_lienzo(16.0, zoom))
                .child(div().flex_1().child(dibujo_con_click(
                    tipo,
                    &puntos_anillo,
                    velas,
                    nodos_flujo,
                    enlaces_flujo,
                    medida,
                    axes,
                    formato.color_serie,
                    formato.color_serie_rgb,
                    theme.is_dark(),
                    referencias.clone(),
                    formato.linea_tendencia,
                    formato.pronostico,
                    formato.radio_interior_anillo,
                    zoom,
                    scale,
                    plot_label_color,
                    source_id,
                    None,
                )))
                .child(leyenda(
                    theme,
                    &puntos_anillo,
                    dimension_ids,
                    source_id,
                    highlight,
                    zoom,
                    scale,
                    label_color,
                    cx,
                ))
                .into_any_element()
        }
        // Las barras horizontales se dibujan a mano porque son el clic: un grafico del
        // sistema no avisa que barra se toco, y filtrar por categoria desde el grafico es una
        // funcion que ya existe.
        "Barras" if series_datos.is_some() => barras_agrupadas(
            theme,
            series_datos.unwrap(),
            series_colors,
            dimension_ids,
            source_id,
            highlight,
            &referencias,
            axes,
            zoom,
            scale,
            label_color,
            cx,
        ),
        "Barras" | "Todo" => barras(
            theme,
            puntos_dibujo,
            dimension_ids,
            source_id,
            highlight,
            formato.etiquetas,
            formato.color_serie_rgb,
            &referencias,
            zoom,
            scale,
            label_color,
            cx,
        ),
        // Los puntos capturan el clic por categoria y aplican el mismo filtro que las barras.
        "Dispersion" => {
            let plot = dispersion(
                theme,
                nube,
                axes,
                formato.color_serie_rgb,
                formatos_eje,
                dimension_ids,
                source_id,
                highlight,
                referencias.clone(),
                zoom,
                scale,
                label_color,
                cx,
            );
            if let Some(series) = series_datos.filter(|series| !series.series.is_empty()) {
                div()
                    .flex()
                    .flex_col()
                    .gap(px_lienzo(8.0, zoom))
                    .child(plot)
                    .child(leyenda_dispersion(
                        theme,
                        series,
                        series_colors,
                        source_id,
                        zoom,
                        scale,
                        label_color,
                    ))
                    .into_any_element()
            } else {
                plot
            }
        }
        "Combinado" => card_vacio(
            theme,
            "Combinado",
            "El visual combinado no está disponible en esta vista.",
            formato,
            // La vista de un solo visual ocupa el lienzo: sin escala.
            zoom, 4096.0, 4096.0,
        ),
        "Embudo" => visuales::embudo_zoom_con_id_interactivo_y_escala(
            &puntos_custom,
            zoom,
            source_id,
            handlers_categoria(puntos, dimension_ids, source_id, cx),
            scale,
        ),
        "Medidor" => medidor.map_or_else(
            || {
                card_vacio(
                    theme,
                    "Medidor",
                    "No hay valores numéricos para mostrar en este medidor.",
                    formato,
                    zoom, 4096.0, 4096.0,
                )
            },
            |medidor| visuales::medidor_zoom_con_escala(medidor, zoom, scale),
        ),
        "Treemap" => visuales::treemap_zoom_con_id_interactivo_y_escala_con_colores(
            &puntos_custom,
            zoom,
            source_id,
            handlers_categoria(puntos, dimension_ids, source_id, cx),
            scale,
            formato.color_serie_rgb,
            formato.color_texto,
        ),
        "Cascada" => visuales::cascada_zoom_con_id_interactivo_y_escala(
            0.0,
            &puntos_custom,
            zoom,
            source_id,
            handlers_categoria(puntos, dimension_ids, source_id, cx),
            scale,
        ),
        "KPI" => {
            let kpi = visuales::TarjetaKpi {
                etiqueta: medida.to_string(),
                valor: kpi_valor,
                objetivo: kpi_objetivo.map(|(nombre, valor)| (nombre.to_string(), valor)),
                menor_es_mejor: formato.kpi_menor_es_mejor,
                escala_texto: f32::from(formato.escala_texto.clamp(70, 160)) / 100.0,
                color_valor: color_valor_kpi(
                    formato,
                    kpi_valor,
                    kpi_objetivo.map(|(_, objective)| objective),
                ),
            };
            if marco == MarcoGrafico::ContenedorLienzo {
                visuales::contenido_kpi_zoom_con_formato(
                    &kpi,
                    formato,
                    familia_tipografica(formato, theme),
                    zoom,
                )
            } else {
                visuales::tarjeta_kpi_zoom_con_formato(
                    &kpi,
                    formato,
                    familia_tipografica(formato, theme),
                    zoom,
                )
            }
        }
        "Sankey" => {
            let view = cx.entity();
            let nodes = nodos_flujo.to_vec();
            let dimensions = dimension_ids.to_vec();
            let source = source_id.to_string();
            let on_node_click =
                std::rc::Rc::new(move |index: usize, _window: &mut Window, app: &mut App| {
                    let Some(node) = nodes.get(index) else {
                        return;
                    };
                    let Some(&column) = dimensions.get(node.fase) else {
                        return;
                    };
                    let values = [node.etiqueta.clone()];
                    let _ = view.update(app, |view, cx| {
                        view.filter_by_category_from(&source, &[column], &values, cx);
                    });
                });
            div()
                .flex()
                .flex_1()
                .child(dibujo_con_click(
                    tipo,
                    puntos,
                    velas,
                    nodos_flujo,
                    enlaces_flujo,
                    medida,
                    axes,
                    formato.color_serie,
                    formato.color_serie_rgb,
                    theme.is_dark(),
                    referencias.clone(),
                    formato.linea_tendencia,
                    formato.pronostico,
                    formato.radio_interior_anillo,
                    zoom,
                    scale,
                    plot_label_color,
                    source_id,
                    Some(on_node_click),
                ))
                .into_any_element()
        }
        "Columnas" if series_datos.is_some() => columnas_agrupadas(
            theme,
            series_datos.unwrap(),
            series_colors,
            dimension_ids,
            source_id,
            highlight,
            &referencias,
            axes,
            zoom,
            scale,
            label_color,
            cx,
        ),
        "Lineas" | "Area" | "Radar" | "Columnas" => {
            let view = cx.entity();
            let marks = puntos_dibujo.to_vec();
            let dimensions = dimension_ids.to_vec();
            let source = source_id.to_string();
            let on_mark_click =
                std::rc::Rc::new(move |index: usize, _window: &mut Window, app: &mut App| {
                    let Some(point) = marks.iter().find(|point| point.indice == index) else {
                        return;
                    };
                    let values = point.clave_categoria.clone();
                    let _ = view.update(app, |view, cx| {
                        view.filter_by_category_from(&source, &dimensions, &values, cx);
                    });
                });
            div()
                .flex()
                .flex_1()
                .child(
                    if let Some(series_data) =
                        series_datos.filter(|_| matches!(tipo, "Lineas" | "Area"))
                    {
                        dibujo_series_con_click(
                            tipo,
                            series_data,
                            series_colors,
                            medida,
                            referencias.clone(),
                            axes,
                            theme.is_dark(),
                            zoom,
                            scale,
                            plot_label_color,
                            Some(on_mark_click.clone()),
                        )
                    } else {
                        dibujo_con_click(
                            tipo,
                            puntos_dibujo,
                            velas,
                            nodos_flujo,
                            enlaces_flujo,
                            medida,
                            axes,
                            formato.color_serie,
                            formato.color_serie_rgb,
                            theme.is_dark(),
                            referencias.clone(),
                            formato.linea_tendencia,
                            formato.pronostico,
                            formato.radio_interior_anillo,
                            zoom,
                            scale,
                            plot_label_color,
                            source_id,
                            Some(on_mark_click),
                        )
                    },
                )
                .into_any_element()
        }
        "Candlestick" => {
            let view = cx.entity();
            let candles = velas.to_vec();
            let dimensions = dimension_ids.to_vec();
            let source = source_id.to_string();
            let on_mark_click =
                std::rc::Rc::new(move |index: usize, _window: &mut Window, app: &mut App| {
                    let Some(candle) = candles.get(index) else {
                        return;
                    };
                    let values = candle.clave_categoria.clone();
                    let _ = view.update(app, |view, cx| {
                        view.filter_by_category_from(&source, &dimensions, &values, cx);
                    });
                });
            div()
                .flex()
                .flex_1()
                .child(dibujo_con_click(
                    tipo,
                    puntos,
                    velas,
                    nodos_flujo,
                    enlaces_flujo,
                    medida,
                    axes,
                    formato.color_serie,
                    formato.color_serie_rgb,
                    theme.is_dark(),
                    referencias.clone(),
                    formato.linea_tendencia,
                    formato.pronostico,
                    formato.radio_interior_anillo,
                    zoom,
                    scale,
                    plot_label_color,
                    source_id,
                    Some(on_mark_click),
                ))
                .into_any_element()
        }
        _ => div()
            .flex()
            .flex_1()
            .child(dibujo_con_click(
                tipo,
                puntos,
                velas,
                nodos_flujo,
                enlaces_flujo,
                medida,
                axes,
                formato.color_serie,
                formato.color_serie_rgb,
                theme.is_dark(),
                referencias.clone(),
                formato.linea_tendencia,
                formato.pronostico,
                formato.radio_interior_anillo,
                zoom,
                scale,
                plot_label_color,
                source_id,
                None,
            ))
            .into_any_element(),
    };

    // Sin marco interno en ninguna variante: el visual llena su tarjeta, y el borde que se
    // personaliza en Propiedades es el de la tarjeta general, como en Power BI.
    let mut tarjeta = div()
        .flex()
        .flex_col()
        .flex_1()
        .min_h_0()
        .overflow_hidden()
        .gap(px_lienzo(12.0, zoom))
        .text_size(px_lienzo(tokens::LETRA_CUERPO * scale, zoom))
        .text_color(foreground);
    if let Some(font_family) = familia_tipografica(formato, theme) {
        tarjeta = tarjeta.font_family(font_family);
    };
    if marco == MarcoGrafico::Interno {
        if formato.titulo {
            tarjeta = tarjeta.child(tarjeta_titulo);
        }
    }
    if formato.leyenda && matches!(tipo, "Columnas" | "Lineas" | "Area" | "Radar") {
        let color_serie = if formato.color_serie_rgb == 0 {
            tokens::serie(formato.color_serie as usize, theme.is_dark())
        } else {
            rgb(formato.color_serie_rgb & 0x00ff_ffff).into()
        };
        tarjeta = tarjeta.child(
            div()
                .flex()
                .items_center()
                .gap(px_lienzo(8.0, zoom))
                .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, scale))
                .text_color(label_color)
                .child(
                    div()
                        .size(px_lienzo((8.0), zoom))
                        .rounded_full()
                        .bg(color_serie),
                )
                .child(medida.to_string()),
        );
    }
    if matches!(tipo, "Lineas" | "Area") && (formato.linea_tendencia || formato.pronostico) {
        let mut legend = div()
            .flex()
            .gap(px_lienzo(12.0, zoom))
            .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, scale))
            .text_color(label_color);
        if formato.linea_tendencia {
            legend = legend.child(
                div()
                    .flex()
                    .items_center()
                    .gap(px_lienzo(4.0, zoom))
                    .child(
                        div()
                            .w(px_lienzo((8.0), zoom))
                            .h(px_lienzo((2.0), zoom))
                            .bg(theme.chart_bullish),
                    )
                    .child("Tendencia"),
            );
        }
        if formato.pronostico {
            legend = legend.child(
                div()
                    .flex()
                    .items_center()
                    .gap(px_lienzo(4.0, zoom))
                    .child(
                        div()
                            .w(px_lienzo((8.0), zoom))
                            .h(px_lienzo((2.0), zoom))
                            .bg(theme.chart_bearish),
                    )
                    .child("Pronóstico"),
            );
        }
        tarjeta = tarjeta.child(legend);
    }
    if matches!(tipo, "Lineas" | "Area" | "Dispersion" | "Barras" | "Columnas")
        && !referencias.is_empty()
    {
        let mut labels = div()
            .flex()
            .flex_wrap()
            .gap_x(px_lienzo(10.0, zoom))
            .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, scale))
            .text_color(label_color);
        if formato.linea_referencia
            && let Some(value) = promedio_analitico
        {
            labels = labels.child(format!("Promedio: {}", format_value(value)));
        }
        if formato.linea_minimo
            && let Some((value, _)) = extremos_analiticos
        {
            labels = labels.child(format!("Mínimo: {}", format_value(value)));
        }
        if formato.linea_maximo
            && let Some((_, value)) = extremos_analiticos
        {
            labels = labels.child(format!("Máximo: {}", format_value(value)));
        }
        if formato.linea_constante {
            labels = labels.child(format!(
                "Valor fijo: {}",
                format_value(formato.valor_linea_constante_milesimas as f64 / 1000.0)
            ));
        }
        tarjeta = tarjeta.child(labels);
    }
    tarjeta = tarjeta.child(cuerpo);
    if !series_leyenda.is_empty() {
        let mut series = div()
            .flex()
            .flex_wrap()
            .gap_x(px_lienzo(12.0, zoom))
            .gap_y(px_lienzo(5.0, zoom))
            .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, scale))
            .text_color(label_color);
        for (index, label) in series_leyenda.iter().enumerate() {
            series = series.child(
                div()
                    .flex()
                    .items_center()
                    .gap(px_lienzo(5.0, zoom))
                    .child(
                        div()
                            .w(px_lienzo(8.0, zoom))
                            .h(px_lienzo(8.0, zoom))
                            .rounded_full()
                            .bg(rgb(color_serie_leyenda(label, index, series_colors))),
                    )
                    .child(label.clone()),
            );
        }
        if series_omitidas > 0 {
            series = series.child(format!("y {series_omitidas} más"));
        }
        tarjeta = tarjeta.child(series);
    }
    if matches!(
        tipo,
        "Lineas"
            | "Area"
            | "Columnas"
            | "Radar"
            | "Embudo"
            | "Treemap"
            | "Cascada"
            | "Sankey"
            | "Candlestick"
    ) && !puntos.is_empty()
    {
        tarjeta = tarjeta.child(leyenda_categorias_interactiva(
            theme,
            categorias,
            categorias_incompletas,
            dimension_ids,
            source_id,
            highlight,
            zoom,
            scale,
            label_color,
            cx,
        ));
    }
    tarjeta = match alto {
        Some(alto) => tarjeta.h(px_lienzo((alto), zoom)).flex_shrink_0(),
        None => tarjeta.flex_1(),
    };
    tarjeta.into_any_element()
}

fn card_combinado(
    theme: &Theme,
    points: &[PuntoCombinado],
    measure_bars: &str,
    measure_line: &str,
    total_categories: usize,
    dimension_ids: &[ObjectId],
    source_id: &str,
    highlight: Option<&Matrix>,
    formato: datan_report::saved::SavedFormato,
    zoom: f32,
    cx: &mut Context<Datan>,
) -> AnyElement {
    let escala_texto = f32::from(formato.escala_texto.clamp(70, 160)) / 100.0;
    let color_bars = color_barras_combinadas(formato, theme.is_dark());
    let color_line = tokens::serie(formato.color_serie as usize + 1, theme.is_dark());
    let (line_min, line_max) = rango_serie_combinada(points);
    let (bars_min, bars_max) = rango_barras_combinadas(points);
    let source_id = source_id.to_string();
    let dimension_ids = dimension_ids.to_vec();
    let paint_points = points.to_vec();
    let highlighted: Vec<bool> = points
        .iter()
        .map(|point| {
            !highlight
                .is_some_and(|matrix| !matrix_contiene_categoria(matrix, &point.clave_categoria))
        })
        .collect();
    let highlighted_for_paint = highlighted.clone();
    let chart_height = 190.0 * zoom;
    let tick_labels = |minimum: f64, maximum: f64, value_format: Option<&formato::Formato>| {
        (0..5)
            .map(|index| {
                let value = maximum - (maximum - minimum) * index as f64 / 4.0;
                div()
                    .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, escala_texto))
                    .text_color(theme.muted_foreground)
                    .child(format_value_with(value, value_format))
            })
            .collect::<Vec<_>>()
    };
    let left_ticks = tick_labels(
        bars_min,
        bars_max,
        points.first().and_then(|p| p.formato_barras.as_ref()),
    );
    let right_ticks = tick_labels(
        line_min,
        line_max,
        points.first().and_then(|p| p.formato_linea.as_ref()),
    );
    let grid_color = theme.chart_grid;
    let chart = canvas(
        move |_bounds, _window, _cx| (),
        move |bounds, (), window, _cx| {
            let top = px(8.0 * zoom);
            let bottom = px(8.0 * zoom);
            let height = (bounds.size.height - top - bottom).max(px(1.0 * zoom));
            let width = bounds.size.width.max(px(1.0 * zoom));
            let y_bars = |value: f64| {
                bounds.origin.y
                    + top
                    + height * (1.0 - ((value - bars_min) / (bars_max - bars_min)) as f32)
            };
            let y_line = |value: f64| {
                bounds.origin.y
                    + top
                    + height * (1.0 - ((value - line_min) / (line_max - line_min)) as f32)
            };
            let mut grid = PathBuilder::stroke(px(1.0 * zoom));
            for tick in 0..=4 {
                let y = bounds.origin.y + top + height * tick as f32 / 4.0;
                grid.move_to(point(bounds.origin.x, y));
                grid.line_to(point(bounds.origin.x + width, y));
            }
            if let Ok(grid) = grid.build() {
                window.paint_path(grid, grid_color);
            }
            let baseline = y_bars(0.0);
            for (index, datum) in paint_points.iter().enumerate() {
                let center_x = bounds.origin.x
                    + width * ((index as f32 + 0.5) / paint_points.len().max(1) as f32);
                let end_y = y_bars(datum.barras);
                let start_y = baseline.min(end_y);
                let bar_height = (baseline - end_y).abs().max(px(1.0 * zoom));
                let bar_width =
                    (width / paint_points.len().max(1) as f32 * 0.48).max(px(2.0 * zoom));
                let color = if highlighted_for_paint.get(index).copied().unwrap_or(true) {
                    color_bars
                } else {
                    color_bars.opacity(0.24)
                };
                window.paint_quad(
                    fill(
                        Bounds::new(
                            point(center_x - bar_width / 2.0, start_y),
                            size(bar_width, bar_height),
                        ),
                        color,
                    )
                    .corner_radii(Corners::all(px(3.0 * zoom))),
                );
            }
            let mut path = PathBuilder::stroke(px(2.0 * zoom));
            for (index, item) in paint_points.iter().enumerate() {
                let center_x = bounds.origin.x
                    + width * ((index as f32 + 0.5) / paint_points.len().max(1) as f32);
                if index == 0 {
                    path.move_to(point(center_x, y_line(item.linea)));
                } else {
                    path.line_to(point(center_x, y_line(item.linea)));
                }
            }
            if let Ok(path) = path.build() {
                window.paint_path(path, color_line);
            }
            for (index, item) in paint_points.iter().enumerate() {
                let center_x = bounds.origin.x
                    + width * ((index as f32 + 0.5) / paint_points.len().max(1) as f32);
                let center = point(center_x, y_line(item.linea));
                let color = if highlighted_for_paint.get(index).copied().unwrap_or(true) {
                    color_line
                } else {
                    color_line.opacity(0.24)
                };
                window.paint_quad(
                    fill(
                        Bounds::new(
                            point(center.x - px(4.0 * zoom), center.y - px(4.0 * zoom)),
                            size(px(8.0 * zoom), px(8.0 * zoom)),
                        ),
                        color,
                    )
                    .corner_radii(Corners::all(px(4.0 * zoom))),
                );
            }
        },
    )
    .absolute()
    .top_0()
    .left_0()
    .w_full()
    .h_full();

    // Sin marco propio: el borde personalizable es el de la tarjeta general.
    let mut card = div()
        .flex()
        .flex_1()
        .min_h_0()
        .flex_col()
        .gap(px_lienzo(8.0, zoom))
        .p(px_lienzo(12.0, zoom));
    if formato.titulo {
        card = card.child(components::titulo_tarjeta_zoom(
            theme,
            format!("{measure_bars} · {measure_line}"),
            zoom,
        ));
    }
    let mut leyenda = div()
        .flex()
        .items_center()
        .gap(px_lienzo(16.0, zoom))
        .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, escala_texto));
    for (label, color, range) in [
        (
            format!("1. Barras · {measure_bars}"),
            color_bars,
            format!(
                "Eje izquierdo: {} a {}",
                format_value_with(
                    bars_min,
                    points.first().and_then(|p| p.formato_barras.as_ref())
                ),
                format_value_with(
                    bars_max,
                    points.first().and_then(|p| p.formato_barras.as_ref())
                )
            ),
        ),
        (
            format!("2. Línea · {measure_line}"),
            color_line,
            format!(
                "Eje derecho: {} a {}",
                format_value_with(
                    line_min,
                    points.first().and_then(|p| p.formato_linea.as_ref())
                ),
                format_value_with(
                    line_max,
                    points.first().and_then(|p| p.formato_linea.as_ref())
                )
            ),
        ),
    ] {
        leyenda = leyenda.child(
            div()
                .flex()
                .items_center()
                .gap(px_lienzo(5.0, zoom))
                .child(
                    div()
                        .w(px_lienzo(9.0, zoom))
                        .h(px_lienzo(9.0, zoom))
                        .rounded_full()
                        .bg(color),
                )
                .child(format!("{label} · {range}")),
        );
    }
    card = card.child(leyenda);
    if total_categories > points.len() {
        card = card.child(components::nota_zoom(
            theme,
            format!(
                "{} de {} categorías · orden del informe",
                points.len(),
                total_categories
            ),
            zoom,
        ));
    }
    let source_for_click = source_id.clone();
    let dimensions_for_click = dimension_ids.clone();
    let left_axis = div()
        .w(px_lienzo(54.0, zoom))
        .h(px(chart_height))
        .flex_shrink_0()
        .flex()
        .flex_col()
        .justify_between()
        .children(left_ticks);
    let right_axis = div()
        .w(px_lienzo(54.0, zoom))
        .h(px(chart_height))
        .flex_shrink_0()
        .flex()
        .flex_col()
        .justify_between()
        .items_end()
        .children(right_ticks);
    let hit_targets = div()
        .absolute()
        .top_0()
        .left_0()
        .w_full()
        .h_full()
        .flex()
        .children(points.iter().map(|item| {
            let category = item.clave_categoria.clone();
            let source = source_for_click.clone();
            let dimensions = dimensions_for_click.clone();
            let tooltip = SharedString::from(tooltip_combinado(item, measure_bars, measure_line));
            div()
                .id(ElementId::Name(SharedString::from(format!(
                    "combinado-hit-{}",
                    item.indice
                ))))
                .flex_1()
                .h_full()
                .cursor_pointer()
                .tooltip(move |window, cx| {
                    gpui_kit::component::tooltip::Tooltip::new(tooltip.clone()).build(window, cx)
                })
                .on_click(cx.listener(move |view, _event, _window, cx| {
                    view.filter_by_category_from(&source, &dimensions, &category, cx);
                }))
        }));
    let plot = div()
        .flex()
        .items_stretch()
        .gap(px_lienzo(6.0, zoom))
        .child(left_axis)
        .child(
            div()
                .relative()
                .flex_1()
                .h(px(chart_height))
                .child(chart)
                .child(hit_targets),
        )
        .child(right_axis);
    let categories = div()
        .flex()
        .gap(px_lienzo(6.0, zoom))
        .child(div().w(px_lienzo(54.0, zoom)).flex_shrink_0())
        .child(
            div()
                .flex_1()
                .flex()
                .children(points.iter().enumerate().map(|(index, item)| {
                    let category = item.clave_categoria.clone();
                    let source = source_for_click.clone();
                    let dimensions = dimensions_for_click.clone();
                    let tooltip =
                        SharedString::from(tooltip_combinado(item, measure_bars, measure_line));
                    let dimmed = !highlighted.get(index).copied().unwrap_or(true);
                    let mut label = div()
                        .id(ElementId::Name(SharedString::from(format!(
                            "combinado-{}",
                            item.indice
                        ))))
                        .flex_1()
                        .min_w_0()
                        .flex()
                        .justify_center()
                        .px(px_lienzo(3.0, zoom))
                        .opacity(if dimmed { 0.35 } else { 1.0 })
                        .hover(|style| style.bg(theme.list_hover.opacity(0.34)))
                        .cursor_pointer()
                        .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, escala_texto))
                        .overflow_hidden()
                        .truncate()
                        .child(item.etiqueta.clone())
                        .tooltip(move |window, cx| {
                            gpui_kit::component::tooltip::Tooltip::new(tooltip.clone())
                                .build(window, cx)
                        })
                        .on_click(cx.listener(move |view, _event, _window, cx| {
                            view.filter_by_category_from(&source, &dimensions, &category, cx);
                        }));
                    if !highlighted.get(index).copied().unwrap_or(true) {
                        label = label.opacity(0.35);
                    }
                    label
                })),
        )
        .child(div().w(px_lienzo(54.0, zoom)).flex_shrink_0());
    card = card.child(plot).child(categories);
    card.into_any_element()
}

fn color_barras_combinadas(
    formato: datan_report::saved::SavedFormato,
    oscuro: bool,
) -> Hsla {
    if formato.color_serie_rgb == 0 {
        tokens::serie(formato.color_serie as usize, oscuro)
    } else {
        rgb(formato.color_serie_rgb & 0x00ff_ffff).into()
    }
}

fn visual_error_sin_relacion(error: &str) -> bool {
    let error = error.to_lowercase();
    error.contains("no hay relationship") || error.contains("no tiene camino de join")
}

fn visual_error_por_falta_de_medidas(error: &str) -> bool {
    error == datan_report::ReportError::NoMeasures.to_string()
}

/// Una tarjeta con un aviso, para el visual que no puede dibujar todavia.
fn card_vacio(
    theme: &Theme,
    tipo: &str,
    texto: impl Into<SharedString>,
    _formato: datan_report::saved::SavedFormato,
    zoom: f32,
    ancho: f32,
    alto: f32,
) -> AnyElement {
    let texto = texto.into();
    let titulo = if texto.starts_with("Añade")
        || texto.starts_with("Marca")
        || texto.starts_with("Elige")
        || texto.starts_with("Selecciona")
        || texto.contains("necesita")
    {
        "Faltan campos"
    } else {
        "Sin datos"
    };
    // El marcador escala con la tarjeta que lo contiene: un visual chico no puede cargar el
    // icono y las letras de tamano completo sin recortarse. 420x300 es donde entra completo;
    // abajo de eso todo se achica, y en tarjetas muy bajas caen primero el texto y el icono.
    let escala = ((ancho / 420.0).min(alto / 300.0)).clamp(0.55, 1.0);
    let con_icono = alto >= 120.0 && ancho >= 230.0;
    let con_texto = alto >= 130.0;
    let contenido = div()
        .flex()
        .flex_1()
        .min_w_0()
        .rounded_xl()
        .border_1()
        .border_dashed()
        .border_color(theme.border)
        .items_center()
        .justify_center()
        .child(
            div()
                .flex()
                .flex_col()
                .items_center()
                .w_full()
                .max_w(px_lienzo(400.0 * escala, zoom))
                .gap(px_lienzo(12.0 * escala, zoom))
                .children(con_icono.then(|| {
                    div()
                        .w(px_lienzo(72.0 * escala, zoom))
                        .h(px_lienzo(56.0 * escala, zoom))
                        .rounded_xl()
                        .border_1()
                        .border_color(theme.border)
                        .bg(theme.background)
                        .flex()
                        .items_center()
                        .justify_center()
                        .child(components::icono(
                            icono_visual(tipo),
                            28.0 * zoom * escala,
                            theme.muted_foreground,
                        ))
                        .into_any_element()
                }))
                .child(
                    div()
                        .font_semibold()
                        .text_size(px_lienzo(tokens::LETRA_VALOR * escala.max(0.75), zoom))
                        .child(titulo),
                )
                .children(con_texto.then(|| {
                    div()
                        .w_full()
                        .max_w(px_lienzo(360.0 * escala, zoom))
                        .text_size(px_lienzo(tokens::LETRA_CUERPO * escala.max(0.8), zoom))
                        .text_color(theme.foreground)
                        .text_align(TextAlign::Center)
                        .child(texto)
                        .into_any_element()
                })),
        );
    contenido
        .mx(px_lienzo(12.0 * escala, zoom))
        .my(px_lienzo(12.0 * escala, zoom))
        .p(px_lienzo(12.0 * escala, zoom))
        .into_any_element()
}

/// Una dispersion: cada categoria es un punto, con una medida en cada eje.
///
/// Los dos ejes se escalan al minimo y al maximo de los datos. Un eje que arranca en cero
/// junta todos los puntos contra la izquierda el dia que las dos medidas tienen un piso alto,
/// que es el caso de casi cualquier tabla de hechos.
fn dispersion(
    theme: &Theme,
    nube: &[PuntoDispersion],
    axes: ChartAxes,
    color_serie_rgb: u32,
    formatos_eje: [Option<&formato::Formato>; 2],
    dimension_ids: &[ObjectId],
    source_id: &str,
    highlight: Option<&Matrix>,
    referencias: Vec<f64>,
    zoom: f32,
    escala_texto: f32,
    label_color: Hsla,
    cx: &mut Context<Datan>,
) -> AnyElement {
    let extremos = |valores: &mut dyn Iterator<Item = f64>| {
        valores.fold(None::<(f64, f64)>, |acc, valor| {
            Some(match acc {
                None => (valor, valor),
                Some((lo, hi)) => (lo.min(valor), hi.max(valor)),
            })
        })
    };
    let (min_x, max_x) = extremos(&mut nube.iter().map(|punto| punto.x)).unwrap_or((0.0, 1.0));
    let (min_y, max_y) = extremos(&mut nube.iter().map(|punto| punto.y)).unwrap_or((0.0, 1.0));
    let span_x = (max_x - min_x).max(f64::MIN_POSITIVE);
    let span_y = (max_y - min_y).max(f64::MIN_POSITIVE);
    let datos: Vec<(f32, f32)> = nube
        .iter()
        .map(|punto| {
            (
                ((punto.x - min_x) / span_x) as f32,
                1.0 - ((punto.y - min_y) / span_y) as f32,
            )
        })
        .collect();
    let color = if color_serie_rgb == 0 {
        tokens::serie_unica(theme.is_dark())
    } else {
        rgb(color_serie_rgb & 0x00ff_ffff).into()
    };
    let point_colors: Vec<_> = nube
        .iter()
        .map(|point| {
            point
                .color_condicional
                .map_or(color, |conditional| rgb(conditional & 0x00ff_ffff).into())
        })
        .collect();
    let rejilla = theme.chart_grid;
    let color_ejes = theme.border;
    let datos_dibujo = datos.clone();
    let point_colors_for_paint = point_colors.clone();
    let highlighted: Vec<bool> = nube
        .iter()
        .map(|point| {
            !highlight
                .is_some_and(|matrix| !matrix_contiene_categoria(matrix, &point.clave_categoria))
        })
        .collect();
    let highlighted_for_paint = highlighted.clone();
    let referencias_y = referencias
        .iter()
        .map(|value| (1.0 - ((*value - min_y) / span_y) as f32).clamp(0.0, 1.0))
        .collect::<Vec<_>>();
    let color_referencias = (0..referencias_y.len())
        .map(|index| tokens::serie((index + 1) % 6, theme.is_dark()))
        .collect::<Vec<_>>();

    let dibujo = canvas(
        move |_bounds, _window, _cx| (),
        move |bounds, (), window, _cx| {
            // Un margen de 6 px: un punto en el borde del canvas se ve cortado a la mitad.
            let margen = px_lienzo((6.), zoom);
            let ancho = (bounds.size.width - margen * 2.0).max(px_lienzo((1.), zoom));
            let alto = (bounds.size.height - margen * 2.0).max(px_lienzo((1.), zoom));
            let x = |t: f32| bounds.origin.x + margen + ancho * t;
            let y = |t: f32| bounds.origin.y + margen + alto * t;

            for (index, ty) in referencias_y.iter().copied().enumerate() {
                let mut trazo = PathBuilder::stroke(px_lienzo(1.5, zoom));
                trazo.move_to(point(x(0.0), y(ty)));
                trazo.line_to(point(x(1.0), y(ty)));
                if let Ok(path) = trazo.build() {
                    window.paint_path(
                        path,
                        color_referencias.get(index).copied().unwrap_or(rejilla),
                    );
                }
            }

            if axes.grid {
                let mut trazo = PathBuilder::stroke(px_lienzo((1.), zoom));
                for i in 0..=4 {
                    let t = i as f32 / 4.0;
                    trazo.move_to(point(x(0.0), y(t)));
                    trazo.line_to(point(x(1.0), y(t)));
                    trazo.move_to(point(x(t), y(0.0)));
                    trazo.line_to(point(x(t), y(1.0)));
                }
                if let Ok(path) = trazo.build() {
                    window.paint_path(path, rejilla);
                }
            }
            if axes.x || axes.y {
                let mut trazo = PathBuilder::stroke(px_lienzo(1.0, zoom));
                if axes.x {
                    trazo.move_to(point(x(0.0), y(1.0)));
                    trazo.line_to(point(x(1.0), y(1.0)));
                }
                if axes.y {
                    trazo.move_to(point(x(0.0), y(0.0)));
                    trazo.line_to(point(x(0.0), y(1.0)));
                }
                if let Ok(path) = trazo.build() {
                    window.paint_path(path, color_ejes);
                }
            }

            for (index, (tx, ty)) in datos_dibujo.iter().enumerate() {
                let color = if highlighted_for_paint.get(index).copied().unwrap_or(true) {
                    point_colors_for_paint.get(index).copied().unwrap_or(color)
                } else {
                    point_colors_for_paint
                        .get(index)
                        .copied()
                        .unwrap_or(color)
                        .opacity(0.24)
                };
                window.paint_quad(
                    fill(
                        Bounds::new(
                            point(
                                x(*tx) - px_lienzo((4.0), zoom),
                                y(*ty) - px_lienzo((4.0), zoom),
                            ),
                            size(px_lienzo((8.0), zoom), px_lienzo((8.0), zoom)),
                        ),
                        color,
                    )
                    .corner_radii(Corners::all(px_lienzo((4.0), zoom))),
                );
            }
        },
    )
    .h(px_lienzo((tokens::ALTO_DISPERSION), zoom))
    .w_full();

    let rotulo = |texto: String| {
        div()
            .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, escala_texto))
            .text_color(label_color)
            .child(texto)
    };
    let margen_eje = 64.0;
    let source = source_id.to_string();
    let dimensions = dimension_ids.to_vec();
    let hit_targets = nube.iter().zip(&datos).map(|(point, (x, y))| {
        let category = point.clave_categoria.clone();
        let tooltip = SharedString::from(tooltip_de_dispersion(point, formatos_eje));
        let source = source.clone();
        let dimensions = dimensions.clone();
        div()
            .id(ElementId::Name(SharedString::from(format!(
                "dispersion-hit-{}",
                point.indice
            ))))
            .absolute()
            .left(relative(*x))
            .ml(px_lienzo(desplazamiento_hit_dispersion(*x), zoom))
            .top(relative(*y))
            .mt(px_lienzo(desplazamiento_hit_dispersion(*y), zoom))
            .w(px_lienzo(16.0, zoom))
            .h(px_lienzo(16.0, zoom))
            .rounded_full()
            .opacity(0.0)
            .cursor_pointer()
            .tooltip(move |window, cx| {
                gpui_kit::component::tooltip::Tooltip::new(tooltip.clone()).build(window, cx)
            })
            .on_click(cx.listener(move |view, _event, _window, cx| {
                view.filter_by_category_from(&source, &dimensions, &category, cx);
            }))
    });
    div()
        .flex()
        .flex_col()
        .gap(px_lienzo(4.0, zoom))
        .child(
            div()
                .flex()
                .gap(px_lienzo(8.0, zoom))
                .child(
                    div()
                        .w(px_lienzo((margen_eje - 8.0), zoom))
                        .h(px_lienzo((tokens::ALTO_DISPERSION), zoom))
                        .flex_shrink_0()
                        .flex()
                        .flex_col()
                        .justify_between()
                        .when(axes.y, |labels| {
                            labels
                                .child(rotulo(format_value_with(max_y, formatos_eje[1])))
                                .child(rotulo(format_value_with(min_y, formatos_eje[1])))
                        }),
                )
                .child(
                    div()
                        .relative()
                        .flex_1()
                        .child(dibujo)
                        .children(hit_targets),
                ),
        )
        .child(
            div()
                .flex()
                .justify_between()
                .pl(px_lienzo((margen_eje), zoom))
                .when(axes.x, |labels| {
                    labels
                        .child(rotulo(format_value_with(min_x, formatos_eje[0])))
                        .child(rotulo(format_value_with(max_x, formatos_eje[0])))
                }),
        )
        .into_any_element()
}

#[derive(Clone, Copy)]
struct ChartAxes {
    x: bool,
    y: bool,
    grid: bool,
}

impl From<datan_report::saved::SavedFormato> for ChartAxes {
    fn from(format: datan_report::saved::SavedFormato) -> Self {
        Self {
            x: format.eje_x,
            y: format.eje,
            grid: format.muestra_rejilla_graficos(),
        }
    }
}

/// El dibujo de un grafico del sistema, segun el tipo elegido.
fn dibujo(
    tipo: &str,
    puntos: &[Punto],
    velas: &[visuales::Vela],
    nodos_flujo: &[visuales::NodoFlujo],
    enlaces_flujo: &[gpui_kit::component::plot::shape::SankeyLink],
    medida: &str,
    eje: bool,
    color_serie: u8,
    oscuro: bool,
    referencia: Option<f64>,
    linea_tendencia: bool,
    pronostico: bool,
    zoom: f32,
) -> AnyElement {
    dibujo_con_click(
        tipo,
        puntos,
        velas,
        nodos_flujo,
        enlaces_flujo,
        medida,
        ChartAxes {
            x: true,
            y: eje,
            grid: eje,
        },
        color_serie,
        0,
        oscuro,
        referencia.into_iter().collect(),
        linea_tendencia,
        pronostico,
        64,
        zoom,
        1.0,
        None,
        tipo,
        None,
    )
}

#[derive(Clone)]
struct PuntoSerieVisual {
    etiqueta: String,
    valores: Vec<Option<f64>>,
}

const PALETA_SERIES: [u32; 5] = [0x2563eb, 0x0d9488, 0xea580c, 0x7c3aed, 0xdc2626];

fn color_serie_leyenda(
    label: &str,
    index: usize,
    overrides: &std::collections::BTreeMap<String, u32>,
) -> u32 {
    overrides
        .get(label)
        .copied()
        .unwrap_or(PALETA_SERIES[index % PALETA_SERIES.len()])
}

fn leyenda_dispersion(
    _theme: &Theme,
    series: &visuales::DatosSeries,
    overrides: &std::collections::BTreeMap<String, u32>,
    visual_id: &str,
    zoom: f32,
    escala_texto: f32,
    label_color: Hsla,
) -> AnyElement {
    let mut items = div()
        .flex()
        .flex_wrap()
        .items_center()
        .gap_x(px_lienzo(12.0, zoom));
    for (index, serie) in series.series.iter().enumerate() {
        let color = color_serie_leyenda(&serie.etiqueta, index, overrides);
        items = items.child(
            div()
                .id(ElementId::Name(SharedString::from(format!(
                    "dispersion-legend-{}-{index}",
                    visual_id
                ))))
                .flex()
                .items_center()
                .gap(px_lienzo(5.0, zoom))
                .child(
                    div()
                        .w(px_lienzo(8.0, zoom))
                        .h(px_lienzo(8.0, zoom))
                        .rounded_full()
                        .bg(rgb(color)),
                )
                .child(
                    div()
                        .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, escala_texto))
                        .text_color(label_color)
                        .child(serie.etiqueta.clone()),
                ),
        );
    }
    items.into_any_element()
}

fn puntos_con_colores_categoria(
    points: &[Punto],
    overrides: &std::collections::BTreeMap<String, u32>,
) -> Vec<Punto> {
    points
        .iter()
        .map(|point| {
            let mut point = point.clone();
            if point.color_condicional.is_none() {
                let category = point.clave_categoria.join(" · ");
                point.color_condicional = overrides.get(&category).copied();
            }
            point
        })
        .collect()
}

fn color_serie_editor(
    label: &str,
    series_index: Option<usize>,
    overrides: &std::collections::BTreeMap<String, u32>,
    fallback: u32,
) -> u32 {
    overrides
        .get(label)
        .copied()
        .or_else(|| series_index.map(|index| color_serie_leyenda(label, index, overrides)))
        .unwrap_or(fallback)
}

fn dibujo_series_con_click(
    tipo: &str,
    series: &visuales::DatosSeries,
    series_colors: &std::collections::BTreeMap<String, u32>,
    medida: &str,
    referencias: Vec<f64>,
    axes: ChartAxes,
    oscuro: bool,
    zoom: f32,
    escala_texto: f32,
    label_color: Option<Hsla>,
    on_mark_click: Option<std::rc::Rc<dyn Fn(usize, &mut Window, &mut App) + 'static>>,
) -> AnyElement {
    let data = series
        .categorias
        .iter()
        .enumerate()
        .map(|(index, category)| PuntoSerieVisual {
            etiqueta: category.join(" · "),
            valores: series
                .series
                .iter()
                .map(|serie| serie.valores.get(index).copied().flatten())
                .collect(),
        })
        .collect::<Vec<_>>();
    let series_names = series
        .series
        .iter()
        .map(|serie| serie.etiqueta.clone())
        .collect::<Vec<_>>();
    let id = ElementId::Name(SharedString::from(format!("grafico-series-{tipo}")));
    let mut range = series
        .series
        .iter()
        .flat_map(|serie| serie.valores.iter().flatten().copied())
        .chain(referencias.iter().copied())
        .fold(None, |range: Option<(f64, f64)>, value| {
            Some(range.map_or((value, value), |(minimum, maximum)| {
                (minimum.min(value), maximum.max(value))
            }))
        })
        .unwrap_or((0.0, 1.0));
    if (range.1 - range.0).abs() < f64::EPSILON {
        range = (range.0 - 1.0, range.1 + 1.0);
    }
    if tipo == "Area" {
        let mut chart = AreaChart::new(data)
            .id(id)
            .x(|point: &PuntoSerieVisual| point.etiqueta.clone())
            .axis_font_size(10.0 * zoom * escala_texto)
            .tooltip_title(|point: &PuntoSerieVisual| SharedString::from(point.etiqueta.clone()))
            .tooltip_value(move |_, series_index, value| {
                SharedString::from(format!(
                    "{}: {}",
                    series_names.get(series_index).map_or("", String::as_str),
                    format_value(value)
                ))
            });
        if let Some(color) = label_color {
            chart = chart.label_color(color);
        }
        for (index, serie) in series.series.iter().enumerate() {
            let color = rgb(color_serie_leyenda(&serie.etiqueta, index, series_colors));
            chart = chart
                .y_optional(move |point: &PuntoSerieVisual| {
                    point.valores.get(index).copied().flatten()
                })
                .stroke(color)
                .fill(color.opacity(0.18))
                .name(serie.etiqueta.clone());
        }
        chart = chart
            .linear()
            .x_axis(axes.x)
            .y_domain(range.0, range.1)
            .y_axis(axes.y)
            .y_tick_count(4)
            .grid(axes.grid)
            .grid_dashed(false);
        for reference in &referencias {
            chart = chart.reference_line(*reference);
        }
        match on_mark_click {
            Some(handler) => chart
                .on_mark_click(move |index, window, cx| handler(index, window, cx))
                .into_any_element(),
            None => chart.into_any_element(),
        }
    } else {
        let mut chart = LineChart::new(data)
            .id(id)
            .x(|point: &PuntoSerieVisual| point.etiqueta.clone())
            .axis_font_size(10.0 * zoom * escala_texto)
            .tooltip_title(|point: &PuntoSerieVisual| SharedString::from(point.etiqueta.clone()))
            .tooltip_value(|_, value| SharedString::from(format_value(value)));
        if let Some(color) = label_color {
            chart = chart.label_color(color);
        }
        for (index, serie) in series.series.iter().enumerate() {
            let color = rgb(color_serie_leyenda(&serie.etiqueta, index, series_colors));
            chart = chart
                .y_optional(move |point: &PuntoSerieVisual| {
                    point.valores.get(index).copied().flatten()
                })
                .stroke(color)
                .name(serie.etiqueta.clone());
        }
        chart = chart
            .linear()
            .x_axis(axes.x)
            .y_domain(range.0, range.1)
            .y_axis(axes.y)
            .y_tick_count(4)
            .grid(axes.grid)
            .grid_dashed(false);
        for reference in &referencias {
            chart = chart.reference_line(*reference);
        }
        match on_mark_click {
            Some(handler) => chart
                .on_mark_click(move |index, window, cx| handler(index, window, cx))
                .into_any_element(),
            None => chart.into_any_element(),
        }
    }
}

fn dibujo_con_click(
    tipo: &str,
    puntos: &[Punto],
    velas: &[visuales::Vela],
    nodos_flujo: &[visuales::NodoFlujo],
    enlaces_flujo: &[gpui_kit::component::plot::shape::SankeyLink],
    medida: &str,
    axes: ChartAxes,
    color_serie: u8,
    color_serie_rgb: u32,
    oscuro: bool,
    referencias: Vec<f64>,
    linea_tendencia: bool,
    pronostico: bool,
    radio_interior_anillo: u8,
    zoom: f32,
    escala_texto: f32,
    label_color: Option<Hsla>,
    chart_key: &str,
    on_mark_click: Option<std::rc::Rc<dyn Fn(usize, &mut Window, &mut App) + 'static>>,
) -> AnyElement {
    let datos = puntos.to_vec();
    let formato_valor = puntos.first().and_then(|point| point.formato.clone());
    let nombre = SharedString::from(medida.to_string());
    // Una sola medida: un solo color. El color por categoria es para el anillo, donde cada
    // porcion ES una categoria.
    let color = if color_serie_rgb == 0 {
        tokens::serie(color_serie as usize, oscuro)
    } else {
        rgb(color_serie_rgb & 0x00ff_ffff).into()
    };
    let id = ElementId::Name(SharedString::from(format!("grafico-{tipo}-{chart_key}")));

    match tipo {
        "Lineas" => {
            let analitica = linea_tendencia || pronostico || !referencias.is_empty();
            let domain = analitica.then(|| rango_analitico(puntos, &referencias, linea_tendencia, pronostico));
            let conditional_color = puntos.iter().any(|point| point.color_condicional.is_some());
            let mut chart = LineChart::new(datos)
                .x(|punto: &Punto| punto.etiqueta.clone())
                .y(|punto: &Punto| punto.valor)
                .axis_font_size(10.0 * zoom * escala_texto)
                .stroke(if conditional_color {
                    color.opacity(0.0)
                } else {
                    color
                })
                .name(nombre)
                .tooltip_title(|punto: &Punto| SharedString::from(punto.etiqueta.clone()))
                .tooltip_value(|punto: &Punto, valor| tooltip_de_punto(punto, valor));
            if let Some(color) = label_color {
                chart = chart.label_color(color);
            }
            let chart = if let Some((min, max)) = domain {
                let chart = chart.y_domain(min, max);
                if pronostico {
                    chart.point_count(puntos.len() + 3)
                } else {
                    chart
                }
            } else {
                chart
            };
            let chart = chart
                .id(id)
                .linear()
                .x_axis(axes.x)
                .y_axis(axes.y)
                .y_tick_count(4)
                .y_tick_format({
                    let formato = formato_valor.clone();
                    move |value| format_value_with(value, formato.as_ref())
                })
                .grid(axes.grid)
                .grid_dashed(false);
            let chart = if let Some(handler) = on_mark_click.clone() {
                chart.on_mark_click(move |index, window, cx| handler(index, window, cx))
            } else {
                chart
            };
            let chart = overlay_color_condicional_lineal(
                chart.into_any_element(),
                puntos,
                color,
                domain,
                axes.y,
                false,
                if pronostico {
                    puntos.len() + 3
                } else {
                    puntos.len()
                },
                zoom,
            );
            if analitica {
                overlay_analitica(
                    oscuro,
                    chart,
                    puntos,
                    referencias.clone(),
                    linea_tendencia,
                    pronostico,
                    axes.y,
                    zoom,
                )
            } else {
                chart
            }
        }
        "Area" => {
            let analitica = linea_tendencia || pronostico || !referencias.is_empty();
            let domain = analitica.then(|| rango_analitico(puntos, &referencias, linea_tendencia, pronostico));
            let conditional_color = puntos.iter().any(|point| point.color_condicional.is_some());
            let mut chart = AreaChart::new(datos)
                .x(|punto: &Punto| punto.etiqueta.clone())
                .y(|punto: &Punto| punto.valor)
                .axis_font_size(10.0 * zoom * escala_texto)
                .stroke(if conditional_color {
                    color.opacity(0.0)
                } else {
                    color
                })
                .fill(if conditional_color {
                    color.opacity(0.0)
                } else {
                    color.opacity(0.18)
                })
                .name(nombre)
                .tooltip_title(|punto: &Punto| SharedString::from(punto.etiqueta.clone()))
                .tooltip_value(|punto: &Punto, _, valor| tooltip_de_punto(punto, valor));
            if let Some(color) = label_color {
                chart = chart.label_color(color);
            }
            let chart = if let Some((min, max)) = domain {
                let chart = chart.y_domain(min, max);
                if pronostico {
                    chart.point_count(puntos.len() + 3)
                } else {
                    chart
                }
            } else {
                chart
            };
            let chart = chart
                .id(id)
                .linear()
                .x_axis(axes.x)
                .y_axis(axes.y)
                .y_tick_count(4)
                .y_tick_format({
                    let formato = formato_valor.clone();
                    move |value| format_value_with(value, formato.as_ref())
                })
                .grid(axes.grid)
                .grid_dashed(false);
            let chart = if let Some(handler) = on_mark_click.clone() {
                chart.on_mark_click(move |index, window, cx| handler(index, window, cx))
            } else {
                chart
            };
            let chart = overlay_color_condicional_lineal(
                chart.into_any_element(),
                puntos,
                color,
                domain,
                axes.y,
                true,
                if pronostico {
                    puntos.len() + 3
                } else {
                    puntos.len()
                },
                zoom,
            );
            if analitica {
                overlay_analitica(
                    oscuro,
                    chart,
                    puntos,
                    referencias.clone(),
                    linea_tendencia,
                    pronostico,
                    axes.y,
                    zoom,
                )
            } else {
                chart
            }
        }
        // `inner_radius` esta en pixeles, como el radio exterior, que sale del alto de la
        // caja.
        "Anillo" => PieChart::new(datos)
            .id(id)
            .value(|punto: &Punto| punto.valor as f32)
            .color(move |punto: &Punto| {
                punto.color_condicional.map_or_else(
                    || tokens::serie(punto.indice, oscuro),
                    |color| rgb(color & 0x00ff_ffff).into(),
                )
            })
            .inner_radius(f32::from(radio_interior_anillo) * zoom)
            .name(nombre)
            .tooltip_name(|punto: &Punto| SharedString::from(punto.etiqueta.clone()))
            .tooltip_value(|punto: &Punto, value, _| tooltip_de_punto(punto, value as f64))
            .into_any_element(),
        "Radar" => {
            let conditional_color = puntos.iter().any(|point| point.color_condicional.is_some());
            let mut chart = RadarChart::new(datos)
                .id(id)
                .label_font_size(10.0 * zoom * escala_texto)
                .label(|punto: &Punto| SharedString::from(punto.etiqueta.clone()))
                .value(|punto: &Punto| punto.valor)
                .stroke(if conditional_color {
                    color.opacity(0.0)
                } else {
                    color
                })
                .fill(color.opacity(0.18))
                .name(nombre)
                .tooltip_value(|punto: &Punto, _, valor| tooltip_de_punto(punto, valor));
            if let Some(color) = label_color {
                chart = chart.label_color(color);
            }
            let chart = match on_mark_click {
                Some(handler) => chart
                    .on_mark_click(move |index, window, cx| handler(index, window, cx))
                    .into_any_element(),
                None => chart.into_any_element(),
            };
            if conditional_color {
                overlay_color_condicional_radar(chart, puntos, color, zoom)
            } else {
                chart
            }
        }
        "Candlestick" => {
            let mut chart = CandlestickChart::new(velas.to_vec())
                .id(id)
                .x(|vela: &visuales::Vela| vela.etiqueta.clone())
                .axis_font_size(10.0 * zoom * escala_texto)
                .open(|vela: &visuales::Vela| vela.apertura)
                .high(|vela: &visuales::Vela| vela.maximo)
                .low(|vela: &visuales::Vela| vela.minimo)
                .close(|vela: &visuales::Vela| vela.cierre)
                .tooltip_value(|vela: &visuales::Vela, _, _| {
                    SharedString::from(format!(
                        "Apertura: {} · Máximo: {} · Mínimo: {} · Cierre: {}",
                        format_value(vela.apertura),
                        format_value(vela.maximo),
                        format_value(vela.minimo),
                        format_value(vela.cierre),
                    ))
                });
            if let Some(color) = label_color {
                chart = chart.label_color(color);
            }
            match on_mark_click {
                Some(handler) => chart
                    .on_mark_click(move |index, window, cx| handler(index, window, cx))
                    .into_any_element(),
                None => chart.into_any_element(),
            }
        }
        "Sankey" => {
            let chart = SankeyChart::new(nodos_flujo.to_vec(), enlaces_flujo.to_vec())
                .id(id)
                .labels(move |nodo: &visuales::NodoFlujo, _| {
                    let mut label =
                        gpui_kit::component::chart::SankeyLabel::new(nodo.etiqueta.clone())
                            .font_size(12.0 * zoom * escala_texto);
                    if let Some(color) = label_color {
                        label = label.color(color);
                    }
                    vec![label]
                })
                .node_color(move |nodo: &visuales::NodoFlujo| tokens::serie(nodo.fase, oscuro))
                .tooltip_name(|nodo: &visuales::NodoFlujo| {
                    SharedString::from(nodo.etiqueta.clone())
                })
                .tooltip_value(|_, valor| SharedString::from(format_value(valor)));
            match on_mark_click {
                Some(handler) => chart
                    .on_node_click(move |node, window, cx| handler(node, window, cx))
                    .into_any_element(),
                None => chart.into_any_element(),
            }
        }
        "Barras" | "Columnas" | "Todo" => {
            let mut chart = BarChart::new(datos)
                .id(id)
                .axis_font_size(10.0 * zoom * escala_texto)
                .alignment(alineacion_barras(tipo))
                .band(|punto: &Punto| SharedString::from(punto.etiqueta.clone()))
                .value(|punto: &Punto| punto.valor)
                .fill(move |point: &Punto, _, _, _| {
                    point
                        .color_condicional
                        .map_or(color, |color| rgb(color & 0x00ff_ffff).into())
                })
                .name(nombre)
                .tooltip_title(|punto: &Punto| SharedString::from(punto.etiqueta.clone()))
                .tooltip_value(|punto: &Punto, valor| tooltip_de_punto(punto, valor))
                .label_axis(if tipo == "Barras" { axes.y } else { axes.x })
                .value_axis(if tipo == "Barras" { axes.x } else { axes.y })
                .value_tick_count(4)
                .value_tick_format({
                    let formato = formato_valor.clone();
                    move |value| format_value_with(value, formato.as_ref())
                })
                .grid(axes.grid)
                .grid_dashed(false)
                .corner_radii(Corners::all(px_lienzo(4.0, zoom)));
            for reference in &referencias {
                chart = chart.reference_line(*reference);
            }
            if let Some(color) = label_color {
                chart = chart.axis_label_color(color);
            }
            match on_mark_click {
                Some(handler) => chart
                    .on_mark_click(move |index, window, cx| handler(index, window, cx))
                    .into_any_element(),
                None => chart.into_any_element(),
            }
        }
        _ => div()
            .flex()
            .flex_1()
            .items_center()
            .justify_center()
            .text_size(px_lienzo(13.0, zoom))
            .child(format!("Visual no compatible: {tipo}"))
            .into_any_element(),
    }
}

/// La leyenda del anillo: el color, la categoria y su valor, y cada fila filtra.
///
/// Dos columnas y no `flex_wrap`: el envoltorio reparte las lineas por el alto que sobre, y
/// ocho filas que se separan solas se leen como ocho bloques sueltos.
fn leyenda(
    theme: &Theme,
    puntos: &[Punto],
    dimension_ids: &[ObjectId],
    source_id: &str,
    highlight: Option<&Matrix>,
    zoom: f32,
    escala_texto: f32,
    label_color: Hsla,
    cx: &mut Context<Datan>,
) -> AnyElement {
    let mitad = puntos.len().div_ceil(2).max(1);
    let (izquierda, derecha) = puntos.split_at(mitad.min(puntos.len()));
    div()
        .w(px_lienzo((360.0), zoom))
        .flex_shrink_0()
        .flex()
        .flex_col()
        .gap(px_lienzo(4.0, zoom))
        .child(components::nota_zoom(
            theme,
            "Categorías · clic para filtrar",
            zoom,
        ))
        .child(
            div()
                .flex()
                .gap_x(px_lienzo(8.0, zoom))
                .child(leyenda_columna(
                    theme,
                    izquierda,
                    dimension_ids,
                    source_id,
                    highlight,
                    zoom,
                    escala_texto,
                    label_color,
                    cx,
                ))
                .child(leyenda_columna(
                    theme,
                    derecha,
                    dimension_ids,
                    source_id,
                    highlight,
                    zoom,
                    escala_texto,
                    label_color,
                    cx,
                )),
        )
        .into_any_element()
}

fn handlers_categoria(
    puntos: &[Punto],
    dimension_ids: &[ObjectId],
    source_id: &str,
    cx: &mut Context<Datan>,
) -> Vec<visuales::CategoryClick> {
    puntos
        .iter()
        .map(|punto| {
            let source = source_id.to_string();
            let dimensions = dimension_ids.to_vec();
            let values = punto.clave_categoria.clone();
            Box::new(cx.listener(move |view, _event, _window, cx| {
                view.filter_by_category_from(&source, &dimensions, &values, cx);
            })) as visuales::CategoryClick
        })
        .collect()
}

/// Una columna de la leyenda: una fila por categoria.
fn leyenda_columna(
    theme: &Theme,
    puntos: &[Punto],
    dimension_ids: &[ObjectId],
    source_id: &str,
    highlight: Option<&Matrix>,
    zoom: f32,
    escala_texto: f32,
    label_color: Hsla,
    cx: &mut Context<Datan>,
) -> AnyElement {
    let mut columna = div().flex_1().flex_col().gap(px_lienzo(4.0, zoom));
    for punto in puntos {
        let dimension_ids = dimension_ids.to_vec();
        let values = punto.clave_categoria.clone();
        let source_id = source_id.to_string();
        let atenuado = highlight
            .is_some_and(|matrix| !matrix_contiene_categoria(matrix, &punto.clave_categoria));
        columna = columna.child(
            div()
                .id(ElementId::Name(SharedString::from(format!(
                    "leyenda-{}",
                    punto.indice
                ))))
                .flex()
                .items_center()
                .gap(px_lienzo(8.0, zoom))
                .px(px_lienzo(8.0, zoom))
                .py(px_lienzo(4.0, zoom))
                .rounded_xl()
                .cursor_pointer()
                .hover(|style| style.bg(theme.list_hover))
                .opacity(if atenuado { 0.3 } else { 1.0 })
                .child(
                    div()
                        .w(px_lienzo((8.0), zoom))
                        .h(px_lienzo((8.0), zoom))
                        .flex_shrink_0()
                        .rounded_full()
                        .bg(punto.color_condicional.map_or_else(
                            || tokens::serie(punto.indice, theme.is_dark()),
                            |color| rgb(color & 0x00ff_ffff).into(),
                        )),
                )
                .child(
                    div()
                        .flex_1()
                        .overflow_hidden()
                        .truncate()
                        .text_size(px_texto_lienzo(tokens::LETRA_ETIQUETA, zoom, escala_texto))
                        .child(punto.etiqueta.clone()),
                )
                .child(
                    div()
                        .flex_shrink_0()
                        .text_size(px_texto_lienzo(tokens::LETRA_ETIQUETA, zoom, escala_texto))
                        .text_color(label_color)
                        .child(format_value_with(punto.valor, punto.formato.as_ref())),
                )
                .tab_index(0)
                .on_click(cx.listener(move |view, _event, _window, cx| {
                    view.filter_by_category_from(&source_id, &dimension_ids, &values, cx);
                })),
        );
    }
    columna.into_any_element()
}

fn leyenda_categorias_interactiva(
    theme: &Theme,
    categorias: &[Punto],
    incompletas: bool,
    dimension_ids: &[ObjectId],
    source_id: &str,
    highlight: Option<&Matrix>,
    zoom: f32,
    escala_texto: f32,
    label_color: Hsla,
    cx: &mut Context<Datan>,
) -> AnyElement {
    let source = source_id.to_string();
    let dimensions = dimension_ids.to_vec();
    let elementos = categorias.iter().map(|punto| {
        let source = source.clone();
        let dimensions = dimensions.clone();
        let values = punto.clave_categoria.clone();
        let active = !highlight
            .is_some_and(|matrix| !matrix_contiene_categoria(matrix, &punto.clave_categoria));
        div()
            .id(ElementId::Name(SharedString::from(format!(
                "category-filter-{}-{}",
                source_id, punto.indice
            ))))
            .flex()
            .items_center()
            .gap(px_lienzo(6.0, zoom))
            .max_w(px_lienzo(180.0, zoom))
            .px(px_lienzo(8.0, zoom))
            .py(px_lienzo(4.0, zoom))
            .rounded_lg()
            .cursor_pointer()
            .hover(|style| style.bg(theme.list_hover))
            .opacity(if active { 1.0 } else { 0.3 })
            .child(
                div()
                    .size(px_lienzo(7.0, zoom))
                    .flex_shrink_0()
                    .rounded_full()
                    .bg(tokens::serie(punto.indice, theme.is_dark())),
            )
            .child(
                div()
                    .overflow_hidden()
                    .truncate()
                    .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, escala_texto))
                    .child(punto.etiqueta.clone()),
            )
            .tab_index(0)
            .on_click(cx.listener(move |view, _event, _window, cx| {
                view.filter_by_category_from(&source, &dimensions, &values, cx);
            }))
    });

    div()
        .flex()
        .flex_col()
        .gap(px_lienzo(4.0, zoom))
        .text_color(label_color)
        .child(components::nota_zoom(
            theme,
            if incompletas {
                "Muestra parcial · clic en una categoría para filtrar"
            } else {
                "Categorías · clic para filtrar"
            },
            zoom,
        ))
        .child(
            div()
                .flex()
                .items_center()
                .flex_wrap()
                .gap(px_lienzo(4.0, zoom))
                .max_h(px_lienzo(76.0, zoom))
                .overflow_y_scrollbar()
                .tab_index(0)
                .tab_group()
                .tab_stop(false)
                .children(elementos),
        )
        .into_any_element()
}

/// Las barras horizontales de una medida, una por categoria, y cada barra filtra.
///
/// Se dibujan con divs y no con un grafico del sistema porque el clic tiene que saber QUE
/// barra se toco, y los graficos no lo dicen.
fn id_fila_barras(source_id: &str, indice: usize) -> String {
    format!("barra-{source_id}-{indice}")
}

fn barras(
    theme: &Theme,
    puntos: &[Punto],
    dimension_ids: &[ObjectId],
    source_id: &str,
    highlight: Option<&Matrix>,
    etiquetas: bool,
    color_serie_rgb: u32,
    referencias: &[f64],
    zoom: f32,
    escala_texto: f32,
    label_color: Hsla,
    cx: &mut Context<Datan>,
) -> AnyElement {
    let escala = crate::visuales::EscalaBarras::desde_valores(
        puntos
            .iter()
            .map(|punto| punto.valor)
            .chain(referencias.iter().copied()),
    );
    let origen = escala.origen() as f32;

    let filas: Vec<AnyElement> = puntos
        .iter()
        .enumerate()
        .map(|(indice, punto)| {
            let atenuado = highlight
                .is_some_and(|matrix| !matrix_contiene_categoria(matrix, &punto.clave_categoria));
            let posicion = escala.posicion(punto.valor) as f32;
            let fraccion = escala.ancho(punto.valor) as f32;
            let espacio_izquierdo = posicion.min(origen);
            let espacio_derecho = (1.0 - espacio_izquierdo - fraccion).max(0.0);
            let category_values = punto.clave_categoria.clone();
            let dimension_ids = dimension_ids.to_vec();
            let tooltip = tooltip_de_punto(punto, punto.valor);
            let source_id = source_id.to_string();
            let mut fila = div()
                .id(ElementId::Name(SharedString::from(id_fila_barras(
                    &source_id, indice,
                ))))
                .flex()
                .flex_shrink_0()
                .items_center()
                .gap(px_lienzo(8.0, zoom))
                .cursor_pointer()
                .hover(|style| style.bg(theme.list_hover))
                .child(
                    div()
                        .w(px_lienzo((150.0), zoom))
                        .flex_shrink_0()
                        .text_size(px_texto_lienzo(tokens::LETRA_ETIQUETA, zoom, escala_texto))
                        .text_color(label_color)
                        .overflow_hidden()
                        .truncate()
                        .child(punto.etiqueta.clone()),
                )
                .child(
                    div()
                        .relative()
                        .flex()
                        .flex_1()
                        .h(px_lienzo((18.0), zoom))
                        .rounded_sm()
                        .bg(theme.chart_grid)
                        .child(div().flex_grow(espacio_izquierdo * 1000.0))
                        .child(
                            div()
                                .flex_grow(fraccion * 1000.0)
                                .h_full()
                                .rounded_sm()
                                .bg({
                                    let color = punto.color_condicional.map_or_else(
                                        || {
                                            if color_serie_rgb == 0 {
                                                tokens::serie_unica(theme.is_dark()).into()
                                            } else {
                                                rgb(color_serie_rgb & 0x00ff_ffff)
                                            }
                                        },
                                        |color| rgb(color & 0x00ff_ffff),
                                    );
                                    if atenuado { color.opacity(0.22) } else { color }
                                }),
                        )
                        .child(div().flex_grow(espacio_derecho * 1000.0))
                        .children(referencias.iter().enumerate().map(|(reference_index, value)| {
                            div()
                                .absolute()
                                .left(relative(escala.posicion(*value) as f32))
                                .top_0()
                                .bottom_0()
                                .w(px_lienzo(if reference_index % 2 == 0 { 1.5 } else { 1.0 }, zoom))
                                .bg(theme.muted_foreground)
                                .child(
                                    div()
                                        .absolute()
                                        .left_0()
                                        .top_0()
                                        .px_1()
                                        .bg(theme.background)
                                        .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, escala_texto))
                                        .text_color(theme.foreground)
                                        .child(format_value(*value)),
                                )
                        })),
                );
            // Sin etiqueta el valor no se dibuja, que es lo que pide apagar las etiquetas. El
            // ancho de la columna no se reserva: la barra llega al borde y la fila no queda
            // coja.
            if etiquetas {
                fila = fila.child(
                    div()
                        .w(px_lienzo((80.0), zoom))
                        .flex_shrink_0()
                        .text_size(px_texto_lienzo(tokens::LETRA_ETIQUETA, zoom, escala_texto))
                        .text_align(TextAlign::Right)
                        .child(format_value_with(punto.valor, punto.formato.as_ref())),
                );
            }
            fila.on_click(cx.listener(move |view, _event, _window, cx| {
                view.filter_by_category_from(&source_id, &dimension_ids, &category_values, cx);
            }))
            .tooltip(move |window, cx| {
                gpui_kit::component::tooltip::Tooltip::new(tooltip.clone()).build(window, cx)
            })
            .into_any_element()
        })
        .collect();

    div()
        .flex()
        .flex_1()
        .flex_col()
        .gap(px_lienzo(4.0, zoom))
        .justify_center()
        .children(filas)
        .into_any_element()
}

fn barras_agrupadas(
    theme: &Theme,
    series: &visuales::DatosSeries,
    series_colors: &std::collections::BTreeMap<String, u32>,
    dimension_ids: &[ObjectId],
    source_id: &str,
    highlight: Option<&Matrix>,
    referencias: &[f64],
    axes: ChartAxes,
    zoom: f32,
    escala_texto: f32,
    label_color: Hsla,
    cx: &mut Context<Datan>,
) -> AnyElement {
    let scale = visuales::EscalaBarras::desde_valores(
        series
            .series
            .iter()
            .flat_map(|serie| serie.valores.iter().flatten().copied())
            .chain(referencias.iter().copied()),
    );
    let groups = series
        .categorias
        .iter()
        .enumerate()
        .map(|(category_index, category)| {
            let category_label = category.join(" · ");
            let rows = series
                .series
                .iter()
                .enumerate()
                .filter_map(|(series_index, serie)| {
                    let value = serie.valores.get(category_index).copied().flatten()?;
                    let mut key = category.clone();
                    key.push(serie.etiqueta.clone());
                    let dim_ids = dimension_ids.to_vec();
                    let source = source_id.to_string();
                    let muted =
                        highlight.is_some_and(|matrix| !matrix_contiene_categoria(matrix, &key));
                    let position = scale.posicion(value) as f32;
                    let width = scale.ancho(value) as f32;
                    let left = position.min(scale.origen() as f32);
                    let right = (1.0 - left - width).max(0.0);
                    let color = rgb(color_serie_leyenda(
                        &serie.etiqueta,
                        series_index,
                        series_colors,
                    ));
                    let tip = format!("{} · {}", serie.etiqueta, format_value(value));
                    Some(
                        div()
                            .id(ElementId::Name(SharedString::from(format!(
                                "bar-series-{category_index}-{series_index}"
                            ))))
                            .flex()
                            .items_center()
                            .gap(px_lienzo(6.0, zoom))
                            .child(
                                div()
                                    .w(px_lienzo(36.0, zoom))
                                    .text_size(px_texto_lienzo(
                                        tokens::LETRA_NOTA,
                                        zoom,
                                        escala_texto,
                                    ))
                                    .text_color(label_color)
                                    .child(serie.etiqueta.clone()),
                            )
                            .child(
                                div()
                                    .relative()
                                    .flex()
                                    .flex_1()
                                    .h(px_lienzo(10.0, zoom))
                                    .rounded_sm()
                                    .bg(if axes.grid {
                                        theme.chart_grid
                                    } else {
                                        theme.background
                                    })
                                    .child(div().flex_grow(left * 1000.0))
                                    .child(
                                        div()
                                            .flex_grow(width * 1000.0)
                                            .h_full()
                                            .rounded_sm()
                                            .bg(if muted { color.opacity(0.22) } else { color }),
                                    )
                                    .child(div().flex_grow(right * 1000.0))
                                    .children((0..=4).filter_map(|tick| {
                                        axes.grid.then(|| {
                                            div()
                                                .absolute()
                                                .left(relative(tick as f32 / 4.0))
                                                .top_0()
                                                .bottom_0()
                                                .w(px_lienzo(1.0, zoom))
                                                .bg(theme.border)
                                        })
                                    }))
                                    .children(referencias.iter().enumerate().map(|(reference_index, value)| {
                                        div()
                                            .absolute()
                                            .left(relative(scale.posicion(*value) as f32))
                                            .top_0()
                                            .bottom_0()
                                            .w(px_lienzo(if reference_index % 2 == 0 { 1.5 } else { 1.0 }, zoom))
                                            .bg(theme.muted_foreground)
                                            .child(
                                                div()
                                                    .absolute()
                                                    .left_0()
                                                    .top_0()
                                                    .px_1()
                                                    .bg(theme.background)
                                                    .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, escala_texto))
                                                    .text_color(theme.foreground)
                                                    .child(format_value(*value)),
                                            )
                                    })),
                            )
                            .on_click(cx.listener(move |view, _, _, cx| {
                                view.filter_by_category_from(&source, &dim_ids, &key, cx)
                            }))
                            .tooltip(move |window, cx| {
                                gpui_kit::component::tooltip::Tooltip::new(tip.clone())
                                    .build(window, cx)
                            })
                            .into_any_element(),
                    )
                })
                .collect::<Vec<_>>();
            div()
                .flex()
                .items_center()
                .gap(px_lienzo(10.0, zoom))
                .when(axes.y, |group| {
                    group.child(
                        div()
                            .w(px_lienzo(120.0, zoom))
                            .text_size(px_texto_lienzo(
                                tokens::LETRA_ETIQUETA,
                                zoom,
                                escala_texto,
                            ))
                            .overflow_hidden()
                            .truncate()
                            .child(category_label),
                    )
                })
                .child(
                    div()
                        .flex_1()
                        .flex()
                        .flex_col()
                        .gap(px_lienzo(2.0, zoom))
                        .children(rows),
                )
        });
    let axis_labels = div()
        .flex()
        .justify_between()
        .ml(px_lienzo(166.0, zoom))
        .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, escala_texto))
        .text_color(label_color)
        .when(axes.x, |labels| {
            labels
                .child(format_value(scale.minimo()))
                .child(format_value(scale.maximo()))
        });
    div()
        .flex()
        .flex_1()
        .flex_col()
        .justify_center()
        .gap(px_lienzo(8.0, zoom))
        .children(groups)
        .child(axis_labels)
        .into_any_element()
}

fn columnas_agrupadas(
    theme: &Theme,
    series: &visuales::DatosSeries,
    series_colors: &std::collections::BTreeMap<String, u32>,
    dimension_ids: &[ObjectId],
    source_id: &str,
    highlight: Option<&Matrix>,
    referencias: &[f64],
    axes: ChartAxes,
    zoom: f32,
    escala_texto: f32,
    label_color: Hsla,
    cx: &mut Context<Datan>,
) -> AnyElement {
    const CHART_HEIGHT: f32 = 136.0;
    let scale = visuales::EscalaBarras::desde_valores(
        series
            .series
            .iter()
            .flat_map(|serie| serie.valores.iter().flatten().copied())
            .chain(referencias.iter().copied()),
    );
    let baseline = (1.0 - scale.origen()) as f32 * CHART_HEIGHT;
    let groups = series
        .categorias
        .iter()
        .enumerate()
        .map(|(category_index, category)| {
            let bars = series
                .series
                .iter()
                .enumerate()
                .filter_map(|(series_index, serie)| {
                    let value = serie.valores.get(category_index).copied().flatten()?;
                    let mut key = category.clone();
                    key.push(serie.etiqueta.clone());
                    let dim_ids = dimension_ids.to_vec();
                    let source = source_id.to_string();
                    let muted =
                        highlight.is_some_and(|matrix| !matrix_contiene_categoria(matrix, &key));
                    let color = rgb(color_serie_leyenda(
                        &serie.etiqueta,
                        series_index,
                        series_colors,
                    ));
                    let geometry = grouped_column_geometry(value, scale, CHART_HEIGHT);
                    let tip = format!("{} · {}", serie.etiqueta, format_value(value));
                    Some(
                        div()
                            .id(ElementId::Name(SharedString::from(format!(
                                "column-series-{category_index}-{series_index}"
                            ))))
                            .relative()
                            .flex_1()
                            .h(px_lienzo(CHART_HEIGHT, zoom))
                            .child(
                                div()
                                    .absolute()
                                    .left_0()
                                    .right_0()
                                    .top(px_lienzo(geometry.top, zoom))
                                    .h(px_lienzo(geometry.height, zoom))
                                    .rounded_t(px_lienzo(3.0, zoom))
                                    .bg(if muted { color.opacity(0.22) } else { color }),
                            )
                            .on_click(cx.listener(move |view, _, _, cx| {
                                view.filter_by_category_from(&source, &dim_ids, &key, cx)
                            }))
                            .tooltip(move |window, cx| {
                                gpui_kit::component::tooltip::Tooltip::new(tip.clone())
                                    .build(window, cx)
                            }),
                    )
                });
            div()
                .relative()
                .flex_1()
                .flex()
                .flex_col()
                .items_center()
                .gap(px_lienzo(4.0, zoom))
                .child(
                    div()
                        .relative()
                        .flex()
                        .items_start()
                        .gap(px_lienzo(2.0, zoom))
                        .w_full()
                        .h(px_lienzo(CHART_HEIGHT, zoom))
                        .children((0..=4).filter_map(|tick| {
                            axes.grid.then(|| {
                                div()
                                    .absolute()
                                    .left_0()
                                    .right_0()
                                    .top(px_lienzo(CHART_HEIGHT * tick as f32 / 4.0, zoom))
                                    .h(px_lienzo(1.0, zoom))
                                    .bg(theme.chart_grid)
                            })
                        }))
                        .children(bars)
                        .children(referencias.iter().enumerate().map(|(reference_index, value)| {
                            let y = (1.0 - scale.posicion(*value) as f32) * CHART_HEIGHT;
                            div()
                                .absolute()
                                .left_0()
                                .right_0()
                                .top(px_lienzo(y, zoom))
                                .h(px_lienzo(if reference_index % 2 == 0 { 1.5 } else { 1.0 }, zoom))
                                .bg(theme.muted_foreground)
                                .child(
                                    div()
                                        .absolute()
                                        .right_0()
                                        .bottom(px_lienzo(1.0, zoom))
                                        .px_1()
                                        .bg(theme.background)
                                        .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, escala_texto))
                                        .text_color(theme.foreground)
                                        .child(format_value(*value)),
                                )
                        }))
                        .when(axes.x, |plot| {
                            plot.child(
                                div()
                                    .absolute()
                                    .left_0()
                                    .right_0()
                                    .top(px_lienzo(baseline, zoom))
                                    .h(px_lienzo(1.0, zoom))
                                    .bg(theme.border),
                            )
                        }),
                )
                .when(axes.x, |group| {
                    group.child(
                        div()
                            .text_size(px_texto_lienzo(
                                tokens::LETRA_NOTA,
                                zoom,
                                escala_texto,
                            ))
                            .text_color(label_color)
                            .overflow_hidden()
                            .truncate()
                            .child(category.join(" · ")),
                    )
                })
        });
    let y_axis_labels = div()
        .w(px_lienzo(if axes.y { 48.0 } else { 0.0 }, zoom))
        .h(px_lienzo(CHART_HEIGHT, zoom))
        .flex_shrink_0()
        .flex()
        .flex_col()
        .justify_between()
        .text_size(px_texto_lienzo(tokens::LETRA_NOTA, zoom, escala_texto))
        .text_color(label_color)
        .when(axes.y, |labels| {
            labels
                .child(format_value(scale.maximo()))
                .child(format_value(scale.minimo()))
        });
    div()
        .flex()
        .flex_1()
        .items_end()
        .gap(px_lienzo(8.0, zoom))
        .child(y_axis_labels)
        .children(groups)
        .into_any_element()
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct ColumnBarGeometry {
    top: f32,
    height: f32,
}

fn grouped_column_geometry(
    value: f64,
    scale: visuales::EscalaBarras,
    track_height: f32,
) -> ColumnBarGeometry {
    let baseline = (1.0 - scale.origen()) as f32 * track_height;
    let height = scale.ancho(value) as f32 * track_height;
    ColumnBarGeometry {
        top: if value >= 0.0 {
            baseline - height
        } else {
            baseline
        },
        height,
    }
}

fn valor_linea_constante_en_milesimas(texto: &str) -> Option<i64> {
    let valor = texto
        .trim()
        .replace(',', ".")
        .parse::<f64>()
        .ok()
        .filter(|valor| valor.is_finite())?;
    Some((valor.clamp(-1_000_000_000.0, 1_000_000_000.0) * 1000.0).round() as i64)
}

/// Un numero para una tarjeta o un eje: sin decimales inutiles.
///
/// `10000.0` y `10000.50` se leen distinto; `10000.000000` y `10000.500000` no. Tres
/// decimales es el punto donde un margen sigue siendo un margen y el ruido ya no molesta.
fn format_value(value: f64) -> String {
    if value.abs() >= 1e12 {
        format!("{:.1}B", value / 1e12)
    } else if value.abs() >= 1e9 {
        format!("{:.1}MM", value / 1e9)
    } else if value.abs() >= 1e6 {
        format!("{:.1}M", value / 1e6)
    } else if value.abs() >= 1e3 {
        format!("{:.1}K", value / 1e3)
    } else if value.fract() == 0.0 {
        format!("{}", value as i64)
    } else {
        format!("{value:.2}")
    }
}

/// Un `Div` con estilo de hover.
///
/// `Div` no tiene `when`, asi que el hover se aplica siempre y el color se decide aqui.
fn cx_hover(color: Hsla, cell: Div) -> Div {
    cell.hover(move |style| style.bg(color))
}

/// El nombre que queda despues de editar la pestaña. `None` es "no cambio nada".
///
/// Separado del metodo porque es la unica decision del renombre: un nombre vacio o igual al
/// anterior no toca el archivo, y el espacio de los costados no forma parte del nombre.
fn nombre_nuevo(viejo: &str, escrito: &str) -> Option<String> {
    let nuevo = escrito.trim();
    if nuevo.is_empty() || nuevo == viejo {
        return None;
    }
    Some(nuevo.to_string())
}

/// Aplica el tema de la app.
///
/// El archivo guarda un enum propio (`config::Tema`) y no el `ThemeMode` del componente: el
/// formato del archivo no tiene que cambiar el dia que el componente renombre el suyo.
fn aplicar_tema(tema: config::Tema, window: Option<&mut Window>, cx: &mut App) {
    let mode = match tema {
        config::Tema::Claro => gpui_kit::component::ThemeMode::Light,
        config::Tema::Oscuro => gpui_kit::component::ThemeMode::Dark,
        // La apariencia del escritorio. Sin ventana todavia (el arranque) la dice la app; con
        // ventana, la ventana, que es la que va a escuchar el cambio.
        config::Tema::Sistema => match window.as_deref() {
            Some(window) => window.appearance().into(),
            None => cx.window_appearance().into(),
        },
    };
    Theme::change(mode, window, cx);
}

/// Atajos de teclado globales de la app.
///
/// Los campos de texto consumen sus propias teclas antes de que lleguen aca: escribir en el
/// editor de medidas no borra el visual seleccionado. Las acciones igual se defienden solas:
/// cada handler valida vista, modo y estado antes de tocar nada.
fn registrar_atajos(cx: &mut App) {
    cx.bind_keys([
        KeyBinding::new("cmd-s", GuardarInforme, None),
        KeyBinding::new("cmd-z", DeshacerCambio, None),
        // Rehacer: Shift+Cmd+Z es el estandar de macOS; Cmd+Y es el alias que traen los
        // usuarios de Windows (Ctrl+Y). Los dos hacen lo mismo.
        KeyBinding::new("shift-cmd-z", RehacerCambio, None),
        KeyBinding::new("cmd-y", RehacerCambio, None),
        KeyBinding::new("backspace", BorrarVisualElegido, None),
        KeyBinding::new("delete", BorrarVisualElegido, None),
        // Cmd+Supr (⌘⌫) borra sin llevar la mano al Esc.
        KeyBinding::new("cmd-backspace", BorrarVisualElegido, None),
        KeyBinding::new("cmd-=", ZoomLienzoMas, None),
        KeyBinding::new("cmd-+", ZoomLienzoMas, None),
        KeyBinding::new("cmd--", ZoomLienzoMenos, None),
        KeyBinding::new("cmd-0", ZoomLienzoReal, None),
        // Esc cierra la capa de arriba: un dialogo, el editor de medidas, un renombre.
        // Sin atajo, cerrar un dialogo abierto por error exige ir con el mouse al boton.
        KeyBinding::new("escape", CerrarCapa, None),
        // Abrir pasa por la lista de informes guardados, igual que el boton.
        KeyBinding::new("cmd-o", AbrirInformes, None),
        // Salir con el mismo flujo del boton de cierre: pregunta por los cambios.
        KeyBinding::new("cmd-q", CerrarDatan, None),
    ]);
}

fn main() {
    application()
        // `Assets` es el juego corto de 106 iconos del componente, y no tiene los siete que
        // usa esta pantalla: el logo, los cuatro tipos de grafico, el anillo, los mosaicos y
        // la tabla quedaban como un hueco en blanco. `AllAssets` es el catalogo completo.
        .with_assets(assets::AllAssets)
        .run(|cx| {
            init(cx);
            registrar_atajos(cx);
            // El tema se aplica antes de abrir la ventana: al reves, el primer frame se pinta
            // claro y el segundo oscuro, un parpadeo en cada arranque.
            aplicar_tema(config::Preferences::load().tema, None, cx);
            let database = std::env::var("DATAN_AUTOCONNECT").unwrap_or_default();
            let window_options = if cfg!(target_os = "macos") {
                WindowOptions {
                    titlebar: Some(TitlebarOptions {
                        title: None,
                        appears_transparent: true,
                        traffic_light_position: Some(point(
                            px(12.0),
                            px((tokens::BARRA_SUPERIOR - 14.0) / 2.0),
                        )),
                    }),
                    ..gpui_kit::component::TitleBar::window_options()
                }
            } else {
                WindowOptions::default()
            };
            open_window(window_options, cx, |window, cx| {
                let view = cx.new(Datan::new);
                // Con "Sistema" elegido, la app sigue el cambio de apariencia del escritorio.
                // El observador se guarda en la vista: al soltarlo se deja de escuchar.
                let seguir = view.clone();
                let apariencia = window.observe_window_appearance(move |window, cx| {
                    if seguir.read(cx).tema != config::Tema::Sistema {
                        return;
                    }
                    let appearance = window.appearance();
                    Theme::change(appearance, Some(window), cx);
                });
                view.update(cx, |view, _| view.apariencia = Some(apariencia));
                // La ventana sostiene el foco raiz desde el arranque: sin foco, los atajos
                // no despachan.
                let handle = view.read(cx).focus_handle.clone();
                window.focus(&handle, cx);
                // El boton rojo de la ventana pasa por aca: con cambios sin guardar abre el
                // dialogo, sin ellos apaga el proceso.
                let view_para_cierre = view.clone();
                window.on_window_should_close(cx, move |_window, cx| {
                    view_para_cierre.update(cx, |view, cx| view.cerrar_ventana(cx))
                });
                // `DATAN_AUTOCONNECT=datan_bench` arranca conectado. Es para desarrollo: en
                // pruebas hay que poder mirar el lienzo sin un clic de por medio. Sin la
                // variable, la app arranca en la pantalla de conexion, como debe.
                if !database.is_empty() {
                    view.update(cx, |view, cx| view.connect(&database, cx));
                }
                view
            })
            .expect("no se pudo abrir la ventana");
        });
}
