    #[test]
    fn el_rol_tooltips_agrega_las_medidas_a_la_consulta_sin_duplicar() {
        let model = datan_model::Model {
            tables: vec![],
            measures: vec![datan_model::Measure::new(
                super::ObjectId(1),
                "Ventas",
                "SUM(hechos[importe])",
            )],
            relationships: vec![],
        };
        let vista = super::Vista {
            selection: super::Selection {
                dimensions: vec![],
                legend: None,
                measures: vec![],
                implicit_measures: vec![],
                value_order: vec![],
            },
            matrix_row_count: None,
            filters: Vec::new(),
            visual: "Lineas".to_string(),
            sort: None,
            top_n: None,
            date_months: None,
            formatos: std::collections::BTreeMap::new(),
        };
        let mut roles = std::collections::BTreeMap::new();
        roles.insert(
            datan_report::saved::SavedVisualRole::Tooltips,
            vec![
                datan_report::saved::SavedVisualField::Measure("Ventas".into()),
                datan_report::saved::SavedVisualField::Measure("Inexistente".into()),
            ],
        );

        let extendida = super::vista_con_medidas_tooltip(&model, &vista, &roles);
        assert_eq!(extendida.selection.measures, vec![super::ObjectId(1)]);
        // El orden de valores tambien tiene que incluirla: ordenar_medidas_visual filtra
        // por el, y una medida fuera del orden no llega a la consulta.
        assert_eq!(
            extendida.selection.value_order,
            vec![super::ValueSelection::Measure(super::ObjectId(1))]
        );

        // Ya seleccionada: la vista no cambia.
        let mut con_medida = vista.clone();
        con_medida.selection.measures = vec![super::ObjectId(1)];
        let mut roles_con_medida = std::collections::BTreeMap::new();
        roles_con_medida.insert(
            datan_report::saved::SavedVisualRole::Tooltips,
            vec![datan_report::saved::SavedVisualField::Measure("Ventas".into())],
        );
        let extendida = super::vista_con_medidas_tooltip(&model, &con_medida, &roles_con_medida);
        assert_eq!(extendida.selection.measures, vec![super::ObjectId(1)]);
        assert!(extendida.selection.value_order.is_empty());

        // Sin rol de tooltips: la vista queda igual.
        let sin_rol = super::vista_con_medidas_tooltip(
            &model,
            &vista,
            &std::collections::BTreeMap::new(),
        );
        assert_eq!(sin_rol.selection.measures, vec![]);
        assert!(sin_rol.selection.value_order.is_empty());
    }

    #[test]
    fn la_tabla_ordena_dimensiones_por_texto_y_medidas_por_numero() {
        // Una medida compara por numero: 9 < 10 aunque "9" > "10" como texto.
        let nueve = vec!["a".to_string(), "9".to_string()];
        let diez = vec!["b".to_string(), "10".to_string()];
        assert_eq!(
            super::comparar_filas_grid(&nueve, &diez, 1, false),
            std::cmp::Ordering::Less
        );
        // Como texto habria dado Mayor.
        assert_eq!(
            super::comparar_filas_grid(&nueve, &diez, 1, true),
            std::cmp::Ordering::Greater
        );
        // Una dimension compara por texto, y el renglon en blanco va primero.
        let blanco = vec!["".to_string()];
        let a = vec!["a".to_string()];
        let b = vec!["b".to_string()];
        assert_eq!(
            super::comparar_filas_grid(&blanco, &a, 0, true),
            std::cmp::Ordering::Less
        );
        assert_eq!(
            super::comparar_filas_grid(&a, &b, 0, true),
            std::cmp::Ordering::Less
        );
    }

