    #[test]
    fn columnas_agrupadas_muestra_valores_negativos_bajo_la_linea_cero() {
        let scale = super::visuales::EscalaBarras::desde_valores([-6.0, 4.0]);
        let positive = super::grouped_column_geometry(4.0, scale, 100.0);
        let negative = super::grouped_column_geometry(-6.0, scale, 100.0);

        assert!((positive.top - 0.0).abs() < 0.001);
        assert!((positive.height - 40.0).abs() < 0.001);
        assert!((negative.top - 40.0).abs() < 0.001);
        assert!((negative.height - 60.0).abs() < 0.001);
        assert!(positive.top >= 0.0 && positive.top + positive.height <= 100.0);
        assert!(negative.top >= 0.0 && negative.top + negative.height <= 100.0);

        let positive_scale = super::visuales::EscalaBarras::desde_valores([2.0, 4.0]);
        let short_positive = super::grouped_column_geometry(2.0, positive_scale, 100.0);
        let tall_positive = super::grouped_column_geometry(4.0, positive_scale, 100.0);
        assert!((short_positive.top - 50.0).abs() < 0.001);
        assert!((short_positive.height - 50.0).abs() < 0.001);
        assert!((tall_positive.top - 0.0).abs() < 0.001);
        assert!((tall_positive.height - 100.0).abs() < 0.001);
        assert!(short_positive.top + short_positive.height <= 100.0);
        assert!(tall_positive.top + tall_positive.height <= 100.0);
    }

