    #[test]
    fn quitar_medida_limpia_todos_sus_roles_de_medidor() {
        let measure = super::ValueSelection::Measure(super::ObjectId(7));
        let other = super::ValueSelection::Measure(super::ObjectId(8));
        let mut fields = super::GaugeFields {
            value: Some(measure),
            minimum: Some(measure),
            maximum: Some(other),
            target: Some(measure),
        };

        fields.remove(measure);

        assert_eq!(fields.value, None);
        assert_eq!(fields.minimum, None);
        assert_eq!(fields.maximum, Some(other));
        assert_eq!(fields.target, None);
    }

