    #[test]
    fn los_visuales_con_roles_usan_slots_explicitos_y_orden_guardado() {
        assert_eq!(super::ordered_value_roles("KPI"), &["Valor", "Objetivo"]);
        assert_eq!(
            super::ordered_value_roles("Dispersion"),
            &["Eje X", "Eje Y"]
        );
        assert_eq!(
            super::ordered_value_roles("Combinado"),
            &["Valores de columnas", "Valores de línea"]
        );
        assert_eq!(
            super::ordered_value_roles("Candlestick"),
            &["Apertura", "Máximo", "Mínimo", "Cierre"]
        );
        assert!(super::ordered_value_roles("Lineas").is_empty());

        let first = super::ValueSelection::Measure(super::ObjectId(1));
        let second = super::ValueSelection::Implicit(super::ObjectId(2), super::Aggregation::Sum);
        let replacement = super::ValueSelection::Measure(super::ObjectId(3));
        let mut selection = super::Selection {
            dimensions: Vec::new(),
            legend: None,
            measures: Vec::new(),
            implicit_measures: Vec::new(),
            value_order: Vec::new(),
        };
        let model = super::Model::default();

        assert_eq!(
            super::colocar_valor_en_orden(&mut selection, 0, first),
            Ok(None)
        );
        assert_eq!(
            super::colocar_valor_en_orden(&mut selection, 2, second),
            Err(())
        );
        assert_eq!(
            super::colocar_valor_en_orden(&mut selection, 1, second),
            Ok(None)
        );
        assert_eq!(
            super::colocar_valor_en_orden(&mut selection, 0, replacement),
            Ok(Some(first))
        );
        assert_eq!(selection.value_order, vec![replacement, second]);
    }

