    #[test]
    fn model_table_positions_roundtrip_by_unique_table_name() {
        let model = datan_testkit::model();
        let runtime = std::collections::BTreeMap::from([
            (datan_testkit::FACT, (120.4, 240.6)),
            (datan_testkit::DATE_TABLE, (f32::NAN, 10.0)),
        ]);

        let saved = super::posiciones_modelo_guardadas(&model, &runtime);
        assert_eq!(
            saved.get("fact_sales"),
            Some(&datan_report::saved::SavedModelPosition { x: 120, y: 241 })
        );
        assert!(!saved.contains_key("dim_date"));

        let restored = super::posiciones_modelo_resueltas(
            &model,
            &std::collections::BTreeMap::from([
                (
                    "FACT_SALES".to_string(),
                    datan_report::saved::SavedModelPosition { x: 120, y: 241 },
                ),
                (
                    "missing".to_string(),
                    datan_report::saved::SavedModelPosition { x: 1, y: 2 },
                ),
            ]),
        );
        assert_eq!(
            restored,
            std::collections::BTreeMap::from([(datan_testkit::FACT, (120.0, 241.0))])
        );
    }

