    #[test]
    fn dos_agregaciones_del_mismo_campo_conservan_identidad_separada() {
        let column = super::ObjectId(10);
        let sum = super::ImplicitMeasure {
            column,
            aggregation: super::Aggregation::Sum,
        };
        let average = super::ImplicitMeasure {
            column,
            aggregation: super::Aggregation::Average,
        };
        let mut selection = super::Selection {
            dimensions: Vec::new(),
            legend: None,
            measures: Vec::new(),
            implicit_measures: vec![sum, average],
            value_order: vec![sum.selection(), average.selection()],
        };
        let model = super::Model::default();

        assert!(selection.value_is_selected(sum.selection()));
        assert!(selection.value_is_selected(average.selection()));
        assert!(super::aggregation_available(
            &selection,
            &model,
            sum.selection(),
            super::Aggregation::Sum,
        ));
        assert!(!super::aggregation_available(
            &selection,
            &model,
            sum.selection(),
            super::Aggregation::Average,
        ));
        assert_ne!(
            super::value_selection_key(sum.selection()),
            super::value_selection_key(average.selection()),
        );
        assert_eq!(
            super::Aggregation::next_for_column(
                &selection,
                &model,
                column,
                super::DataType::Decimal,
            ),
            Some(super::Aggregation::Count),
        );

        super::quitar_valor_seleccion(&mut selection, sum.selection());

        assert!(!selection.value_is_selected(sum.selection()));
        assert!(selection.value_is_selected(average.selection()));
        assert_eq!(selection.value_order, vec![average.selection()]);
    }

