    #[test]
    fn una_eleccion_vieja_se_reemplaza_y_persiste_si_queda_una_candidata() {
        let path =
            std::env::temp_dir().join(format!("datan-fact-recovery-{}.toml", std::process::id()));
        let mut document = ModelDoc {
            fact_table: Some("ventas_archivadas".to_string()),
            ..ModelDoc::default()
        };
        document.save_to(&path).expect("guarda selección vieja");

        let candidates = vec!["ventas_actuales".to_string()];
        let recovered = super::fact_selection_after_stale(&candidates);
        super::persist_fact_selection(&mut document, recovered.as_deref(), &path)
            .expect("guarda selección recuperada");

        let reloaded = ModelDoc::load_from(&path).expect("vuelve a abrir el documento");
        let _ = std::fs::remove_file(path);
        assert_eq!(reloaded.fact_table.as_deref(), Some("ventas_actuales"));
    }

