    #[test]
    fn relation_creation_detects_one_to_one_and_uses_many_to_many_without_single_keys() {
        let mut model = modelo_relaciones();
        model.tables[1].key_columns = vec![super::ObjectId(21)];
        assert_eq!(
            super::preparar_relacion(&model, super::ObjectId(11), super::ObjectId(21)),
            Ok((
                super::ObjectId(11),
                super::ObjectId(21),
                super::Cardinality::OneToOne
            ))
        );

        model.tables[0].key_columns.push(super::ObjectId(12));
        model.tables[1].key_columns.push(super::ObjectId(22));
        assert_eq!(
            super::preparar_relacion(&model, super::ObjectId(11), super::ObjectId(21)),
            Ok((
                super::ObjectId(11),
                super::ObjectId(21),
                super::Cardinality::ManyToMany
            ))
        );
    }

