    #[test]
    fn informe_reciente_no_conecta_a_un_origen_reemplazado() {
        use super::{RecentReportSource, recent_report_source};

        let profile = super::config::Connection {
            name: "ventas".to_string(),
            database: "ventas".to_string(),
            host: "db.example.test".to_string(),
            port: 5432,
            username: "analista".to_string(),
            sslmode: "prefer".to_string(),
            mode: super::config::ConnectionMode::DirectQuery,
            table: String::new(),
            source_query: None,
        };

        assert!(matches!(
            recent_report_source(false, true, None),
            RecentReportSource::Unavailable
        ));
        let malformed_key = super::config::Connection::from_document_key(
            "ventas".to_string(),
            "source-v1--malformed",
        );
        assert!(matches!(
            recent_report_source(false, true, malformed_key),
            RecentReportSource::Unavailable
        ));
        let blank_host_key = super::config::Connection::from_document_key(
            "ventas".to_string(),
            "source-v1--db----5432--user",
        );
        assert!(matches!(
            recent_report_source(false, true, blank_host_key),
            RecentReportSource::Unavailable
        ));
        assert!(matches!(
            recent_report_source(false, true, Some(profile)),
            RecentReportSource::Reconnect(_)
        ));
        assert!(matches!(
            recent_report_source(false, false, None),
            RecentReportSource::Choose
        ));
        assert!(matches!(
            recent_report_source(true, true, None),
            RecentReportSource::Current
        ));
    }

    #[test]
    fn organizar_modelo_centra_hechos_y_reparte_dimensiones_a_los_lados() {
        let table = |id, kind, column_count| datan_model::Table {
            id: ObjectId(id),
            name: format!("tabla_{id}"),
            kind,
            columns: (0..column_count)
                .map(|column| {
                    datan_model::Column::new(
                        ObjectId(id * 100 + column as u64),
                        format!("campo_{column}"),
                        DataType::Integer,
                    )
                })
                .collect(),
            key_columns: Vec::new(),
            is_date_table: false,
        };
        let model = datan_model::Model {
            tables: vec![
                table(1, datan_model::TableKind::Dimension, 2),
                table(2, datan_model::TableKind::Facts, 4),
                table(3, datan_model::TableKind::Dimension, 3),
                table(4, datan_model::TableKind::Dimension, 1),
                table(5, datan_model::TableKind::Dimension, 2),
            ],
            measures: Vec::new(),
            relationships: Vec::new(),
        };

        assert_eq!(posicion_inicial_tabla(&model, 1), (340.0, 168.0));
        assert_eq!(posicion_inicial_tabla(&model, 0), (100.0, 100.0));
        assert_eq!(posicion_inicial_tabla(&model, 3), (650.0, 100.0));
        assert_eq!(posicion_inicial_tabla(&model, 2), (100.0, 240.0));
        assert_eq!(posicion_inicial_tabla(&model, 4), (650.0, 216.0));
        assert!(posicion_inicial_tabla(&model, 2).1 > posicion_inicial_tabla(&model, 0).1);
        assert!(posicion_inicial_tabla(&model, 4).1 > posicion_inicial_tabla(&model, 3).1);
        let visible = model.tables.iter().map(|table| table.id).collect();
        assert!(zoom_ajustado_modelo(&model, &Default::default(), &visible, 700.0, 500.0) < 100);
        assert_eq!(
            zoom_ajustado_modelo(&model, &Default::default(), &visible, 10_000.0, 10_000.0),
            150
        );
        let visible_fact = [model.tables[1].id].into_iter().collect();
        assert_eq!(
            zoom_ajustado_modelo(&model, &Default::default(), &visible_fact, 700.0, 500.0),
            150
        );
    }

