    #[test]
    fn zoom_del_modelo_mantiene_el_punto_bajo_el_cursor() {
        let pointer = point(px(180.0), px(120.0));
        let scroll = point(px(-60.0), px(-30.0));
        let old_content = point(
            (pointer.x - scroll.x) / px(1.0),
            (pointer.y - scroll.y) / px(1.0),
        );
        let (percent, next_scroll) = zoom_modelo_en_punto(100, 10.0, pointer, scroll);
        let new_content = point(
            (pointer.x - next_scroll.x) / px(percent as f32 / 100.0),
            (pointer.y - next_scroll.y) / px(percent as f32 / 100.0),
        );

        assert_eq!(percent, 110);
        assert!((old_content.x - new_content.x).abs() < 1.0);
        assert!((old_content.y - new_content.y).abs() < 1.0);
        assert_eq!(zoom_modelo_en_punto(100, -1.0, pointer, scroll).0, 99);
        assert_eq!(zoom_modelo_en_punto(100, 1.0, pointer, scroll).0, 101);
        assert_eq!(zoom_modelo_en_punto(40, -1.0, pointer, scroll).0, 40);
        assert_eq!(zoom_modelo_en_punto(150, 1.0, pointer, scroll).0, 150);
    }

    #[test]
    fn minimapa_acepta_un_viewport_que_cubre_el_contenido_completo() {
        let viewport =
            super::minimap_viewport_axis(0.0, 600.0, 1.0, 0.0, 600.0, 3.8146973e-6, 176.0 / 600.0);

        assert_eq!(viewport, Some((3.8146973e-6, 176.0)));
        let oversized =
            super::minimap_viewport_axis(0.0, 900.0, 1.0, 0.0, 600.0, 3.8146973e-6, 176.0 / 600.0);
        assert_eq!(oversized, viewport);

        let partial = super::minimap_viewport_axis(-100.0, 200.0, 1.0, 100.0, 700.0, 12.0, 0.2);
        assert_eq!(partial, Some((12.0, 40.0)));
        assert_eq!(
            super::minimap_viewport_axis(-800.0, 100.0, 1.0, 100.0, 700.0, 12.0, 0.2),
            None
        );
    }

