    #[test]
    fn zoom_rueda_acumula_deltas_pequenos_y_respeta_el_sentido() {
        let (first, remainder) = acumular_zoom_rueda(0.0, 1.0);
        assert_eq!(first, 0);
        assert_eq!(remainder, 0.25);

        let (next, remainder) = acumular_zoom_rueda(remainder, 3.0);
        assert_eq!(next, 1);
        assert_eq!(remainder, 0.0);

        let (large, remainder) = acumular_zoom_rueda(0.0, 40.0);
        assert_eq!(large, 10);
        assert_eq!(remainder, 0.0);

        let (reverse, remainder) = acumular_zoom_rueda(0.0, -40.0);
        assert_eq!(reverse, -10);
        assert_eq!(remainder, 0.0);
        assert_eq!(
            zoom_modelo_en_punto(
                149,
                large as f32,
                point(px(0.0), px(0.0)),
                point(px(0.0), px(0.0))
            )
            .0,
            150
        );
        assert_eq!(
            zoom_modelo_en_punto(
                41,
                reverse as f32,
                point(px(0.0), px(0.0)),
                point(px(0.0), px(0.0))
            )
            .0,
            40
        );
    }

