    #[test]
    fn el_clic_en_categoria_compuesta_conserva_todas_sus_dimensiones() {
        let columns = [ObjectId(7), ObjectId(8)];
        let values = ["Norte".to_string(), "Mesa".to_string()];
        let filters =
            filtros_fila_tabla(
                super::RowKind::Data,
                &columns,
                &values,
                |column| match column {
                    ObjectId(7) => "Region".to_string(),
                    ObjectId(8) => "Producto".to_string(),
                    _ => String::new(),
                },
            )
            .expect("la fila tiene todos sus valores dimensionales");

        assert_eq!(filters.len(), 2);
        assert_eq!(filters[0].column, ObjectId(7));
        assert_eq!(filters[0].label.as_ref(), "Region");
        assert_eq!(filters[0].value.as_ref(), "Norte");
        assert_eq!(filters[1].column, ObjectId(8));
        assert_eq!(filters[1].label.as_ref(), "Producto");
        assert_eq!(filters[1].value.as_ref(), "Mesa");
        assert!(
            filtros_fila_tabla(super::RowKind::Data, &columns, &values[..1], |_| {
                String::new()
            })
            .is_none()
        );
        assert!(filtros_fila_tabla(super::RowKind::Data, &[], &[], |_| String::new()).is_none());
        assert!(
            filtros_fila_tabla(
                super::RowKind::Subtotal { level: 0 },
                &columns,
                &values,
                |_| String::new()
            )
            .is_none()
        );
        assert!(
            filtros_fila_tabla(super::RowKind::GrandTotal, &columns, &values, |_| {
                String::new()
            })
            .is_none()
        );
    }

