    #[test]
    fn subtotales_de_columna_consultan_solo_la_dimension_pivotada() {
        let model = datan_testkit::model();
        let report = datan_report::Report::new(model)
            .with_dimensions(vec![
                datan_testkit::PRODUCT_REGION,
                datan_testkit::PRODUCT_CATEGORY,
            ])
            .with_measures(vec![ObjectId(101)])
            .filtered_by(
                datan_testkit::PRODUCT_REGION,
                datan_dax_eval::FilterValue::Text("Norte".to_string()),
            );
        let totals = reporte_subtotales_columna(&report, true, 1).expect("consulta de columnas");
        let expected = datan_report::Report::new(datan_testkit::model())
            .with_dimensions(vec![datan_testkit::PRODUCT_CATEGORY])
            .with_measures(vec![ObjectId(101)])
            .filtered_by(
                datan_testkit::PRODUCT_REGION,
                datan_dax_eval::FilterValue::Text("Norte".to_string()),
            );

        assert_eq!(totals.dimensions, vec![datan_testkit::PRODUCT_CATEGORY]);
        let actual_engine = datan_testkit::engine().expect("motor");
        let expected_engine = datan_testkit::engine().expect("motor esperado");
        let actual = totals.execute(&actual_engine, None).expect("totales");
        let expected = expected.execute(&expected_engine, None).expect("esperado");
        assert_eq!(actual.headers, expected.headers);
        assert_eq!(actual.rows, expected.rows);
        assert!(reporte_subtotales_columna(&report, false, 1).is_none());
        assert!(
            reporte_subtotales_columna(
                &report.clone().with_top_n(datan_report::TopN {
                    measure: ObjectId(101),
                    count: 3,
                    abajo: false,
                }),
                true,
                1,
            )
            .is_none()
        );
    }

