    #[test]
    fn subtotal_de_columna_evalua_medidas_no_aditivas_en_su_contexto() {
        let report = datan_report::Report::new(datan_testkit::model())
            .with_dimensions(vec![
                datan_testkit::PRODUCT_REGION,
                datan_testkit::PRODUCT_CATEGORY,
            ])
            .with_measures(vec![ObjectId(103)]);
        let totals = reporte_subtotales_columna(&report, true, 1).expect("consulta de columnas");
        let engine = datan_testkit::engine().expect("motor");
        let detail = report
            .execute(&engine, None)
            .expect("medidas por region y categoria");
        let column_totals = totals.execute(&engine, None).expect("totales de categoria");
        let mut sum_of_rows = std::collections::BTreeMap::<String, f64>::new();
        for (index, row) in detail.rows.iter().enumerate() {
            if detail.row_kind(index) != datan_report::RowKind::Data {
                continue;
            }
            if let (Some(category), Some(value)) = (row.get(1), row.get(2))
                && let Ok(value) = value.parse::<f64>()
            {
                *sum_of_rows.entry(category.clone()).or_default() += value;
            }
        }
        assert!(column_totals.rows.iter().any(|row| {
            let Some(category) = row.first() else {
                return false;
            };
            let Some(value) = row.get(1).and_then(|value| value.parse::<f64>().ok()) else {
                return false;
            };
            sum_of_rows
                .get(category)
                .is_some_and(|sum| (sum - value).abs() > 1e-6)
        }));
    }

