    #[test]
    fn el_texto_igual_al_rotulo_en_blanco_sobrevive_al_guardar_y_abrir() {
        use datan_model::{Table, TableKind};

        let model = datan_model::Model {
            tables: vec![Table {
                id: ObjectId(1),
                name: "catalogo".to_string(),
                kind: TableKind::Dimension,
                columns: vec![datan_model::Column::new(
                    ObjectId(7),
                    "categoria",
                    DataType::Text,
                )],
                key_columns: Vec::new(),
                is_date_table: false,
            }],
            ..datan_model::Model::default()
        };
        let text = datan_report::ETIQUETA_EN_BLANCO.to_string();
        let prefixed_text = format!("{FILTER_TEXT_LITERAL_PREFIX}valor real");
        let saved = datan_report::saved::SavedFilter {
            column: "categoria".to_string(),
            table: Some("catalogo".to_string()),
            values: vec![
                format!("{:?}", datan_dax_eval::FilterValue::Text(text.clone())),
                format!(
                    "{:?}",
                    datan_dax_eval::FilterValue::Text(prefixed_text.clone())
                ),
            ],
            operator: None,
        };

        let reopened = filtros_desde_guardados(&model, &[saved]);

        assert_eq!(reopened.len(), 2);
        assert_eq!(
            valor_de_filtro(DataType::Text, &reopened[0].value),
            datan_dax_eval::FilterValue::Text(text)
        );
        assert_eq!(
            valor_de_filtro(DataType::Text, &reopened[1].value),
            datan_dax_eval::FilterValue::Text(prefixed_text)
        );
    }

