    #[test]
    fn deshacer_y_rehacer_restauran_las_selecciones_temporales_de_graficos() {
        let mut page = pagina_inicial("Página 1".to_string(), vista("Barras"));
        let source_id = page.visual_activo.clone();
        let filters = [ActiveFilter {
            column: ObjectId(18),
            label: "Región".into(),
            value: "Norte".into(),
            operator: None,
            upper_value: None,
        }];
        alternar_seleccion_grafico(&mut page, &source_id, &filters);

        let mut history = Historial::default();
        history.recordar(super::interacciones_grafico_guardadas(Some(&page)));
        alternar_seleccion_grafico(&mut page, &source_id, &filters);

        let empty = super::interacciones_grafico_guardadas(Some(&page));
        let selected = history.deshacer(empty).expect("restaura la selección");
        super::restaurar_interacciones_grafico(&mut page, selected);
        assert!(page.interacciones_grafico.contains_key(&source_id));

        let selected = super::interacciones_grafico_guardadas(Some(&page));
        let cleared = history.rehacer(selected).expect("rehace el cambio");
        super::restaurar_interacciones_grafico(&mut page, cleared);
        assert!(!page.interacciones_grafico.contains_key(&source_id));
    }

