    #[test]
    fn duplicar_pagina_activa_la_copia_de_cualquier_pestana() {
        for (activa, origen) in [(0usize, 1usize), (2, 0), (1, 1)] {
            let mut paginas = ["Uno", "Dos", "Tres"]
                .into_iter()
                .map(|nombre| pagina_inicial(nombre.to_string(), vista("Barras")))
                .collect::<Vec<_>>();
            let copia = pagina_inicial("Copia".to_string(), vista("Barras"));
            let indice_copia = origen + 1;
            let mut pagina_activa = activa;

            assert_eq!(
                insertar_copia_pagina(&mut paginas, &mut pagina_activa, origen, copia),
                Some(indice_copia)
            );
            assert_eq!(pagina_activa, indice_copia);
            assert_eq!(paginas[indice_copia].nombre, "Copia");
        }
    }

    #[test]
    fn duplicar_pagina_reasigna_ids_en_visuales_interacciones_y_bookmarks() {
        let mut page = pagina_inicial("Página 1".to_string(), vista("Barras"));
        let mut second = page.visuales[0].clone();
        second.id = visual_id();
        let first_id = page.visuales[0].id.clone();
        let second_id = second.id.clone();
        page.visuales[0].interactions.insert(
            second_id.clone(),
            datan_report::saved::SavedInteraction::Highlight,
        );
        page.visuales.push(second);
        page.visual_activo = second_id.clone();
        page.bookmarks.push(BookmarkState {
            nombre: "Antes".to_string(),
            filtros: Vec::new(),
            visuales: page.visuales.clone(),
            visual_activo: second_id.clone(),
        });

        rekey_pagina(&mut page);

        let new_first = &page.visuales[0].id;
        let new_second = &page.visuales[1].id;
        assert_ne!(new_first, &first_id);
        assert_ne!(new_second, &second_id);
        assert_eq!(&page.visual_activo, new_second);
        assert_eq!(
            page.visuales[0].interactions.get(new_second),
            Some(&datan_report::saved::SavedInteraction::Highlight)
        );
        assert_eq!(
            page.bookmarks[0].visual_activo,
            page.bookmarks[0].visuales[1].id
        );
        assert_ne!(page.bookmarks[0].visuales[0].id, first_id);
        assert_ne!(page.bookmarks[0].visuales[1].id, second_id);
        assert_eq!(
            page.bookmarks[0].visuales[0]
                .interactions
                .get(&page.bookmarks[0].visuales[1].id),
            Some(&datan_report::saved::SavedInteraction::Highlight)
        );
    }

