    #[test]
    fn el_modo_de_interaccion_no_ofrece_resaltar_si_el_destino_no_lo_admite() {
        use datan_report::saved::SavedInteraction;

        assert_eq!(
            siguiente_interaccion(SavedInteraction::Filter, false),
            SavedInteraction::Disabled
        );
        assert_eq!(
            siguiente_interaccion(SavedInteraction::Filter, true),
            SavedInteraction::Highlight
        );
        assert_eq!(
            siguiente_interaccion(SavedInteraction::Disabled, false),
            SavedInteraction::Filter
        );
        for kind in ["Barras", "Columnas", "Dispersion", "Anillo", "Combinado"] {
            assert!(super::visual_admite_resaltado(kind), "{kind}");
        }
        for kind in ["Tabla", "Lineas", "Area", "KPI", "Medidor", "Treemap"] {
            assert!(!super::visual_admite_resaltado(kind), "{kind}");
        }
        assert!(!visual_admite_seleccion_interactiva("KPI"));
        assert!(!visual_admite_seleccion_interactiva("Segmentador"));
        assert!(visual_admite_seleccion_interactiva("Tabla"));
    }

