        assert!(mover_capa_visual(&mut layers, 0, true));
        assert_eq!(layers, ["medio", "fondo", "frente"]);
        assert!(mover_capa_visual(&mut layers, 1, true));
        assert_eq!(layers, ["medio", "frente", "fondo"]);
        assert!(mover_capa_visual(&mut layers, 2, false));
        assert_eq!(layers, ["medio", "fondo", "frente"]);
        assert!(!mover_capa_visual(&mut layers, 2, true));
