    #[test]
    fn el_orden_de_medidas_sube_y_baja_sin_salir_de_la_lista() {
        let mut measures = [1, 2, 3];

        assert!(mover_campo_vecino(&mut measures, 1, OrdenCampo::Arriba));
        assert_eq!(measures, [2, 1, 3]);
        assert!(mover_campo_vecino(&mut measures, 1, OrdenCampo::Abajo));
        assert_eq!(measures, [2, 3, 1]);
        assert!(!mover_campo_vecino(&mut measures, 0, OrdenCampo::Arriba));
        assert!(!mover_campo_vecino(&mut measures, 3, OrdenCampo::Abajo));
        assert_eq!(measures, [2, 3, 1]);
    }

    #[test]
    fn el_lienzo_alinea_y_distribuye_solo_los_visuales_elegidos() {
        use datan_report::saved::{SavedPosition, SavedSize};
        let mut items = vec![
            (
                "a".to_string(),
                SavedPosition { x: 20, y: 80 },
                SavedSize {
                    width: 100,
                    height: 40,
                },
            ),
            (
                "b".to_string(),
                SavedPosition { x: 180, y: 30 },
                SavedSize {
                    width: 80,
                    height: 60,
                },
            ),
            (
                "c".to_string(),
                SavedPosition { x: 400, y: 120 },
                SavedSize {
                    width: 120,
                    height: 30,
                },
            ),
            (
                "d".to_string(),
                SavedPosition { x: 600, y: 10 },
                SavedSize {
                    width: 70,
                    height: 20,
                },
            ),
        ];

        assert!(disponer_visuales(
            &mut items,
            &["a".into(), "c".into()],
            DisposicionLienzo::Izquierda
        ));
        assert_eq!(items[0].1.x, 20);
        assert_eq!(items[2].1.x, 20);
        assert_eq!(
            items[1].1.x, 180,
            "los visuales fuera de la seleccion no cambian"
        );
        items[2].1.x = 400;
        assert!(disponer_visuales(
            &mut items,
            &["a".into(), "b".into(), "c".into()],
            DisposicionLienzo::Horizontal
        ));
        assert_eq!(items[0].1.x, 20);
        assert_eq!(items[2].1.x, 400);
        assert_eq!(
            items[1].1.x, 220,
            "el espacio entre los visuales queda uniforme"
        );
        assert!(!disponer_visuales(
            &mut items,
            &["a".into(), "b".into()],
            DisposicionLienzo::Vertical
        ));
    }

