    #[test]
    fn division_de_matriz_conserva_una_dimension_en_cada_eje() {
        let dimensions = [ObjectId(1), ObjectId(2), ObjectId(3), ObjectId(4)];
        assert_eq!(matriz_filas(4, None), 3);
        assert_eq!(matriz_filas(4, Some(2)), 2);
        assert_eq!(matriz_filas(4, Some(0)), 1);
        assert_eq!(matriz_filas(4, Some(8)), 3);
        assert_eq!(
            siguiente_cantidad_filas(&dimensions, 3, ObjectId(3)),
            Some(2)
        );
        assert_eq!(
            siguiente_cantidad_filas(&dimensions, 2, ObjectId(3)),
            Some(3)
        );
        assert_eq!(siguiente_cantidad_filas(&dimensions, 2, ObjectId(1)), None);
        assert_eq!(siguiente_cantidad_filas(&dimensions, 2, ObjectId(4)), None);
        assert_eq!(matriz_filas(1, None), 1);
    }

