    #[test]
    fn medidor_usa_el_total_y_admite_una_medida_sin_dimension() {
        let measure = ObjectId(101);
        let model = datan_testkit::model();
        let selection = super::Selection {
            dimensions: Vec::new(),
            legend: None,
            measures: vec![measure],
            implicit_measures: Vec::new(),
            value_order: vec![super::ValueSelection::Measure(measure)],
        };
        let header = Header {
            label: "Amount".to_string(),
            column: ObjectId(0),
            measure: Some(measure),
            data_type: datan_model::DataType::Decimal,
        };
        let matrix = Matrix {
            headers: vec![
                Header {
                    label: "Zona".to_string(),
                    column: ObjectId(10),
                    measure: None,
                    data_type: datan_model::DataType::Text,
                },
                header.clone(),
            ],
            rows: vec![
                vec!["Zona Z".to_string(), "10".to_string()],
                vec!["Zona A".to_string(), "20".to_string()],
                vec!["Total".to_string(), "30".to_string()],
            ],
            kinds: vec![
                datan_report::RowKind::Data,
                datan_report::RowKind::Data,
                datan_report::RowKind::GrandTotal,
            ],
            truncated: false,
        };
        let gauge = super::medidor_de_matriz(
            &matrix,
            1,
            &selection,
            super::GaugeFields::default(),
            &model,
            "gauge-test",
            &std::collections::HashMap::new(),
        )
        .expect("el total alimenta el medidor");

        assert_eq!(gauge.etiqueta, "Amount");
        assert_eq!(gauge.valor, 30.0);
        assert_eq!((gauge.minimo, gauge.maximo), (0.0, 36.0));

        let scalar = Matrix {
            headers: vec![header],
            rows: vec![vec!["42".to_string()]],
            kinds: vec![datan_report::RowKind::GrandTotal],
            truncated: false,
        };
        assert_eq!(
            super::medidor_de_matriz(
                &scalar,
                0,
                &selection,
                super::GaugeFields::default(),
                &model,
                "gauge-scalar-test",
                &std::collections::HashMap::new(),
            )
            .map(|gauge| gauge.valor),
            Some(42.0)
        );
    }

    #[test]
    fn medidor_usa_los_limites_y_el_objetivo_asignados() {
        let measures = [ObjectId(101), ObjectId(102), ObjectId(103), ObjectId(104)];
        let selection = super::Selection {
            dimensions: Vec::new(),
            legend: None,
            measures: measures.to_vec(),
            implicit_measures: Vec::new(),
            value_order: measures
                .iter()
                .copied()
                .map(super::ValueSelection::Measure)
                .collect(),
        };
        let matrix = Matrix {
            headers: ["Valor", "Mínimo", "Máximo", "Objetivo"]
                .into_iter()
                .zip(measures)
                .map(|(label, measure)| Header {
                    label: label.to_string(),
                    column: ObjectId(0),
                    measure: Some(measure),
                    data_type: datan_model::DataType::Decimal,
                })
                .collect(),
            rows: vec![vec!["42".into(), "10".into(), "80".into(), "65".into()]],
            kinds: vec![datan_report::RowKind::GrandTotal],
            truncated: false,
        };
        let fields = super::GaugeFields {
            value: Some(super::ValueSelection::Measure(measures[0])),
            minimum: Some(super::ValueSelection::Measure(measures[1])),
            maximum: Some(super::ValueSelection::Measure(measures[2])),
            target: Some(super::ValueSelection::Measure(measures[3])),
        };

        let gauge = super::medidor_de_matriz(
            &matrix,
            0,
            &selection,
            fields,
            &datan_model::Model::default(),
            "gauge-configured-test",
            &std::collections::HashMap::new(),
        )
        .expect("los cuatro campos alimentan el medidor");

        assert_eq!(gauge.valor, 42.0);
        assert_eq!((gauge.minimo, gauge.maximo), (10.0, 80.0));
        assert_eq!(gauge.objetivo, Some(65.0));
    }

    #[test]
    fn instrucciones_de_visual_indican_campos_faltantes_y_orden() {
        assert_eq!(
            instruccion_eje("Sankey", 0),
            Some("Añade el origen y el destino.")
        );
        assert_eq!(
            instruccion_eje("Sankey", 1),
            Some("Añade el destino del flujo.")
        );
        assert_eq!(instruccion_eje("Sankey", 2), None);
        assert_eq!(instruccion_eje("Barras", 0), None);
        assert_eq!(
            instruccion_valores("Candlestick", 0),
            Some("Añade apertura, máximo, mínimo y cierre.")
        );
        assert_eq!(
            instruccion_valores("Candlestick", 3),
            Some("Añade la medida de cierre.")
        );
        assert_eq!(
            instruccion_valores("Combinado", 1),
            Some("Añade la medida para la línea.")
        );
        assert_eq!(
            instruccion_valores("Dispersion", 1),
            Some("Añade la medida del eje Y.")
        );
        assert_eq!(instruccion_valores("Columnas", 0), None);
        assert_eq!(
            mensaje_campos_visual("KPI", 0, 0),
            Some("Añade una medida desde Datos para mostrar el indicador.")
        );
        assert_eq!(mensaje_campos_visual("KPI", 0, 1), None);
        assert_eq!(
            mensaje_campos_visual("Sankey", 3, 1),
            Some("Sankey usa dos campos de eje: origen y destino. Quita los campos extra.")
        );
        assert_eq!(
            mensaje_campos_visual("Sankey", 2, 2),
            Some("Sankey usa una medida para el peso de los enlaces. Quita las medidas extra.")
        );
        assert_eq!(
            mensaje_campos_visual("Medidor", 0, 0),
            Some("Añade una medida a Valores para mostrar el medidor.")
        );
        assert_eq!(mensaje_campos_visual("Medidor", 0, 1), None);
        assert_eq!(mensaje_campos_visual("Medidor", 1, 1), None);
        assert_eq!(
            mensaje_campos_visual("Barras", 0, 1),
            Some("Añade un campo al eje para mostrar categorías.")
        );
        assert_eq!(
            mensaje_campos_visual("Lineas", 1, 0),
            Some("Añade una medida numérica a Valores desde Datos.")
        );
        assert_eq!(mensaje_campos_visual("Tarjetas", 0, 1), None);
        assert_eq!(
            mensaje_campos_visual("Barras", 0, 0),
            Some("Marca un campo en el eje y una medida en Valores desde Datos.")
        );
        assert_eq!(
            mensaje_campos_visual("Dispersion", 0, 0),
            Some("Marca una categoría en el eje y dos medidas numéricas para los ejes X e Y.")
        );
        assert_eq!(
            mensaje_campos_visual("Combinado", 1, 1),
            Some("Añade la medida para la línea.")
        );
        assert_eq!(
            mensaje_campos_visual("Tarjetas", 0, 0),
            Some("Añade una medida desde Datos para mostrar la tarjeta.")
        );
        assert_eq!(
            mensaje_campos_visual("Segmentador", 0, 0),
            Some("Añade un campo desde Datos para filtrar con este segmentador.")
        );
        assert_eq!(
            mensaje_sin_datos_visual("Barras"),
            "No hay categorías para mostrar. Revisa los filtros."
        );
        assert_eq!(
            mensaje_sin_datos_visual("Dispersion"),
            "No hay pares de valores para comparar. Revisa los filtros."
        );
        assert_eq!(
            mensaje_sin_datos_visual("Tabla"),
            "No hay filas para mostrar en esta tabla. Revisa los filtros."
        );
    }

