    #[test]
    fn los_dias_guardados_conservan_fechas_antes_y_despues_de_la_epoca() {
        let epoch = chrono::NaiveDate::from_ymd_opt(1970, 1, 1).expect("fecha valida");
        let before = chrono::NaiveDate::from_ymd_opt(1969, 12, 31).expect("fecha valida");
        let after = chrono::NaiveDate::from_ymd_opt(2024, 2, 29).expect("fecha valida");

        assert_eq!(fecha_desde_dia(0), Some(epoch));
        assert_eq!(dia_desde_fecha(before), -1);
        assert_eq!(fecha_desde_dia(dia_desde_fecha(after)), Some(after));
    }

