    #[test]
    fn tooltip_incluye_las_otras_medidas_de_la_fila() {
        let matrix = Matrix {
            headers: vec![
                Header {
                    label: "Producto".to_string(),
                    column: ObjectId(1),
                    measure: None,
                    data_type: DataType::Text,
                },
                Header {
                    label: "Región".to_string(),
                    column: ObjectId(4),
                    measure: None,
                    data_type: DataType::Text,
                },
                Header {
                    label: "Ventas".to_string(),
                    column: ObjectId(0),
                    measure: Some(ObjectId(2)),
                    data_type: DataType::Decimal,
                },
                Header {
                    label: "Margen".to_string(),
                    column: ObjectId(0),
                    measure: Some(ObjectId(3)),
                    data_type: DataType::Decimal,
                },
            ],
            rows: vec![
                vec![
                    "Mesa".to_string(),
                    "Norte".to_string(),
                    "100".to_string(),
                    "0.25".to_string(),
                ],
                vec![
                    "Mesa".to_string(),
                    "Sur".to_string(),
                    "80".to_string(),
                    "0.5".to_string(),
                ],
            ],
            kinds: vec![datan_report::RowKind::Data, datan_report::RowKind::Data],
            truncated: false,
        };
        let formatos = std::collections::HashMap::from([
            (
                ObjectId(2),
                formato::Formato::Moneda {
                    simbolo: "€".to_string(),
                    decimales: 2,
                },
            ),
            (ObjectId(3), formato::Formato::Porcentaje { decimales: 1 }),
        ]);
        let points = puntos_de_matriz_con_formatos(&matrix, 2, 8, true, &formatos);
        let first = tooltip_de_punto(&points[0], points[0].valor);
        let second = tooltip_de_punto(&points[1], points[1].valor);

        assert_eq!(points.len(), 2);
        assert!(first.contains("Margen:"));
        assert!(second.contains("Margen:"));
        assert!(first.contains("€100,00"));
        assert!(first.contains("Margen: 25,0%"));
        assert!(second.contains("Margen: 50,0%"));
        assert_ne!(first, second);
    }

    #[test]
    fn cross_highlight_compara_la_clave_completa_de_categoria() {
        let matrix = Matrix {
            headers: vec![
                Header {
                    label: "Producto".to_string(),
                    column: ObjectId(1),
                    measure: None,
                    data_type: DataType::Text,
                },
                Header {
                    label: "Región".to_string(),
                    column: ObjectId(4),
                    measure: None,
                    data_type: DataType::Text,
                },
            ],
            rows: vec![vec!["Mesa".to_string(), "Norte".to_string()]],
            kinds: vec![datan_report::RowKind::Data],
            truncated: false,
        };

        assert!(matrix_contiene_categoria(
            &matrix,
            &["Mesa".to_string(), "Norte".to_string()]
        ));
        assert!(!matrix_contiene_categoria(
            &matrix,
            &["Mesa".to_string(), "Sur".to_string()]
        ));
        assert!(!matrix_contiene_categoria(
            &matrix,
            &["Mesa · Norte".to_string()]
        ));
    }

