    #[test]
    fn combinado_alinea_medidas_por_categoria_y_usa_ejes_independientes() {
        let matrix = Matrix {
            headers: vec![
                Header {
                    label: "Mes".to_string(),
                    column: ObjectId(1),
                    measure: None,
                    data_type: DataType::Text,
                },
                Header {
                    label: "Ventas".to_string(),
                    column: ObjectId(0),
                    measure: Some(ObjectId(2)),
                    data_type: DataType::Decimal,
                },
                Header {
                    label: "Margen".to_string(),
                    column: ObjectId(0),
                    measure: Some(ObjectId(3)),
                    data_type: DataType::Decimal,
                },
            ],
            rows: vec![
                vec!["Total".to_string(), "180".to_string(), "0.7".to_string()],
                vec!["Enero".to_string(), "120".to_string(), "0.2".to_string()],
                vec!["Febrero".to_string(), "60".to_string(), "0.9".to_string()],
                vec!["Marzo".to_string(), "100".to_string(), "0.4".to_string()],
            ],
            kinds: vec![
                datan_report::RowKind::Subtotal { level: 0 },
                datan_report::RowKind::Data,
                datan_report::RowKind::Data,
                datan_report::RowKind::Data,
            ],
            truncated: false,
        };

        let formats = std::collections::HashMap::from([
            (
                ObjectId(2),
                formato::Formato::Moneda {
                    simbolo: "€".to_string(),
                    decimales: 2,
                },
            ),
            (ObjectId(3), formato::Formato::Porcentaje { decimales: 1 }),
        ]);
        let series = puntos_combinados(&matrix, 1, TOPE, &formats);

        assert!(matriz_tiene_filas_de_datos(&matrix));
        assert_eq!(series.total, 3);
        assert_eq!(matrix.row_count(), 4);
        assert_eq!(series.puntos.len(), 3);
        assert_eq!(series.puntos[0].clave_categoria, ["Enero"]);
        assert_eq!(
            (series.puntos[0].barras, series.puntos[0].linea),
            (120.0, 0.2)
        );
        assert_eq!(series.puntos[1].clave_categoria, ["Febrero"]);
        assert_eq!(
            (series.puntos[1].barras, series.puntos[1].linea),
            (60.0, 0.9)
        );
        assert_eq!(series.puntos[2].clave_categoria, ["Marzo"]);
        assert_eq!(
            (series.puntos[2].barras, series.puntos[2].linea),
            (100.0, 0.4)
        );
        assert_eq!(rango_barras_combinadas(&series.puntos), (0.0, 120.0));
        assert_eq!(rango_serie_combinada(&series.puntos), (0.2, 0.9));
        assert_eq!(
            tooltip_combinado(&series.puntos[0], "Ventas", "Margen"),
            "Enero · Ventas: €120,00 · Margen: 20,0%"
        );
        let total_only = Matrix {
            headers: Vec::new(),
            rows: vec![vec![
                "Total".to_string(),
                "180".to_string(),
                "0.7".to_string(),
            ]],
            kinds: vec![datan_report::RowKind::GrandTotal],
            truncated: false,
        };
        assert!(!matriz_tiene_filas_de_datos(&total_only));
    }

    #[test]
    fn combinado_limita_ambas_series_con_las_mismas_categorias() {
        let rows: Vec<Vec<String>> = (1..=10)
            .map(|index| {
                vec![
                    format!("C{index}"),
                    index.to_string(),
                    (index * 10).to_string(),
                ]
            })
            .collect();
        let matrix = Matrix {
            headers: Vec::new(),
            rows,
            kinds: vec![datan_report::RowKind::Data; 10],
            truncated: false,
        };

        let series = puntos_combinados(&matrix, 1, 8, &std::collections::HashMap::new());

        assert_eq!(series.total, 10);
        assert_eq!(series.puntos.len(), 8);
        assert_eq!(
            series.puntos.first().map(|point| point.etiqueta.as_str()),
            Some("C1")
        );
        assert_eq!(
            series.puntos.last().map(|point| point.etiqueta.as_str()),
            Some("C8")
        );
        assert!(
            series
                .puntos
                .iter()
                .all(|point| point.linea == point.barras * 10.0)
        );
    }

