    #[test]
    fn borrar_medida_limpia_pagina_visuales_y_bookmarks_incluido_top_n() {
        let measure = ObjectId(41);
        let mut page = pagina_inicial("Página 1".to_string(), vista("Barras"));
        page.vista.selection.measures.push(measure);
        page.vista.top_n = Some(datan_report::TopN {
            measure,
            count: 5,
            abajo: false,
        });
        page.visuales[0].vista.selection.measures.push(measure);
        page.visuales[0].vista.top_n = page.vista.top_n;
        page.bookmarks.push(BookmarkState {
            nombre: "Antes".to_string(),
            filtros: Vec::new(),
            visuales: page.visuales.clone(),
            visual_activo: page.visual_activo.clone(),
        });

        page.quitar_medida(measure);

        assert!(page.vista.selection.measures.is_empty());
        assert!(page.vista.top_n.is_none());
        assert!(page.visuales[0].vista.selection.measures.is_empty());
        assert!(page.visuales[0].vista.top_n.is_none());
        assert!(
            page.bookmarks[0].visuales[0]
                .vista
                .selection
                .measures
                .is_empty()
        );
        assert!(page.bookmarks[0].visuales[0].vista.top_n.is_none());
    }

