    #[test]
    fn countrows_de_la_misma_tabla_es_una_sola_metrica() {
        let model = Model {
            tables: vec![Table {
                id: ObjectId(1),
                name: "ventas".to_string(),
                kind: TableKind::Facts,
                columns: vec![
                    Column::new(ObjectId(10), "cliente", DataType::Text),
                    Column::new(ObjectId(11), "producto", DataType::Text),
                ],
                key_columns: vec![],
                is_date_table: false,
            }],
            measures: vec![],
            relationships: vec![],
        };
        let metric = |column: &str| {
            SavedColorMetric::Implicit(datan_report::saved::SavedImplicitMeasure {
                column: datan_report::saved::SavedColumnRef::Qualified {
                    table: "ventas".into(),
                    column: column.into(),
                },
                aggregation: datan_report::saved::SavedAggregation::CountRows,
                table: Some("ventas".into()),
            })
        };
        let client_count = metric("cliente");
        let product_count = metric("producto");
        assert!(metricas_color_equivalentes(
            &model,
            &client_count,
            &product_count
        ));
        assert_eq!(
            cargar_colores_condicionales(&model, Some(&client_count), Some(&product_count),),
            (Some(client_count), None)
        );
    }

    #[test]
    fn color_condicional_usa_colores_configurados_y_ignora_no_finitos() {
        let format = SavedFormato {
            color_estado_favorable: 0x1256ab,
            color_estado_desfavorable: 0xb13247,
            ..Default::default()
        };

        assert_eq!(color_condicional_por_signo(format, -0.01), Some(0xb13247));
        assert_eq!(color_condicional_por_signo(format, 0.0), Some(0x1256ab));
        assert_eq!(color_condicional_por_signo(format, 20.0), Some(0x1256ab));
        assert_eq!(color_condicional_por_signo(format, f64::NAN), None);
        assert_eq!(color_condicional_por_signo(format, f64::INFINITY), None);
    }

    #[test]
    fn color_condicional_solo_se_expone_en_visuales_con_marcas_coloreables() {
        for kind in [
            "KPI",
            "Tarjetas",
            "Barras",
            "Columnas",
            "Anillo",
            "Dispersion",
            "Lineas",
            "Area",
            "Radar",
        ] {
            assert!(super::visual_admite_color_condicional(kind), "{kind}");
        }
        for kind in ["Tabla", "Matriz", "Medidor", "Candlestick"] {
            assert!(!super::visual_admite_color_condicional(kind), "{kind}");
        }
    }

