    #[test]
    fn anillo_usa_colores_guardados_por_categoria_y_prioriza_reglas_condicionales() {
        let points = vec![
            super::Punto {
                indice: 0,
                etiqueta: "Hogar".into(),
                clave_categoria: vec!["Hogar".into()],
                valor: 12.0,
                color_condicional: None,
                formato: None,
                detalles: Vec::new(),
            },
            super::Punto {
                indice: 1,
                etiqueta: "Moda".into(),
                clave_categoria: vec!["Moda".into()],
                valor: 8.0,
                color_condicional: Some(0xdc2626),
                formato: None,
                detalles: Vec::new(),
            },
        ];
        let colors = [
            ("Hogar".to_string(), 0x0d9488),
            ("Moda".to_string(), 0xea580c),
        ]
        .into_iter()
        .collect();

        let colored = super::puntos_con_colores_categoria(&points, &colors);

        assert_eq!(colored[0].color_condicional, Some(0x0d9488));
        assert_eq!(colored[1].color_condicional, Some(0xdc2626));
        assert_eq!(points[0].color_condicional, None);
    }

